import type { RouteSectionProps } from "@solidjs/router";
import { Ssgoi } from "@ssgoi/solid";
import { createSignal, onCleanup, Show } from "solid-js";
import { rootConfig } from "~/lib/ssgoi-config";
import { cn } from "~/lib/utils";
import { Fab } from "./fab";
import { MagicNav } from "./magic-nav";
import type { NavKey } from "./sidebar";
import { Sidebar } from "./sidebar";
import { TopBar } from "./top-bar";

/* ── Zone detection ──────────────────────────────────────────────── */

type Zone = "shell" | "flow" | "auth";

const ZONE_MAP: Record<string, Zone> = {
  "/": "shell",
  "/transactions": "shell",
  "/pengaturan": "shell",
  "/transaction-new": "flow",
  "/payment": "flow",
  "/receipt": "flow",
  "/login": "auth",
  "/register": "auth",
  "/pin": "auth",
};

const navFromPath = (pathname: string): NavKey => {
  if (pathname === "/") {
    return "home";
  }
  if (pathname === "/transactions") {
    return "transactions";
  }
  if (pathname === "/pengaturan") {
    return "settings";
  }
  return "home";
};

/* ── AppShell ────────────────────────────────────────────────────── */

export const AppShell = (props: RouteSectionProps) => {
  const pathname = () => props.location.pathname;
  const zone = (): Zone => ZONE_MAP[pathname()] ?? "shell";
  const isShell = () => zone() === "shell";
  const activeNav = () => navFromPath(pathname());

  /* ── Expandable sidebar ── */
  const [expanded, setExpanded] = createSignal(false);
  let expandTimer: ReturnType<typeof setTimeout> | undefined;

  const touchSidebar = () => {
    setExpanded(true);
    clearTimeout(expandTimer);
    expandTimer = setTimeout(() => setExpanded(false), 1200);
  };

  const closeSidebar = () => {
    if (expanded()) {
      setExpanded(false);
      clearTimeout(expandTimer);
    }
  };

  onCleanup(() => clearTimeout(expandTimer));

  return (
    <div class="bg-card">
      <Sidebar
        activeNav={activeNav()}
        expanded={expanded()}
        isShell={isShell()}
        onClose={closeSidebar}
        onTouch={touchSidebar}
      />

      <TopBar
        expanded={expanded()}
        isShell={isShell()}
        onClose={closeSidebar}
      />

      {/* ── Main content area ── margins snap, SSGOI masks the change */}
      <main
        class={cn(
          "relative flex flex-1 flex-col overflow-hidden bg-background transition-[margin-left] duration-300",
          isShell() && "mt-[54px] h-[calc(100vh-54px)]",
          isShell() && expanded() ? "ml-[200px]" : "ml-[80px]",
          !isShell() && "ml-0 h-screen",
          "max-[900px]:ml-0"
        )}
        onPointerDown={closeSidebar}
      >
        <Ssgoi config={rootConfig}>{props.children}</Ssgoi>
      </main>

      {/* ── Shell-only chrome ── */}
      <Show when={isShell()}>
        <Fab />
        <MagicNav active={activeNav()} />
      </Show>
    </div>
  );
};

import { A } from "@solidjs/router";
import { motion } from "motion-solidjs";
import { For, Show } from "solid-js";
import { FileIcon, HomeIcon, LogoutIcon, SettingsIcon } from "~/assets";
import { Button } from "~/components/ui/button";
import { cn } from "~/lib/utils";

export type NavKey = "home" | "transactions" | "settings";

const navItems: readonly {
  key: NavKey;
  Icon: typeof HomeIcon;
  label: string;
  href: string;
}[] = [
  { key: "home", Icon: HomeIcon, label: "Home", href: "/" },
  {
    key: "transactions",
    Icon: FileIcon,
    label: "Transaksi",
    href: "/transactions",
  },
  {
    key: "settings",
    Icon: SettingsIcon,
    label: "Pengaturan",
    href: "/pengaturan",
  },
] as const;

interface SidebarProps {
  readonly activeNav: NavKey;
  readonly expanded: boolean;
  readonly isShell: boolean;
  readonly onClose: () => void;
  readonly onTouch: () => void;
}

export const Sidebar = (props: SidebarProps) => {
  return (
    <motion.nav
      animate={{
        x: props.isShell ? 0 : -80,
        opacity: props.isShell ? 1 : 0,
        pointerEvents: props.isShell ? "auto" : "none",
        width: props.isShell && props.expanded ? 200 : 80,
      }}
      class="fixed top-0 left-0 z-[100] flex h-screen flex-col overflow-hidden border-border border-r bg-card px-3 py-5 pb-4 max-[900px]:hidden"
      initial={{ x: -80, opacity: 0, width: 80 }}
      onClick={props.onTouch}
      transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1], delay: 0.05 }}
    >
      {/* Brand */}
      <div class="mb-7 flex h-12 shrink-0 items-center gap-2.5">
        <div class="grid h-12 w-12 shrink-0 place-items-center rounded-[14px]">
          <img
            alt="Nata POS"
            class="h-full w-full object-contain"
            src="/logo.png"
          />
        </div>
        <Show when={props.expanded}>
          <span class="whitespace-nowrap font-bold font-display text-[20px] text-foreground tracking-tight">
            Nata POS
          </span>
        </Show>
      </div>
      <div class="flex flex-1 flex-col justify-center gap-2">
        <For each={navItems}>
          {(item) => {
            const isActive = () => props.activeNav === item.key;
            return (
              <Button
                aria-label={item.label}
                as={A}
                class={cn(
                  "relative flex h-[58px] items-center justify-start gap-[7px] rounded-[14px] transition-[width,padding] duration-300 [&>svg]:transition-transform [&>svg]:duration-150 hover:[&>svg]:scale-108",
                  props.expanded ? "w-full px-3" : "w-[52px] px-[15px]"
                )}
                end={item.key === "home"}
                href={item.href}
                look="ghost"
                size="none"
                tone={isActive() ? "primary" : "neutral"}
              >
                <Show when={isActive()}>
                  <span
                    aria-hidden="true"
                    class="absolute top-1/2 left-[-12px] h-6 w-[4px] -translate-y-1/2 rounded-r-full bg-accent-foreground dark:bg-accent"
                  />
                </Show>
                <item.Icon class="h-[22px] w-[22px] shrink-0" />
                <Show when={props.expanded}>
                  <span class="whitespace-nowrap font-semibold text-[9px] uppercase leading-none tracking-[0.06em]">
                    {item.label}
                  </span>
                </Show>
              </Button>
            );
          }}
        </For>
      </div>

      {/* Logout */}
      <Button
        aria-label="Keluar"
        class={cn(
          "flex h-[58px] items-center justify-start gap-[7px] rounded-[14px] transition-[width,padding] duration-300 [&>svg]:transition-transform [&>svg]:duration-150 [&>svg]:hover:translate-x-0.5",
          props.expanded ? "mb-1 w-full px-3" : "mb-1 w-[52px] px-[15px]"
        )}
        look="ghost"
        size="none"
        tone="destructive"
        type="button"
      >
        <LogoutIcon class="h-[22px] w-[22px] shrink-0" />
        <Show when={props.expanded}>
          <span class="whitespace-nowrap font-semibold text-[9px] uppercase leading-none tracking-[0.06em]">
            Keluar
          </span>
        </Show>
      </Button>
    </motion.nav>
  );
};

import { motion } from "motion-solidjs";
import { createSignal, onCleanup } from "solid-js";
import { BellIcon, CloudIcon, LoaderIcon } from "~/assets";
import { cn } from "~/lib/utils";

function formatClock(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

const TopBarContent = () => {
  const [clock, setClock] = createSignal(formatClock());
  const [syncing, setSyncing] = createSignal(false);

  const timer = setInterval(() => setClock(formatClock()), 1000);
  onCleanup(() => clearInterval(timer));

  const handleSync = () => {
    if (syncing()) {
      return;
    }
    setSyncing(true);
    setTimeout(() => setSyncing(false), 1800);
  };

  return (
    <>
      <div class="flex items-center gap-3">
        <button
          aria-label="Sinkronisasi"
          class="inline-flex items-center gap-[7px] rounded-full border border-accent-foreground/15 bg-accent/15 px-3.5 py-1.5 font-medium text-[13px] text-accent-foreground tracking-[0.01em] transition-[background,border-color,transform] duration-200 hover:border-accent-foreground/25 hover:bg-accent/25 active:scale-[0.96] dark:border-accent/30 dark:text-accent dark:hover:border-accent/50"
          onClick={handleSync}
          type="button"
        >
          <span class="relative h-4 w-4 shrink-0">
            {syncing() ? (
              <LoaderIcon class="h-4 w-4 animate-spin" />
            ) : (
              <>
                <CloudIcon class="h-4 w-4" />
                <span class="absolute -right-0.5 -bottom-px h-[7px] w-[7px] animate-[pulse-dot_2s_ease-in-out_infinite] rounded-full border-[1.5px] border-primary bg-accent dark:border-accent/40" />
              </>
            )}
          </span>
          {syncing() ? "Sinkronisasi\u2026" : "Online"}
        </button>

        <span class="font-medium text-[14px] text-muted-foreground tabular-nums">
          {clock()}
          <span class="ml-1 text-[11px] text-faint-foreground tracking-[0.02em]">
            WIB
          </span>
        </span>
      </div>

      <button
        aria-label="Notifikasi"
        class="grid h-[38px] w-[38px] place-items-center rounded-[8px] border border-border bg-card text-muted-foreground transition-[background,border-color,box-shadow] duration-150 hover:border-primary/15 hover:bg-muted hover:shadow-card-hover"
        type="button"
      >
        <BellIcon class="h-[18px] w-[18px]" />
      </button>
    </>
  );
};

interface TopBarProps {
  readonly expanded: boolean;
  readonly isShell: boolean;
  readonly onClose: () => void;
}

export const TopBar = (props: TopBarProps) => (
  <motion.header
    animate={{
      x: props.isShell ? 0 : -80,
      opacity: props.isShell ? 1 : 0,
      pointerEvents: props.isShell ? "auto" : "none",
    }}
    class={cn(
      "fixed top-0 right-0 z-[99] flex h-[54px] shrink-0 items-center justify-between border-border border-b bg-card px-7 transition-[left] duration-300 max-[900px]:left-0 max-[900px]:px-[18px]",
      props.isShell && (props.expanded ? "left-[200px]" : "left-[80px]"),
      !props.isShell && "left-0"
    )}
    initial={{ x: -80, opacity: 0 }}
    onPointerDown={props.onClose}
    transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1], delay: 0.12 }}
  >
    <TopBarContent />
  </motion.header>
);

import { A } from "@solidjs/router";
import { PlusIcon } from "~/assets";

export const Fab = () => (
  <div class="fixed right-7 bottom-7 z-[90] max-[900px]:hidden">
    <A
      aria-label="Buat Transaksi"
      class="relative flex h-14 animate-[fab-pulse_2.8s_ease-in-out_infinite] items-center gap-2.5 rounded-[10px] bg-primary px-7 font-semibold text-[15px] text-primary-foreground tracking-[0.02em] shadow-card transition-[transform,box-shadow] duration-200 [transition-timing-function:cubic-bezier(0.34,1.56,0.64,1)] hover:translate-y-[-3px] hover:scale-[1.03] hover:animate-none hover:shadow-card-hover active:translate-y-0 active:scale-[0.98] active:shadow-card active:duration-100 dark:animate-[fab-pulse-dark_2.8s_ease-in-out_infinite] dark:hover:animate-none"
      href="/transaction-new"
    >
      <PlusIcon class="h-5 w-5" />
      Buat Transaksi
    </A>
  </div>
);

