import { FadeIn } from "~/components/ui/fade-in";
import { useOrientation } from "~/lib/use-orientation";
import { EarningsCard } from "./components/earnings-card";
import { KpiCards } from "./components/kpi-cards";
import { QuickActions } from "./components/quick-actions";
import { VenueCard } from "./components/venue-card";

/* Stagger orchestration */
const STAGGER = 0.07;

export default function Dashboard() {
  const isPortrait = useOrientation();
  const enable = () => !isPortrait();
  return (
    <div
      class="scrollbar-none relative flex flex-1 flex-col overflow-y-auto bg-banner-to"
      data-ssgoi-transition="/"
    >
      {/* Banner zone */}
      <div class="relative flex shrink-0 flex-col gap-3 px-[18px] pt-3.5 pb-10 md:px-6 md:pt-4 md:pb-24">
        <FadeIn delay={STAGGER * 0} duration={0.45} enable={enable()} y={12}>
          <VenueCard />
        </FadeIn>
        <FadeIn delay={STAGGER * 1} duration={0.45} enable={enable()} y={12}>
          <EarningsCard />
        </FadeIn>
      </div>

      {/* Content body — slides up into the banner */}
      <FadeIn
        class="relative z-10 -mt-6 flex flex-1 flex-col gap-5 rounded-t-3xl bg-background px-[18px] py-7 pb-[105px] md:-mt-14 md:gap-6 md:rounded-t-[60px] md:px-6 md:py-9"
        delay={STAGGER * 2}
        duration={0.55}
        enable={enable()}
        y={40}
      >
        <FadeIn delay={STAGGER * 4} duration={0.4} enable={enable()} y={14}>
          <QuickActions />
        </FadeIn>
        <FadeIn delay={STAGGER * 6} duration={0.4} enable={enable()} y={14}>
          <KpiCards />
        </FadeIn>
      </FadeIn>
    </div>
  );
}

import { type JSX, Show, splitProps } from "solid-js";

type FadeInProps = Omit<JSX.HTMLAttributes<HTMLDivElement>, "style"> & {
  /** Seconds to wait before starting */
  delay?: number;
  /** Animation duration in seconds */
  duration?: number;
  /** Initial vertical offset in px (animates to 0) */
  y?: number;
  /** Initial horizontal offset in px (animates to 0) */
  x?: number;
  /** Initial scale (animates to 1). e.g. 0.97 for a subtle grow */
  scale?: number;
  /** Enable the entrance animation (default: true). Set to false to render
   * children without animation — useful where an SSGOI page transition
   * already carries the motion (e.g. portrait x-slide). */
  enable?: boolean;
  style?: JSX.CSSProperties;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";

/**
 * Entrance fade animation using CSS keyframes.
 *
 * On `animationend` the `animation` property is stripped so the element
 * settles at its natural CSS state (opacity: 1, no transform). This is
 * essential for SSGOI: when the page is cloned via `cloneNode(true)` for
 * the OUT transition, there is no animation to replay and no WAAPI state
 * to lose — unlike `motion-solidjs`, whose WAAPI animations vanish on
 * clone and leave elements stuck at their invisible `initial` state.
 */
export function FadeIn(props: FadeInProps) {
  const [local, rest] = splitProps(props, [
    "delay",
    "duration",
    "y",
    "x",
    "scale",
    "enable",
    "style",
    "class",
    "onAnimationEnd",
    "children",
  ]);

  const enabled = () => local.enable ?? true;

  return (
    <Show
      fallback={
        <div {...rest} class={local.class} style={local.style}>
          {local.children}
        </div>
      }
      when={enabled()}
    >
      <div
        {...rest}
        class={local.class}
        onAnimationEnd={(e) => {
          e.currentTarget.style.animation = "none";
          if (typeof local.onAnimationEnd === "function") {
            (local.onAnimationEnd as (e: AnimationEvent) => void)(e);
          }
        }}
        style={{
          "--enter-y": `${local.y ?? 12}px`,
          "--enter-x": `${local.x ?? 0}px`,
          "--enter-scale": `${local.scale ?? 1}`,
          animation: `${local.duration ?? 0.45}s ${EASE} ${local.delay ?? 0}s both ssgoi-enter`,
          ...local.style,
        }}
      >
        {local.children}
      </div>
    </Show>
  );
}

import { For } from "solid-js";
import {
  CreditCardIcon,
  DollarSignIcon,
  FileIcon,
  InfoIcon,
  MonitorIcon,
  SettingsIcon,
  StoreIcon,
  UsersIcon,
} from "~/assets";
import { Button } from "~/components/ui/button";
import { cn } from "~/lib/utils";

export type SectionKey =
  | "bisnis"
  | "umum"
  | "pajak"
  | "pembayaran"
  | "struk"
  | "tim"
  | "perangkat"
  | "tentang";

const NAV_ITEMS: readonly {
  readonly key: SectionKey;
  readonly label: string;
  readonly Icon: typeof StoreIcon;
}[] = [
  { key: "bisnis", label: "Bisnis", Icon: StoreIcon },
  { key: "umum", label: "Umum", Icon: SettingsIcon },
  { key: "pajak", label: "Pajak & Biaya", Icon: DollarSignIcon },
  { key: "pembayaran", label: "Pembayaran", Icon: CreditCardIcon },
  { key: "struk", label: "Struk", Icon: FileIcon },
  { key: "tim", label: "Kasir & Tim", Icon: UsersIcon },
  { key: "perangkat", label: "Perangkat", Icon: MonitorIcon },
  { key: "tentang", label: "Tentang", Icon: InfoIcon },
] as const;

interface SettingsNavProps {
  readonly active: SectionKey;
  readonly onSelect: (key: SectionKey) => void;
}

export function SettingsNav(props: SettingsNavProps) {
  return (
    <nav class="flex w-[220px] shrink-0 flex-col gap-0.5 gap-y-2 max-[900px]:w-full max-[900px]:flex-row max-[900px]:gap-1">
      <For each={NAV_ITEMS}>
        {(item) => {
          const isActive = () => props.active === item.key;
          return (
            <Button
              aria-label={item.label}
              class="flex items-center gap-2.5 rounded-[10px] px-3.5 py-2.5 text-left font-semibold text-body-sm max-[900px]:whitespace-nowrap max-[900px]:px-3 max-[900px]:py-2 max-[900px]:text-caption"
              look={isActive() ? "soft" : "ghost"}
              onClick={() => props.onSelect(item.key)}
              size="none"
              tone="primary"
              type="button"
            >
              <item.Icon
                class={cn(
                  "h-[18px] w-[18px] shrink-0",
                  isActive()
                    ? "text-primary"
                    : "opacity-55 transition-[opacity] duration-150 hover:opacity-80 dark:opacity-40"
                )}
              />
              {item.label}
            </Button>
          );
        }}
      </For>
    </nav>
  );
}

import * as ButtonPrimitive from "@kobalte/core/button";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import type { VariantProps } from "class-variance-authority";
import { cva } from "class-variance-authority";
import type { JSX, ValidComponent } from "solid-js";
import { splitProps } from "solid-js";

import { cn } from "~/lib/utils";

/**
 * Composable button system.
 *
 *   look × tone × size  →  5 × 3 × 9 = 135 combinations from 17 definitions.
 *
 * ┌──────────┬──────────────────────────────────────────────────────┐
 * │ look     │ solid | soft | outline | ghost | link                │
 * │ tone     │ primary | destructive | neutral                     │
 * │ size     │ xs | sm | md | lg | xl | icon | icon-sm | icon-xs   │
 * │          │ | none                                              │
 * └──────────┴──────────────────────────────────────────────────────┘
 *
 * Migration from old variants:
 *   default           → look="solid"  tone="primary"
 *   destructive       → look="solid"  tone="destructive"
 *   outline           → look="outline" tone="neutral"
 *   outline-primary   → look="outline" tone="primary"
 *   secondary         → look="soft"   tone="neutral"
 *   ghost             → look="ghost"  tone="neutral"
 *   link              → look="link"   tone="primary"
 *   card / card-active           → outline/soft + tone="primary" + class
 *   pill / pill-highlight / ...  → outline/soft/solid + tone="primary" + class
 *   card-accent / card-accent-active → outline/soft + tone="primary" + class
 */
export const buttonVariants = cva(
  "inline-flex cursor-pointer items-center gap-2 whitespace-nowrap rounded-sm font-medium font-sans text-sm transition-[background,border-color,box-shadow,transform,color] duration-standard ease-standard focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-3 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      look: {
        solid: "border-none",
        soft: "border-none",
        outline: "border-[1.5px]",
        ghost: "border-none bg-transparent",
        link: "border-none bg-transparent",
      },
      tone: {
        primary: "",
        destructive: "",
        neutral: "",
      },
      size: {
        xs: "h-8 justify-center px-2.5 text-xs",
        sm: "h-9 justify-center px-3 text-xs",
        md: "h-10 justify-center px-4 py-2",
        lg: "h-12 justify-center px-8 font-semibold",
        xl: "h-[50px] justify-center px-8 font-semibold text-[15px] tracking-[0.02em]",
        icon: "size-10 justify-center",
        "icon-sm": "size-9 justify-center",
        "icon-xs": "size-8 justify-center",
        none: "",
      },
    },
    compoundVariants: [
      /* ── solid ──────────────────────────────────────────────────── */
      {
        look: "solid",
        tone: "primary",
        class:
          "bg-primary text-primary-foreground hover:-translate-y-px hover:bg-primary-hover hover:shadow-[0_4px_12px_rgba(28,58,19,0.25),0_1px_3px_rgba(28,58,19,0.10)] active:translate-y-0 active:bg-primary-active active:shadow-none dark:hover:shadow-[0_6px_20px_rgba(0,0,0,0.45)]",
      },
      {
        look: "solid",
        tone: "destructive",
        class:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
      },

      /* ── soft ───────────────────────────────────────────────────── */
      {
        look: "soft",
        tone: "primary",
        class: "bg-accent-soft text-primary",
      },
      {
        look: "soft",
        tone: "neutral",
        class: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
      },
      {
        look: "soft",
        tone: "destructive",
        class: "bg-destructive/10 text-destructive hover:bg-destructive/15",
      },

      /* ── outline ────────────────────────────────────────────────── */
      {
        look: "outline",
        tone: "primary",
        class:
          "border-primary bg-transparent font-semibold text-primary hover:bg-primary/5 active:scale-[0.98] dark:border-accent dark:text-accent dark:hover:bg-accent/10",
      },
      {
        look: "outline",
        tone: "neutral",
        class:
          "border-input bg-background text-foreground hover:border-muted-foreground hover:bg-muted hover:shadow-[0_2px_8px_rgba(0,0,0,0.06)] active:bg-border/50",
      },
      {
        look: "outline",
        tone: "destructive",
        class:
          "border-destructive/50 bg-transparent text-destructive hover:bg-destructive/10",
      },

      /* ── ghost ──────────────────────────────────────────────────── */
      {
        look: "ghost",
        tone: "primary",
        class: "text-primary hover:bg-foreground/5 dark:text-accent",
      },
      {
        look: "ghost",
        tone: "neutral",
        class:
          "text-muted-foreground hover:bg-foreground/5 hover:text-foreground",
      },
      {
        look: "ghost",
        tone: "destructive",
        class: "text-destructive hover:bg-destructive/10",
      },

      /* ── link ───────────────────────────────────────────────────── */
      {
        look: "link",
        tone: "primary",
        class: "text-primary underline-offset-4 hover:underline",
      },
    ],
    defaultVariants: {
      look: "solid",
      tone: "primary",
      size: "md",
    },
  }
);

export type ButtonProps<T extends ValidComponent = "button"> =
  ButtonPrimitive.ButtonRootProps<T> &
    VariantProps<typeof buttonVariants> & {
      class?: string | undefined;
      children?: JSX.Element;
    };

export const Button = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, ButtonProps<T>>
) => {
  const [local, others] = splitProps(props as ButtonProps, [
    "look",
    "tone",
    "size",
    "class",
  ]);
  return (
    <ButtonPrimitive.Root
      class={cn(
        buttonVariants({
          look: local.look,
          tone: local.tone,
          size: local.size,
        }),
        local.class
      )}
      {...others}
    />
  );
};

