import { createSignal, onCleanup, onMount, type Accessor } from "solid-js";
import { toast } from "solid-sonner";
import { useNavigate } from "@solidjs/router";
import { DIGIT_RE, LOCK_DURATION_MS, MAX_ATTEMPTS, MAX_PIN, type PinUser } from "../types";

interface UsePinAuthOptions {
  readonly user: Accessor<PinUser>;
  readonly onSuccess: () => void;
}

export function usePinAuth(options: UsePinAuthOptions) {
  const navigate = useNavigate();
  const [pin, setPin] = createSignal("");
  const [error, setError] = createSignal("");
  const [attempts, setAttempts] = createSignal(0);
  const [locked, setLocked] = createSignal(false);

  let lockTimer: ReturnType<typeof setTimeout> | undefined;
  onCleanup(() => clearTimeout(lockTimer));

  function resetPin() {
    setPin("");
    setError("");
    setLocked(false);
  }

  function submitPin() {
    if (locked() || pin().length !== MAX_PIN) return;
    if (pin() === options.user().pin) {
      options.onSuccess();
      toast.success(`Selamat datang, ${options.user().name.split(" ")[0]}!`);
      setTimeout(() => navigate("/"), 1200);
    } else {
      const nextAttempts = attempts() + 1;
      setAttempts(nextAttempts);
      if (nextAttempts >= MAX_ATTEMPTS) {
        setLocked(true);
        setError("Terlalu banyak percobaan. Coba lagi nanti.");
        toast.error("Akun terkunci sementara");
        lockTimer = setTimeout(() => {
          setAttempts(0);
          resetPin();
        }, LOCK_DURATION_MS);
      } else {
        setError(`PIN salah (${MAX_ATTEMPTS - nextAttempts} percobaan tersisa)`);
        setTimeout(() => setPin(""), 500);
        setTimeout(() => setError(""), 3000);
      }
    }
  }

  function addDigit(d: string) {
    if (locked() || pin().length >= MAX_PIN) return;
    const next = pin() + d;
    setPin(next);
    if (next.length === MAX_PIN) setTimeout(submitPin, 200);
  }

  function removeDigit() {
    if (locked() || pin().length === 0) return;
    setPin(pin().slice(0, -1));
  }

  function handleKeydown(e: KeyboardEvent) {
    if (DIGIT_RE.test(e.key)) addDigit(e.key);
    else if (e.key === "Backspace") removeDigit();
    else if (e.key === "Enter" && pin().length === MAX_PIN) submitPin();
  }

  onMount(() => {
    window.addEventListener("keydown", handleKeydown);
    onCleanup(() => window.removeEventListener("keydown", handleKeydown));
  });

  return { pin, error, attempts, locked, addDigit, removeDigit };
}
```

