#!/usr/bin/env python3
"""
Migrate max-[Npx]: desktop-first breakpoints → mobile-first min-width variants.

Transformation:
  px-8  max-[900px]:p-6   →   p-6  lg:px-8
  (mobile value becomes base, desktop value gets min-width prefix)

Fold mapping (6 ad-hoc values → 3 breakpoints):
  480 → base (phone IS the default)
  600 → sm   (600px)
  800 → lg   (fold up to 900)
  900 → lg   (900px)
  1100 → xl  (fold up to 1200)
  1200 → xl  (1200px)
"""
import re
import sys
from pathlib import Path

FOLD = {
    '480': 'sm',
    '600': 'sm',
    '800': 'lg',
    '900': 'lg',
    '1100': 'xl',
    '1200': 'xl',
}

BP_ORDER = ['sm', 'lg', 'xl']

DISPLAY_TOKENS = {'hidden', 'block', 'flex', 'grid', 'inline-flex', 'inline-block', 'contents'}
FLEX_DIR_TOKENS = {'flex-row', 'flex-col', 'flex-row-reverse', 'flex-col-reverse'}
FLEX_DIR_OPP = {'flex-col': 'flex-row', 'flex-row': 'flex-col',
                'flex-col-reverse': 'flex-row-reverse', 'flex-row-reverse': 'flex-col-reverse'}


def prop_key(token: str) -> str:
    """Extract a property-matching key from a Tailwind token."""
    t = token.lstrip('-')
    if t in DISPLAY_TOKENS:
        return 'display'
    if t in FLEX_DIR_TOKENS:
        return 'flex-direction'
    if t.startswith('overflow-'):
        # overflow-y-auto and overflow-y-visible conflict
        base = '-'.join(t.split('-')[:2])
        return base
    if t.startswith('grid-cols'):
        return 'grid-cols'
    # Match alphabetic prefix (with hyphens) before value part
    m = re.match(r'^([a-z][a-z-]*?)(?=[\d\[\(\%]|$)', t)
    if m:
        return m.group(1).rstrip('-')
    return t


def transform_class_string(s: str) -> str:
    tokens = s.split()

    desktop = []
    # {bp: [values]} — values with max-[] prefix stripped
    mobile = {}

    for tok in tokens:
        m = re.match(r'max-\[(\d+)px\]:(.+)', tok)
        if m:
            px, val = m.group(1), m.group(2)
            bp = FOLD.get(px)
            if bp:
                mobile.setdefault(bp, []).append(val)
            else:
                print(f"  WARNING: unmapped breakpoint max-[{px}px]")
        else:
            desktop.append(tok)

    if not mobile:
        return s

    used_bps = sorted(mobile.keys(), key=lambda b: BP_ORDER.index(b))

    # Mobile-first prefix assignment:
    #   smallest bp  → base (no prefix)
    #   bp[i]        → prefix bp[i-1]
    #   desktop      → prefix = last bp
    bp_prefix = {}
    for i, bp in enumerate(used_bps):
        bp_prefix[bp] = '' if i == 0 else used_bps[i - 1]
    desktop_prefix = used_bps[-1]

    # Collect all overridden property keys
    overridden = set()
    for bp in used_bps:
        for val in mobile[bp]:
            overridden.add(prop_key(val))

    result = []

    # 1. Base = smallest breakpoint values (no prefix)
    for val in mobile[used_bps[0]]:
        result.append(val)

    # 2. Other breakpoint values get their assigned prefix
    for bp in used_bps[1:]:
        prefix = bp_prefix[bp]
        for val in mobile[bp]:
            result.append(f'{prefix}:{val}' if prefix else val)

    # 3. Desktop tokens — overridden ones get prefix, shared ones stay base
    desktop_has_display = False
    for tok in desktop:
        pk = prop_key(tok)
        if pk in overridden:
            result.append(f'{desktop_prefix}:{tok}' if desktop_prefix else tok)
            if pk == 'display':
                desktop_has_display = True
        else:
            result.append(tok)
            if pk == 'display':
                desktop_has_display = True

    # 4. Special: flex-direction restore
    #    If base has flex-col but desktop has no explicit flex-row, add it
    base_has_flex_dir = any(prop_key(v) == 'flex-direction'
                           for v in mobile.get(used_bps[0], []))
    if base_has_flex_dir:
        dir_val = next(v for v in mobile[used_bps[0]]
                      if prop_key(v) == 'flex-direction')
        if dir_val in FLEX_DIR_OPP:
            result.append(f'{desktop_prefix}:{FLEX_DIR_OPP[dir_val]}')

    # 5. Special: display restore
    #    If base has 'hidden' but desktop has no explicit display, add lg:block
    base_vals = mobile.get(used_bps[0], [])
    if 'hidden' in base_vals and not desktop_has_display:
        result.append(f'{desktop_prefix}:block')

    return ' '.join(result)


def process_file(filepath: str) -> bool:
    path = Path(filepath)
    content = path.read_text()
    changed = False

    # Match class="..." — handles single-line attribute values
    # Also handles class={`...`} template literals (simple case, no ${})
    def replace_class(m):
        nonlocal changed
        prefix = m.group(1)  # class=" or class={"
        quote = m.group(2)   # " or `
        classes = m.group(3)
        suffix = m.group(4)  # " or `}

        if 'max-[' not in classes:
            return m.group(0)

        new_classes = transform_class_string(classes)
        if new_classes != classes:
            changed = True
            return f'{prefix}{quote}{new_classes}{suffix}'
        return m.group(0)

    # Pattern: class="..." or class={`...`}
    pattern = re.compile(
        r'(class=)(["{]+)([^"}]+)(["}]+)',
    )

    new_content = pattern.sub(replace_class, content)

    if changed:
        path.write_text(new_content)
        print(f"  ✓ {filepath}")
    return changed


def main():
    src = Path('src')
    files = sorted(src.rglob('*.tsx'))
    count = 0
    for f in files:
        text = f.read_text()
        if 'max-[' in text:
            if process_file(str(f)):
                count += 1
            else:
                # Check for remaining max-[]
                remaining = re.findall(r'max-\[\d+px\]', text)
                if remaining:
                    print(f"  ⚠ {f} — {len(remaining)} max-[] remaining (no change?)")
    print(f"\nDone: {count} files transformed")


if __name__ == '__main__':
    main()

