import type { NavKey } from "./sidebar";

/* ── Design parameters ───────────────────────────────────────────── */
const BAR_HEIGHT = 64;
const CUTOUT_RADIUS = 33;
const BUTTON_SIZE = 60;
const NOTCH_WIDTH = CUTOUT_RADIUS * 2;

/* ── Parametric SVG path (Kyle Shevlin technique) ──────────────────
   Traces a rectangle with a semicircular notch dipping into the top
   center. sweep-flag=0 curves the arc DOWNWARD into the bar. */
function buildNotchPath(width: number): string {
