import * as shape from 'd3-shape';
import { scale } from 'react-native-size-scaling';

//** Path Line */
const line = (width: number, height: number, centerWidth: number) => {
  const path = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)([
    { x: width / 2 + scale(centerWidth), y: 0 },
    { x: width, y: 0 },
    { x: width, y: height },
    { x: 0, y: height },
    { x: 0, y: 0 },
    { x: width / 2 - scale(centerWidth), y: 0 },
  ]);

  return path;
};

//** Path Line Left*/
const lineLeft = (width: number, height: number, centerWidth: number) => {
  const path = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)([
    { x: scale(centerWidth * 1.9) + scale(10), y: 0 },
    { x: width, y: 0 },
    { x: width, y: height },
    { x: 0, y: height },
    { x: 0, y: 0 },
  ]);

  return path;
};

//** Path Line Right*/
const lineRight = (width: number, height: number, centerWidth: number) => {
  const path = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)([
    { x: width, y: 0 },
    { x: width, y: height },
    { x: 0, y: height },
    { x: 0, y: 0 },
    { x: width - scale(centerWidth * 1.9) - scale(10), y: 0 },
  ]);

  return path;
};

//** Path Line Border Left Right Down */
const lineBorder = (width: number, height: number, centerWidth: number) => {
  const border = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)
    .curve(shape.curveBasis)([
    // right
    { x: width / 2 + scale(centerWidth), y: 0 },
    { x: width - scale(20), y: 0 },
    { x: width - scale(10), y: scale(2) },
    { x: width - scale(2), y: scale(10) },
    { x: width, y: scale(20) },
    { x: width, y: height },
    { x: width, y: height },
    // bottom
    { x: width, y: height },
    { x: 0, y: height },
    // left
    { x: 0, y: height },
    { x: 0, y: height },
    { x: 0, y: scale(20) },
    { x: 0 + scale(2), y: scale(10) },
    { x: 0 + scale(10), y: scale(2) },
    { x: 0 + scale(20), y: 0 },
    { x: width / 2 - scale(centerWidth), y: 0 },
  ]);

  return border;
};

//** Path Line Border Left Right Down */
const lineBorderRight = (
  width: number,
  height: number,
  centerWidth: number
) => {
  const border = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)
    .curve(shape.curveBasis)([
    // right
    { x: width, y: 0 },
    { x: width, y: height },
    { x: width, y: height },
    // bottom
    { x: width, y: height },
    { x: 0, y: height },
    // left
    { x: 0, y: height },
    { x: 0, y: height },
    { x: 0, y: scale(20) },
    { x: 0 + scale(2), y: scale(10) },
    { x: 0 + scale(10), y: scale(2) },
    { x: 0 + scale(20), y: 0 },
    { x: width - scale(centerWidth * 1.9) - scale(10), y: 0 },
  ]);

  return border;
};

//** Path Line Border Left Right Down */
const lineBorderLeft = (width: number, height: number, centerWidth: number) => {
  const border = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)
    .curve(shape.curveBasis)([
    // right
    { x: scale(centerWidth * 1.9) + scale(10), y: 0 },
    { x: width - scale(20), y: 0 },
    { x: width - scale(10), y: scale(2) },
    { x: width - scale(2), y: scale(10) },
    { x: width, y: scale(20) },
    { x: width, y: height },
    { x: width, y: height },
    // bottom
    { x: width, y: height },
    { x: 0, y: height },
    // left
    { x: 0, y: height },
    { x: 0, y: height },
    { x: 0, y: 0 },
  ]);

  return border;
};

//** Path Curved Down Left */
const lineCurved = (iPosition: number, height: number, circle: number) => {
  const position = iPosition;
  const circleWidth = circle + position;
  const trim = (position + circleWidth) / 2;

  const curved = (shape as any)
    .line()
    .x((d: { x: any }) => d.x)
    .y((d: { y: any }) => d.y)
    .curve(shape.curveBasis)([
    { x: position - scale(20), y: 0 }, // border center left
    { x: position - scale(10), y: scale(2) },
    { x: position - scale(2), y: scale(10) },
    { x: position, y: scale(17) },

    { x: trim - scale(25), y: height / 2 + scale(2) },
    { x: trim - scale(10), y: height / 2 + scale(10) },
    { x: trim, y: height / 2 + scale(10) },
    { x: trim + scale(10), y: height / 2 + scale(10) },
    { x: trim + scale(25), y: height / 2 + scale(2) },

    { x: circleWidth, y: scale(17) }, // border center right
    { x: circleWidth + scale(2), y: scale(10) },
    { x: circleWidth + scale(10), y: 0 },
    { x: circleWidth + scale(20), y: 0 },
  ]);

  return curved;
};

export const getPathDown = (
  width: number,
  iHeight: number,
  centerWidth: number,
  borderTopLeftRight = false,
  position: 'CENTER' | 'LEFT' | 'RIGHT'
) => {
  const height = scale(iHeight);
  const circleWidth = scale(centerWidth) + scale(16);

  if (borderTopLeftRight && position === 'LEFT') {
    return `${lineBorderLeft(width, height, centerWidth)} ${lineCurved(
      circleWidth / 3,
      height,
      circleWidth
    )}`;
  }

  if (borderTopLeftRight && position === 'RIGHT') {
    return `${lineBorderRight(width, height, centerWidth)} ${lineCurved(
      width - circleWidth * 1.33,
      height,
      circleWidth
    )}`;
  }

  if (borderTopLeftRight && position === 'CENTER') {
    return `${lineBorder(width, height, centerWidth)} ${lineCurved(
      width / 2 - circleWidth / 2,
      height,
      circleWidth
    )}`;
  }

  if (position === 'LEFT') {
    return `${lineLeft(width, height, centerWidth)} ${lineCurved(
      circleWidth / 3,
      height,
      circleWidth
    )}`;
  }

  if (position === 'RIGHT') {
    return `${lineRight(width, height, centerWidth)} ${lineCurved(
      width - circleWidth * 1.33,
      height,
      circleWidth
    )}`;
  }

  return `${line(width, height, centerWidth)} ${lineCurved(
    width / 2 - circleWidth / 2,
    height,
    circleWidth
  )}`;
};

import React from 'react';
import { Path, Svg } from 'react-native-svg';
import { CurvedBottomBarView } from '../ShadowView';
import { CurvedView } from './model';

const CurvedContainer: CurvedView = (props) => {
  const { style, width, height, bgColor, path, borderColor, borderWidth } =
    props;

  const border =
    borderWidth && borderWidth > 0
      ? { stroke: borderColor, strokeWidth: borderWidth }
      : {};

  return (
    <CurvedBottomBarView style={style}>
      <Svg width={width} height={height}>
        <Path fill={bgColor} {...{ d: path }} {...border} />
      </Svg>
    </CurvedBottomBarView>
  );
};

export const CurvedViewComponent: CurvedView = React.memo(CurvedContainer);

/* eslint-disable @typescript-eslint/no-shadow */
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import React, {
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useState,
} from 'react';
import {
  Dimensions,
  I18nManager,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import { scale } from 'react-native-size-scaling';
import { useDeviceOrientation } from '../../../useDeviceOrientation';
import { getPathDown } from '../../utils/pathDown';
import { getPathUp } from '../../utils/pathUp';
import { CurvedViewComponent } from '../CurvedView/curvedView';
import type { ICurvedBottomBarRef, NavigatorBottomBarProps } from './model';
import { styles } from './styles';
const { width: maxW } = Dimensions.get('window');

const Tab = createBottomTabNavigator();

const BottomBarComponent = React.forwardRef<
  ICurvedBottomBarRef,
  NavigatorBottomBarProps
>((props, ref) => {
  const {
    type = 'DOWN',
    circlePosition = 'CENTER',
    style,
    width = null,
    height = 65,
    circleWidth = 50,
    bgColor = 'gray',
    initialRouteName,
    tabBar,
    renderCircle,
    borderTopLeftRight = false,
    shadowStyle,
    borderColor = 'gray',
    borderWidth = 0,
  } = props;

  const [itemLeft, setItemLeft] = useState<any[]>([]);
  const [itemRight, setItemRight] = useState<any[]>([]);
  const [maxWidth, setMaxWidth] = useState<number>(width || maxW);
  const [isShow, setIsShow] = useState(true);
  const children = props?.children as any[];
  const orientation = useDeviceOrientation();

  useImperativeHandle(ref, () => {
    return { setVisible };
  });

  const setVisible = (visible: boolean) => {
    setIsShow(visible);
  };

  useEffect(() => {
    const { width: w } = Dimensions.get('window');
    if (!width) {
      setMaxWidth(w);
    }
  }, [orientation, width]);

  const _renderButtonCenter = useCallback(
    (focusedTab: string, navigate: any) => {
      const getTab = children.filter(
        (e: any) =>
          e?.props?.position === 'CIRCLE' || e?.props?.position === 'CENTER'
      )[0]?.props?.name;

      return renderCircle({
        routeName: getTab,
        selectedTab: focusedTab,
        navigate: (selectTab: string) => {
          if (selectTab) {
            navigate(selectTab);
          }
        },
      });
    },
    [children, renderCircle]
  );

  useEffect(() => {
    const arrLeft: any = children.filter(
      (item) => item?.props?.position === 'LEFT'
    );
    const arrRight: any = children.filter(
      (item) => item?.props?.position === 'RIGHT'
    );

    setItemLeft(arrLeft);
    setItemRight(arrRight);
  }, [children, initialRouteName]);

  const getCircleWidth = useMemo(() => {
    return circleWidth < 50 ? 50 : circleWidth > 60 ? 60 : circleWidth;
  }, [circleWidth]);

  const getTabbarHeight = useMemo(() => {
    return height < 50 ? 50 : height > 90 ? 90 : height;
  }, [height]);

  const d = useMemo(() => {
    return type === 'DOWN'
      ? getPathDown(
          maxWidth,
          getTabbarHeight,
          getCircleWidth,
          borderTopLeftRight,
          !I18nManager.isRTL
            ? circlePosition
            : circlePosition === 'LEFT'
            ? 'RIGHT'
            : circlePosition === 'RIGHT'
            ? 'LEFT'
            : 'CENTER'
        )
      : getPathUp(
          maxWidth,
          getTabbarHeight + 30,
          getCircleWidth,
          borderTopLeftRight,
          !I18nManager.isRTL
            ? circlePosition
            : circlePosition === 'LEFT'
            ? 'RIGHT'
            : circlePosition === 'RIGHT'
            ? 'LEFT'
            : 'CENTER'
        );
  }, [
    borderTopLeftRight,
    circlePosition,
    getCircleWidth,
    getTabbarHeight,
    maxWidth,
    type,
  ]);

  const renderItem = ({ color, routeName, navigate }: any) => {
    return (
      <TouchableOpacity
        key={routeName}
        style={styles.itemTab}
        onPress={() => navigate(routeName)}
      >
        <Text style={{ color: color }}>{routeName}</Text>
      </TouchableOpacity>
    );
  };

  const _renderTabIcon = useCallback(
    (arr: any[], focusedTab: string, navigation: any) => {
      return (
        <View style={[styles.rowLeft, { height: scale(getTabbarHeight) }]}>
          {arr.map((item: any, index) => {
            const routeName: string = item?.props?.name;

            if (tabBar === undefined) {
              return renderItem({
                routeName,
                color: focusedTab === routeName ? 'blue' : 'gray',
                navigate: navigation.navigate,
              });
            }

            return (
              <View style={styles.flex1} key={index.toString()}>
                {tabBar({
                  routeName,
                  selectedTab: focusedTab,
                  navigate: (selectTab: string) => {
                    if (selectTab !== focusedTab) {
                      navigation.navigate({
                        name: routeName,
                        merge: true,
                      });
                    }
                  },
                })}
              </View>
            );
          })}
        </View>
      );
    },
    [getTabbarHeight, tabBar]
  );

  const renderPosition = useCallback(
    (props: any) => {
      const { state, navigation } = props;
      const focusedTab = state?.routes[state.index].name;

      if (circlePosition === 'LEFT') {
        return (
          <>
            <View style={{ marginLeft: scale(getCircleWidth) / 2 }}>
              {_renderButtonCenter(focusedTab, navigation.navigate)}
            </View>
            {_renderTabIcon(
              [...itemLeft, ...itemRight],
              focusedTab,
              navigation
            )}
          </>
        );
      }

      if (circlePosition === 'RIGHT') {
        return (
          <>
            {_renderTabIcon(
              [...itemLeft, ...itemRight],
              focusedTab,
              navigation
            )}
            <View style={{ marginRight: scale(getCircleWidth) / 2 }}>
              {_renderButtonCenter(focusedTab, navigation.navigate)}
            </View>
          </>
        );
      }

      return (
        <>
          {_renderTabIcon(itemLeft, focusedTab, navigation)}
          {_renderButtonCenter(focusedTab, navigation.navigate)}
          {_renderTabIcon(itemRight, focusedTab, navigation)}
        </>
      );
    },
    [
      _renderButtonCenter,
      _renderTabIcon,
      circlePosition,
      getCircleWidth,
      itemLeft,
      itemRight,
    ]
  );

  const _renderTabContainer = useCallback(
    (props: any) => {
      return (
        <View
          style={[
            styles.main,
            { width: maxWidth },
            type === 'UP' && styles.top30,
          ]}
        >
          {renderPosition(props)}
        </View>
      );
    },
    [maxWidth, renderPosition, type]
  );

  const MyTabBar = useCallback(
    (props: any) => {
      if (!isShow) {
        return null;
      }

      return (
        <View style={[styles.container, style]}>
          <CurvedViewComponent
            style={shadowStyle}
            width={maxWidth}
            height={scale(getTabbarHeight) + (type === 'DOWN' ? 0 : scale(30))}
            bgColor={bgColor}
            path={d}
            borderColor={borderColor}
            borderWidth={borderWidth}
          />
          {_renderTabContainer(props)}
        </View>
      );
    },
    [
      _renderTabContainer,
      bgColor,
      d,
      getTabbarHeight,
      isShow,
      maxWidth,
      shadowStyle,
      style,
      type,
      borderColor,
      borderWidth,
    ]
  );

  const main = useMemo(() => {
    return (
      <Tab.Navigator {...props} tabBar={MyTabBar}>
        {children?.map((e: any) => {
          const Component = e?.props?.component;

          return (
            <Tab.Screen
              options={e?.props?.options}
              key={e?.props?.name}
              name={e?.props?.name}
            >
              {(props) => <Component {...props} />}
            </Tab.Screen>
          );
        })}
      </Tab.Navigator>
    );
  }, [MyTabBar, children, props]);

  return main;
});

export default BottomBarComponent;

