import { A } from "@solidjs/router";
import { For } from "solid-js";
import {
  CashRegisterIcon,
  FileIcon,
  GridIcon,
  HomeIcon,
  SettingsIcon,
} from "~/assets";
import { cn } from "~/lib/utils";
import type { NavKey } from "./sidebar";

/* ── Design parameters ───────────────────────────────────────────── */
const BAR_HEIGHT = 64;
const BUTTON_SIZE = 60;
const BUTTON_RADIUS = BUTTON_SIZE / 2; // 30
const NOTCH_RADIUS = 42; // button radius (30) + gap (12) → uniform clearance
const CENTER_WIDTH = 168; // fixed: notch opening (84) + 42px flat on each side

// Bézier control factor — standard circle approximation constant (0.5523)
