import { A } from "@solidjs/router";
import { createSignal, For, onCleanup, onMount } from "solid-js";
import {
  CashRegisterIcon,
  FileIcon,
  GridIcon,
  HomeIcon,
  SettingsIcon,
} from "~/assets";
import { cn } from "~/lib/utils";
import type { NavKey } from "./sidebar";

/* ── Design parameters ───────────────────────────────────────────── */
const BAR_HEIGHT = 64;
const CUTOUT_RADIUS = 42; // half-width of opening (84px total)
const NOTCH_DEPTH = 54; // how deep the dip goes (deeper than radius for visible bottom gap)
const BUTTON_SIZE = 60;
const NOTCH_WIDTH = CUTOUT_RADIUS * 2;

/* ── Parametric SVG path (Kyle Shevlin technique, smoothed) ───────
   The notch is built from two cubic Béziers instead of a single arc.
   Control points enforce G1 (tangent) continuity where the notch
   meets the flat top edge — horizontal tangents at the entry/exit so
   there is no visible corner, vertical tangents at the bottom center
   for a smooth round dip. */
const ENTRY_CP = CUTOUT_RADIUS * 0.5; // horizontal control distance (flat approach)
const DEPTH_CP = NOTCH_DEPTH * 0.55; // vertical control distance (bottom roundness)

function buildNotchPath(width: number): string {
  const cx = width / 2;
  const lx = cx - CUTOUT_RADIUS;
  const rx = cx + CUTOUT_RADIUS;
  const bottom = NOTCH_DEPTH;
  return [
    `M0,${BAR_HEIGHT}`,
    "L0,0",
    `L${lx},0`,
    // left half: horizontal tangent at top → vertical tangent at bottom
    `C${lx + ENTRY_CP},0 ${cx},${bottom - DEPTH_CP} ${cx},${bottom}`,
    // right half: vertical tangent at bottom → horizontal tangent at top
    `C${cx},${bottom - DEPTH_CP} ${rx - ENTRY_CP},0 ${rx},0`,
    `L${width},0`,
    `L${width},${BAR_HEIGHT}`,
    "Z",
  ].join(" ");
}

interface NotchNavProps {
  readonly active: NavKey;
}

const leftTabs = [
  { key: "home" as NavKey, Icon: HomeIcon, label: "Home", href: "/" },
  {
    key: "transactions" as NavKey,
    Icon: FileIcon,
    label: "Transaksi",
    href: "/transactions",
  },
];

const rightTabs = [
  {
    key: "katalog" as NavKey,
    Icon: GridIcon,
    label: "Katalog",
    href: "/katalog",
  },
  {
    key: "settings" as NavKey,
    Icon: SettingsIcon,
    label: "Pengaturan",
    href: "/pengaturan",
  },
];

export const NotchNav = (props: NotchNavProps) => {
  let navRef: HTMLDivElement | undefined;
  const [barWidth, setBarWidth] = createSignal(0);

  onMount(() => {
    const update = () => {
      if (navRef) {
        setBarWidth(navRef.offsetWidth);
      }
    };
    update();
    const ro = new ResizeObserver(update);
    if (navRef) {
      ro.observe(navRef);
    }
    onCleanup(() => ro.disconnect());
  });

  return (
    <nav
      aria-label="Mobile navigation"
      class="fixed right-0 bottom-0 left-0 z-[100] lg:hidden"
    >
      <div
        class="relative"
        ref={(el) => (navRef = el)}
        style={{ height: `${BAR_HEIGHT}px` }}
      >
        {/* SVG bar with notch */}
        <svg
          aria-hidden="true"
          height={BAR_HEIGHT}
          preserveAspectRatio="none"
          style={{
            "drop-shadow": "0 -2px 8px rgba(0,0,0,0.06)",
            filter: "drop-shadow(0 -2px 8px rgba(0,0,0,0.06))",
          }}
          viewBox={`0 0 ${Math.max(barWidth(), 1)} ${BAR_HEIGHT}`}
          width="100%"
        >
          <path
            d={buildNotchPath(Math.max(barWidth(), 1))}
            fill="var(--color-card)"
          />
        </svg>

        {/* Tab row: 2 left + notch spacer + 2 right */}
        <div class="absolute inset-0 flex items-center">
          <div class="flex flex-1 justify-around">
            <For each={leftTabs}>
              {(tab) => <NavTab active={props.active} tab={tab} />}
            </For>
          </div>
          <div style={{ width: `${NOTCH_WIDTH}px`, "flex-shrink": "0" }} />
          <div class="flex flex-1 justify-around">
            <For each={rightTabs}>
              {(tab) => <NavTab active={props.active} tab={tab} />}
            </For>
          </div>
        </div>
      </div>

      {/* Center floating button */}
      <A
        aria-label="Buat Transaksi"
        class="absolute left-1/2 flex -translate-x-1/2 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-[0_4px_14px_rgba(0,0,0,0.18)] transition-transform duration-200 [transition-timing-function:cubic-bezier(0.34,1.56,0.64,1)] hover:scale-105 active:scale-95 active:duration-75"
        href="/transaction-new"
        style={{
          width: `${BUTTON_SIZE}px`,
          height: `${BUTTON_SIZE}px`,
          bottom: `${BAR_HEIGHT - BUTTON_SIZE / 2 + 4}px`,
        }}
      >
        <CashRegisterIcon class="h-6 w-6" />
      </A>
    </nav>
  );
};

/* ── Individual tab ──────────────────────────────────────────────── */

function NavTab(props: {
  active: NavKey;
  tab: { key: NavKey; Icon: typeof HomeIcon; label: string; href: string };
}) {
  const isActive = () => props.active === props.tab.key;
  return (
    <A
      class="flex flex-col items-center gap-1 no-underline"
      end={props.tab.key === "home"}
      href={props.tab.href}
    >
      <props.tab.Icon
        class={cn(
          "h-[22px] w-[22px] transition-colors duration-200",
          isActive() ? "text-primary dark:text-accent" : "text-faint-foreground"
        )}
      />
      <span
        class={cn(
          "font-medium text-[10px] tracking-[0.02em] transition-colors duration-200",
          isActive() ? "text-foreground" : "text-faint-foreground"
        )}
      >
        {props.tab.label}
      </span>
    </A>
  );
}

