import { For } from "solid-js";
import {
  CreditCardIcon,
  DollarSignIcon,
  FileIcon,
  InfoIcon,
  MonitorIcon,
  SettingsIcon,
  StoreIcon,
  UsersIcon,
} from "~/assets";
import { Button } from "~/components/ui/button";
import { cn } from "~/lib/utils";

export type SectionKey =
  | "bisnis"
  | "umum"
  | "pajak"
  | "pembayaran"
  | "struk"
  | "tim"
  | "perangkat"
  | "tentang";

const NAV_ITEMS: readonly {
  readonly key: SectionKey;
  readonly label: string;
  readonly Icon: typeof StoreIcon;
}[] = [
  { key: "bisnis", label: "Bisnis", Icon: StoreIcon },
  { key: "umum", label: "Umum", Icon: SettingsIcon },
  { key: "pajak", label: "Pajak & Biaya", Icon: DollarSignIcon },
  { key: "pembayaran", label: "Pembayaran", Icon: CreditCardIcon },
  { key: "struk", label: "Struk", Icon: FileIcon },
  { key: "tim", label: "Kasir & Tim", Icon: UsersIcon },
  { key: "perangkat", label: "Perangkat", Icon: MonitorIcon },
  { key: "tentang", label: "Tentang", Icon: InfoIcon },
] as const;

interface SettingsNavProps {
  readonly active: SectionKey;
  readonly onSelect: (key: SectionKey) => void;
}

export function SettingsNav(props: SettingsNavProps) {
  return (
    <nav class="flex w-full shrink-0 flex-row gap-1 gap-y-2 lg:w-[220px] lg:flex-col lg:gap-0.5">
      <For each={NAV_ITEMS}>
        {(item) => {
          const isActive = () => props.active === item.key;
          return (
            <Button
              aria-label={item.label}
              class="flex items-center gap-2.5 whitespace-nowrap rounded-[10px] px-3 py-2 text-left font-semibold text-body-sm text-caption lg:px-3.5 lg:py-2.5"
              look={isActive() ? "soft" : "ghost"}
              onClick={() => props.onSelect(item.key)}
              size="none"
              tone="primary"
              type="button"
            >
              <item.Icon
                class={cn(
                  "h-[18px] w-[18px] shrink-0",
                  isActive()
                    ? "text-primary"
                    : "opacity-55 transition-[opacity] duration-150 hover:opacity-80 dark:opacity-40"
                )}
              />
              {item.label}
            </Button>
          );
        }}
      </For>
    </nav>
  );
}

import {
  ColorModeProvider,
  ColorModeScript,
  createLocalStorageManager,
} from "@kobalte/core";
import { Route, Router } from "@solidjs/router";
import { AppShell } from "./components/layout/app-shell";
import { Toaster } from "./components/ui/toaster";
import Dashboard from "./pages/dashboard";
import Katalog from "./pages/katalog";
import Login from "./pages/login";
import Payment from "./pages/payment";
import Pengaturan from "./pages/pengaturan";
import Pin from "./pages/pin";
import Receipt from "./pages/receipt";
import Register from "./pages/register";
import TransactionNew from "./pages/transaction-new";
import Transactions from "./pages/transactions";

const storageManager = createLocalStorageManager("sakti-theme");

export default function AppRoutes() {
  return (
    <Router
      root={(props) => (
        <>
          <ColorModeScript storageType={storageManager.type} />
          <ColorModeProvider storageManager={storageManager}>
            <AppShell {...props} />
            <Toaster />
          </ColorModeProvider>
        </>
      )}
    >
      <Route component={Dashboard} path="/" />
      <Route component={Transactions} path="/transactions" />
      <Route component={Pengaturan} path="/pengaturan" />
      <Route component={Katalog} path="/katalog" />
      <Route component={TransactionNew} path="/transaction-new" />
      <Route component={Payment} path="/payment" />
      <Route component={Receipt} path="/receipt" />
      <Route component={Login} path="/login" />
      <Route component={Register} path="/register" />
      <Route component={Pin} path="/pin" />
    </Router>
  );
}

import type { SsgoiConfig, SsgoiPathTransition } from "@ssgoi/solid";
import { axis, drill, fade } from "@ssgoi/solid/view-transitions";

/* ── Path groups ─────────────────────────────────────────────────── */

const SHELL_PATHS = ["/", "/transactions", "/katalog", "/pengaturan"] as const;
const AUTH_PATHS = ["/login", "/register", "/pin"] as const;

/* ── Root config factory ───────────────────────────────────────────
   Pure: takes the current orientation so the caller can drive it
   reactively (matchMedia). Portrait screens slide on X (feels like
   swiping pages); landscape screens slide on Y (feels like scrolling
   sections). The axis choice is made per-navigation, not cached at
   module load. */
export function createRootConfig(isPortrait: boolean): SsgoiConfig {
  const shellSlides: SsgoiPathTransition[] = isPortrait
    ? axis({ paths: [...SHELL_PATHS], type: "x", variant: "snappy" })
    : axis({ paths: [...SHELL_PATHS], type: "y", variant: "default" });

  return {
    transitions: [
      // Shell ↔ Shell
      ...shellSlides,

      // Flow → Flow: drill parallax
      drill({ enter: "/payment", exit: "/transaction-new", type: "parallax" }),
      drill({ enter: "/receipt", exit: "/payment", type: "parallax" }),

      // Auth ↔ Auth: fade
      fade({ paths: [...AUTH_PATHS] }),

      // Shell → Flow: drill in (any shell page → transaction-new)
      drill({ enter: "/transaction-new", exit: "/", type: "parallax" }),
      drill({
        enter: "/transaction-new",
        exit: "/transactions",
        type: "parallax",
      }),
      drill({
        enter: "/transaction-new",
        exit: "/pengaturan",
        type: "parallax",
      }),
      drill({
        enter: "/transaction-new",
        exit: "/katalog",
        type: "parallax",
      }),
    ],
  };
}

import type { RouteSectionProps } from "@solidjs/router";
import { Ssgoi } from "@ssgoi/solid";
import { createMemo, createSignal, onCleanup, Show } from "solid-js";
import { createRootConfig } from "~/lib/ssgoi-config";
import { useOrientation } from "~/lib/use-orientation";
import { cn } from "~/lib/utils";
import { Fab } from "./fab";
import { NotchNav } from "./notch-nav";
import type { NavKey } from "./sidebar";
import { Sidebar } from "./sidebar";
import { TopBar } from "./top-bar";

/* ── Zone detection ──────────────────────────────────────────────── */

type Zone = "shell" | "flow" | "auth";

const ZONE_MAP: Record<string, Zone> = {
  "/": "shell",
  "/transactions": "shell",
  "/katalog": "shell",
  "/pengaturan": "shell",
  "/transaction-new": "flow",
  "/payment": "flow",
  "/receipt": "flow",
  "/login": "auth",
  "/register": "auth",
  "/pin": "auth",
};

const navFromPath = (pathname: string): NavKey => {
  if (pathname === "/") {
    return "home";
  }
  if (pathname === "/transactions") {
    return "transactions";
  }
  if (pathname === "/katalog") {
    return "katalog";
  }
  if (pathname === "/pengaturan") {
    return "settings";
  }
  return "home";
};

/* ── AppShell ────────────────────────────────────────────────────── */

export const AppShell = (props: RouteSectionProps) => {
  const pathname = () => props.location.pathname;
  const zone = (): Zone => ZONE_MAP[pathname()] ?? "shell";
  const isShell = () => zone() === "shell";
  const activeNav = () => navFromPath(pathname());

  /* ── Expandable sidebar ── */
  const [expanded, setExpanded] = createSignal(false);
  let expandTimer: ReturnType<typeof setTimeout> | undefined;

  /* ── SSGOI config memo: axis choice (x vs y) tracks orientation.
     SSGOI's own createMemo recreates the transition context when config
     identity changes. Orientation signal is global (use-orientation.ts). */
  const isPortrait = useOrientation();
  const config = createMemo(() => createRootConfig(isPortrait()));

  const touchSidebar = () => {
    setExpanded(true);
    clearTimeout(expandTimer);
    expandTimer = setTimeout(() => setExpanded(false), 1200);
  };

  const closeSidebar = () => {
    if (expanded()) {
      setExpanded(false);
      clearTimeout(expandTimer);
    }
  };

  onCleanup(() => clearTimeout(expandTimer));

  return (
    <div class="bg-card">
      <Sidebar
        activeNav={activeNav()}
        expanded={expanded()}
        isShell={isShell()}
        onClose={closeSidebar}
        onTouch={touchSidebar}
      />

      <TopBar
        expanded={expanded()}
        isShell={isShell()}
        onClose={closeSidebar}
      />

      {/* ── Main content area ── margins snap, SSGOI masks the change */}
      <main
        class={cn(
          "relative flex flex-1 flex-col overflow-hidden bg-background",
          isShell() && "mt-[54px] h-[calc(100vh-54px)]",
          isShell() && (expanded() ? "lg:ml-[200px]" : "lg:ml-[80px]"),
          isShell() &&
            "transition-[margin-left] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
          !isShell() && "h-screen"
        )}
        onPointerDown={closeSidebar}
      >
        <Ssgoi config={config()}>{props.children}</Ssgoi>
      </main>

      {/* ── Shell-only chrome ── */}
      <Show when={isShell() && pathname() !== "/pengaturan"}>
        <Fab />
      </Show>
      <Show when={isShell()}>
        <NotchNav active={activeNav()} />
      </Show>
    </div>
  );
};

import * as ButtonPrimitive from "@kobalte/core/button";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import type { VariantProps } from "class-variance-authority";
import { cva } from "class-variance-authority";
import type { JSX, ValidComponent } from "solid-js";
import { splitProps } from "solid-js";

import { cn } from "~/lib/utils";

/**
 * Composable button system.
 *
 *   look × tone × size  →  5 × 3 × 9 = 135 combinations from 17 definitions.
 *
 * ┌──────────┬──────────────────────────────────────────────────────┐
 * │ look     │ solid | soft | outline | ghost | link                │
 * │ tone     │ primary | destructive | neutral                     │
 * │ size     │ xs | sm | md | lg | xl | icon | icon-sm | icon-xs   │
 * │          │ | none                                              │
 * └──────────┴──────────────────────────────────────────────────────┘
 *
 * Migration from old variants:
 *   default           → look="solid"  tone="primary"
 *   destructive       → look="solid"  tone="destructive"
 *   outline           → look="outline" tone="neutral"
 *   outline-primary   → look="outline" tone="primary"
 *   secondary         → look="soft"   tone="neutral"
 *   ghost             → look="ghost"  tone="neutral"
 *   link              → look="link"   tone="primary"
 *   card / card-active           → outline/soft + tone="primary" + class
 *   pill / pill-highlight / ...  → outline/soft/solid + tone="primary" + class
 *   card-accent / card-accent-active → outline/soft + tone="primary" + class
 */
export const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center gap-2 whitespace-nowrap rounded-sm font-medium font-sans text-sm transition-[background,border-color,box-shadow,transform,color] duration-standard ease-standard focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-3 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      look: {
        solid: "border-none",
        soft: "border-none",
        outline: "border-[1.5px]",
        ghost: "border-none bg-transparent",
        link: "border-none bg-transparent",
      },
      tone: {
        primary: "",
        destructive: "",
        neutral: "",
      },
      size: {
        xs: "h-8 justify-center px-2.5 text-xs",
        sm: "h-9 justify-center px-3 text-xs",
        md: "h-10 justify-center px-4 py-2",
        lg: "h-12 justify-center px-8 font-semibold",
        xl: "h-[50px] justify-center px-8 font-semibold text-[15px] tracking-[0.02em]",
        icon: "size-10 justify-center",
        "icon-sm": "size-9 justify-center",
        "icon-xs": "size-8 justify-center",
        none: "",
      },
    },
    compoundVariants: [
      /* ── solid ──────────────────────────────────────────────────── */
      {
        look: "solid",
        tone: "primary",
        class:
          "bg-primary text-primary-foreground hover:-translate-y-px hover:bg-primary-hover hover:shadow-[0_4px_12px_rgba(28,58,19,0.25),0_1px_3px_rgba(28,58,19,0.10)] active:translate-y-0 active:bg-primary-active active:shadow-none dark:hover:shadow-[0_6px_20px_rgba(0,0,0,0.45)]",
      },
      {
        look: "solid",
        tone: "destructive",
        class:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
      },

      /* ── soft ───────────────────────────────────────────────────── */
      {
        look: "soft",
        tone: "primary",
        class: "bg-accent-soft text-primary",
      },
      {
        look: "soft",
        tone: "neutral",
        class: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
      },
      {
        look: "soft",
        tone: "destructive",
        class: "bg-destructive/10 text-destructive hover:bg-destructive/15",
      },

      /* ── outline ────────────────────────────────────────────────── */
      {
        look: "outline",
        tone: "primary",
        class:
          "border-primary bg-transparent font-semibold text-primary hover:bg-primary/5 active:scale-[0.98] dark:border-accent dark:text-accent dark:hover:bg-accent/10",
      },
      {
        look: "outline",
        tone: "neutral",
        class:
          "border-input bg-background text-foreground hover:border-muted-foreground hover:bg-muted hover:shadow-[0_2px_8px_rgba(0,0,0,0.06)] active:bg-border/50",
      },
      {
        look: "outline",
        tone: "destructive",
        class:
          "border-destructive/50 bg-transparent text-destructive hover:bg-destructive/10",
      },

      /* ── ghost ──────────────────────────────────────────────────── */
      {
        look: "ghost",
        tone: "primary",
        class: "text-primary hover:bg-foreground/5 dark:text-accent",
      },
      {
        look: "ghost",
        tone: "neutral",
        class:
          "text-muted-foreground hover:bg-foreground/5 hover:text-foreground",
      },
      {
        look: "ghost",
        tone: "destructive",
        class: "text-destructive hover:bg-destructive/10",
      },

      /* ── link ───────────────────────────────────────────────────── */
      {
        look: "link",
        tone: "primary",
        class: "text-primary underline-offset-4 hover:underline",
      },
    ],
    defaultVariants: {
      look: "solid",
      tone: "primary",
      size: "md",
    },
  }
);

export type ButtonProps<T extends ValidComponent = "button"> =
  ButtonPrimitive.ButtonRootProps<T> &
    VariantProps<typeof buttonVariants> & {
      class?: string | undefined;
      children?: JSX.Element;
    };

export const Button = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, ButtonProps<T>>
) => {
  const [local, others] = splitProps(props as ButtonProps, [
    "look",
    "tone",
    "size",
    "class",
  ]);
  return (
    <ButtonPrimitive.Root
      class={cn(
        buttonVariants({
          look: local.look,
          tone: local.tone,
          size: local.size,
        }),
        local.class
      )}
      {...others}
    />
  );
};

