import { useLocation, useNavigate } from "@solidjs/router";
import { For } from "solid-js";
import {
  CreditCardIcon,
  DollarSignIcon,
  FileIcon,
  InfoIcon,
  MonitorIcon,
  SettingsIcon,
  StoreIcon,
  UsersIcon,
} from "~/assets";
import { Button } from "~/components/ui/button";
import { useIsWide } from "~/lib/use-is-wide";
import { cn } from "~/lib/utils";

export type SectionKey =
  | "bisnis"
  | "umum"
  | "pajak"
  | "pembayaran"
  | "struk"
  | "tim"
  | "perangkat"
  | "tentang";

export const NAV_ITEMS: readonly {
  readonly key: SectionKey;
  readonly label: string;
  readonly Icon: typeof StoreIcon;
}[] = [
  { key: "bisnis", label: "Bisnis", Icon: StoreIcon },
  { key: "umum", label: "Umum", Icon: SettingsIcon },
  { key: "pajak", label: "Pajak & Biaya", Icon: DollarSignIcon },
  { key: "pembayaran", label: "Pembayaran", Icon: CreditCardIcon },
  { key: "struk", label: "Struk", Icon: FileIcon },
  { key: "tim", label: "Kasir & Tim", Icon: UsersIcon },
  { key: "perangkat", label: "Perangkat", Icon: MonitorIcon },
  { key: "tentang", label: "Tentang", Icon: InfoIcon },
] as const;

export function SettingsNav() {
  const location = useLocation();
  const navigate = useNavigate();
  const isWide = useIsWide();

  const sectionSeg = () => location.pathname.split("/")[2];

  // Desktop index route (/pengaturan) renders Bisnis by default, so it's
  // active. Below lg, the index has no active item — it's a menu screen.
  const activeKey = (): SectionKey | null => {
    const seg = sectionSeg();
    if (seg) {
      return seg as SectionKey;
    }
    return isWide() ? "bisnis" : null;
  };
  return (
    <nav class="flex w-full shrink-0 flex-col gap-0.5 lg:w-[220px]">
      <For each={NAV_ITEMS}>
        {(item) => (
          <Button
            aria-label={item.label}
            class="flex w-full items-center gap-2.5 whitespace-nowrap rounded-[10px] px-4 py-3 text-left font-semibold text-body-sm lg:w-auto lg:px-3.5 lg:py-2.5"
            look={activeKey() === item.key ? "soft" : "ghost"}
            onClick={() =>
              navigate(
                // Below lg: every item (including bisnis) drills into its
                // own sub-route. Desktop: bisnis uses the bare index route.
                item.key === "bisnis" && isWide()
                  ? "/pengaturan"
                  : `/pengaturan/${item.key}`
              )
            }
            size="none"
            tone="primary"
            type="button"
          >
            <item.Icon
              class={cn(
                "h-[18px] w-[18px] shrink-0",
                activeKey() === item.key
                  ? "text-primary"
                  : "opacity-55 transition-[opacity] duration-150 hover:opacity-80 dark:opacity-40"
              )}
            />
            {item.label}
          </Button>
        )}
      </For>
    </nav>
  );
}

import type { RouteSectionProps } from "@solidjs/router";
import { useLocation } from "@solidjs/router";
import { Show } from "solid-js";
import { SubPageShell } from "~/components/layout/sub-page-shell/sub-page-shell";
import { FadeIn } from "~/components/ui/fade-in";
import { useIsWide } from "~/lib/use-is-wide";
import { useOrientation } from "~/lib/use-orientation";
import { NAV_ITEMS, SettingsNav } from "./components/settings-nav";

export default function Pengaturan(props: RouteSectionProps) {
  const isPortrait = useOrientation();
  const isWide = useIsWide();
  const enable = () => !isPortrait();
  const location = useLocation();

  // Section sub-route? (e.g. /pengaturan/umum — not the bare /pengaturan)
  const isSectionRoute = () => {
    const parts = location.pathname.split("/").filter(Boolean);
    return parts.length > 1 && parts[0] === "pengaturan";
  };

  const sectionTitle = () => {
    const seg = location.pathname.split("/")[2];
    return NAV_ITEMS.find((i) => i.key === seg)?.label ?? "Pengaturan";
  };

  return (
    <Show
      fallback={
        /* ── Index route (mobile) or two-column layout (desktop) ── */
        <div
          class="scrollbar-none flex flex-1 flex-col gap-4 overflow-y-auto px-[18px] pt-6 pb-28 lg:gap-5 lg:px-7 lg:pb-24"
          data-ssgoi-transition="/pengaturan"
        >
          <FadeIn duration={0.35} enable={enable()} y={-8}>
            <h1 class="font-bold font-display text-foreground text-heading-sm">
              Pengaturan
            </h1>
            <p class="mt-0.5 text-body-sm text-muted-foreground tracking-[0.02em]">
              Kelola konfigurasi bisnis dan aplikasi Anda
            </p>
          </FadeIn>

          <div class="flex flex-col gap-6 lg:flex-row">
            <FadeIn delay={0.06} duration={0.45} enable={enable()} x={-30}>
              <SettingsNav />
            </FadeIn>

            {/* Desktop only — section panel. Hidden below lg (nav is the menu). */}
            <Show when={isWide()}>
              <FadeIn
                class="flex min-w-0 flex-1 flex-col gap-6"
                delay={0.14}
                duration={0.5}
                enable={enable()}
                scale={0.97}
                x={24}
              >
                <Show keyed when={location.pathname}>
                  {(_) => (
                    <FadeIn
                      duration={0.35}
                      enable={enable()}
                      scale={0.98}
                      x={16}
                    >
                      {props.children}
                    </FadeIn>
                  )}
                </Show>
              </FadeIn>
            </Show>
          </div>
        </div>
      }
      when={!isWide() && isSectionRoute()}
      when={isPortrait() && isSectionRoute()}
    >
      {/* ── Mobile section route → full-screen SubPageShell ── */}
      <SubPageShell
        backHref="/pengaturan"
        data-ssgoi-transition={location.pathname}
        title={sectionTitle()}
      >
        <div class="scrollbar-none flex-1 overflow-y-auto p-5 pb-28">
          {props.children}
        </div>
      </SubPageShell>
    </Show>
  );
}

