   Seed identity lives in the primitives + their values.
   ─────────────────────────────────────────────────────────────────────────── */

@theme {
  /* ── Breakpoints (mobile-first) ── */
  --breakpoint-sm: 37.5rem;  /*  600px — phone → tablet          */
  --breakpoint-lg: 56.25rem; /*  900px — tablet → desktop        */
  --breakpoint-xl: 75rem;    /* 1200px — desktop → large desktop */

  /* ── Custom spacing / height ── */
  --spacing-header: 56px;

