  --color-lime: oklch(0.9356 0.1298 126.62);
  --color-parchment: oklch(0.9897 0.0066 106.52);
  --color-parchment-darker: oklch(0.9650 0.0066 106.52);
  --color-stone: oklch(0.9477 0.0066 106.53);
  --color-sage: oklch(0.8264 0.0053 145.53);
  --color-gray: oklch(0.7668 0.0000 0);

  /* ── Brand banner gradient (auth / PIN surfaces) ── */
  --color-banner-from: oklch(0.3904 0.0789 163.39);
  --color-banner-to: oklch(0.3105 0.0617 164.22);

  /* ── shadcn roles — surfaces & text ── */
  --color-background: var(--color-parchment);
  --color-foreground: var(--color-canopy);
  --color-card: var(--color-parchment-darker);
  --color-card-foreground: var(--color-canopy);
  --color-popover: var(--color-parchment);
  --color-popover-foreground: var(--color-canopy);
  --color-muted: var(--color-stone);
  --color-muted-foreground: oklch(0.4369 0.0376 129.47);
  --color-secondary: var(--color-stone);
  --color-secondary-foreground: var(--color-canopy);
  --color-faint-foreground: oklch(0.5583 0.0324 129.13);

  /* ── shadcn roles — brand & action ── */
  --color-primary: var(--color-canopy);
  --color-primary-foreground: oklch(1.0000 0.0000 0);
  --color-primary-hover: oklch(0.3683 0.0893 138.91);
  --color-primary-active: oklch(0.2617 0.0583 139.50);
  --color-accent: var(--color-lime);
  --color-accent-foreground: var(--color-canopy);
  --color-accent-soft: var(--color-lime);
  --color-danger: oklch(0.5386 0.1937 26.72);
  --color-danger-foreground: oklch(1.0000 0.0000 0);

  /* ── shadcn roles — lines & focus ── */
  --color-border: oklch(0.3146 0.0734 139.03 / 0.12);
  --color-input: var(--color-border);
  --color-ring: var(--color-canopy);

  /* ── Status tones (shadcn has none; seed KPI needs these) ── */
  --color-status-info: oklch(0.5876 0.1389 241.97);
  --color-status-info-foreground: oklch(1.0000 0.0000 0);
  --color-status-success: var(--color-canopy);
  --color-status-success-foreground: oklch(1.0000 0.0000 0);
  --color-status-warning: oklch(0.7701 0.1548 81.06);
  --color-status-warning-foreground: oklch(1.0000 0.0000 0);
  --color-status-danger: oklch(0.5433 0.1740 29.70);
  --color-status-danger-foreground: oklch(1.0000 0.0000 0);
  --color-status-processing: oklch(0.9267 0.1587 100.40);
  --color-status-processing-foreground: oklch(0.4987 0.1019 89.25);

  /* ── Typography ── */
  --font-sans:
    "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, "Segoe UI",
    system-ui, sans-serif;
  --font-display:
    "Bricolage Grotesque", "Archivo Black", "Mulish", "Inter", system-ui,
    sans-serif;
  --font-mono:
    "Roboto Mono", "JetBrains Mono", "IBM Plex Mono", ui-monospace,
    monospace;

  /* ── Typography (v4 bundled: each text-* sets size + leading + tracking) ──
     Body/caption tracking adapted to actual UI usage (audit option A):
     small text runs loose-positive in the real UI; headings stay tight.
     Micro-labels (uppercase status chips, KPI tickers) keep explicit
     tracking-[0.06em]/[0.08em] overrides — intentionally not a base token. */
  --text-caption-sm: 10px;
  --text-caption-sm--line-height: 1.4;
  --text-caption-sm--letter-spacing: 0.02em;

  --text-caption: 12px;
  --text-caption--line-height: 1.4;
  --text-caption--letter-spacing: 0.01em;

  --text-body-sm: 14px;
  --text-body-sm--line-height: 1.4;
  --text-body-sm--letter-spacing: 0.01em;

  --text-body: 16px;
  --text-body--line-height: 1.4;
  --text-body--letter-spacing: 0em;

  --text-body-lg: 18px;
  --text-body-lg--line-height: 1.3;
  --text-body-lg--letter-spacing: -0.01em;

  --text-subheading: 20px;
  --text-subheading--line-height: 1.2;
  --text-subheading--letter-spacing: -0.01em;

  --text-heading-sm: 24px;
  --text-heading-sm--line-height: 1.17;
  --text-heading-sm--letter-spacing: -0.01em;

  --text-heading: 32px;
  --text-heading--line-height: 1.2;
  --text-heading--letter-spacing: -0.01em;

  --text-heading-lg: 40px;
  --text-heading-lg--line-height: 1.1;
  --text-heading-lg--letter-spacing: -0.02em;

  --text-display: 48px;
  --text-display--line-height: 1.1;
  --text-display--letter-spacing: 0.04em;

  /* ── Elevation (canopy-tinted, light mode) ── */
  --shadow-card:
    0 1px 2px oklch(0.3146 0.0734 139.03 / 0.05), 0 8px 24px -10px oklch(0.3146 0.0734 139.03 / 0.12);
  --shadow-card-hover:
    0 2px 6px oklch(0.3146 0.0734 139.03 / 0.06), 0 14px 36px -12px oklch(0.3146 0.0734 139.03 / 0.18);

  /* ── Motion ── */
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --duration-standard: 0.2s;

  --animate-spin: spin 1s linear infinite;
  --animate-ghost-1: ghost-float-1 7s ease-in-out infinite;
  --animate-ghost-2: ghost-float-2 6s ease-in-out infinite;
  --animate-ghost-3: ghost-float-3 8s ease-in-out infinite;
  --animate-ghost-4: ghost-float-4 7.5s ease-in-out infinite;
  --animate-shake: shake 0.5s ease;
  --animate-success-pop: success-pop 0.5s
    cubic-bezier(0.175, 0.885, 0.32, 1.275);
  --animate-avatar-pulse: avatar-pulse 2.5s ease-in-out 1s 2;
  --animate-fade-in: fade-in 0.3s ease;
  --animate-stagger-in: fadeUp 0.35s ease both;
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
  --animate-content-show: content-show 0.2s ease-out;
  --animate-content-hide: content-hide 0.2s ease-out;
}

/* ── Keyframes ── */
@keyframes accordion-down {
  from {
    height: 0;
  }
  to {
    height: var(--kb-accordion-content-height);
  }
}
@keyframes accordion-up {
  from {
    height: var(--kb-accordion-content-height);
  }
  to {
    height: 0;
  }
}
@keyframes content-show {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes content-hide {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.96);
  }
}
@keyframes ghost-float-1 {
  0%,
  100% {
    transform: translateY(0) rotate(-5deg);
  }
  50% {
    transform: translateY(-8px) rotate(-5deg);
  }
}
@keyframes ghost-float-2 {
  0%,
  100% {
    transform: translateY(0) rotate(3deg);
  }
  50% {
    transform: translateY(-8px) rotate(3deg);
  }
}
@keyframes ghost-float-3 {
  0%,
  100% {
    transform: translateY(0) rotate(-2deg);
  }
  50% {
    transform: translateY(-8px) rotate(-2deg);
  }
}
@keyframes ghost-float-4 {
  0%,
  100% {
    transform: translateY(0) rotate(4deg);
  }
  50% {
    transform: translateY(-8px) rotate(4deg);
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes pulse-dot {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}
@keyframes fab-pulse {
  0%,
  100% {
    box-shadow: 0 1px 3px oklch(0.3146 0.0734 139.03 / 0.1);
  }
  50% {
    box-shadow:
      0 1px 3px oklch(0.3146 0.0734 139.03 / 0.1),
      0 0 0 6px oklch(0.3146 0.0734 139.03 / 0.04);
  }
}
@keyframes fab-pulse-dark {
  0%,
  100% {
    box-shadow: 0 4px 16px oklch(0.0000 0.0000 0 / 0.35);
  }
  50% {
    box-shadow:
      0 4px 16px oklch(0.0000 0.0000 0 / 0.35),
      0 0 0 6px oklch(0.9356 0.1298 126.62 / 0.06);
  }
}
@keyframes fadeDown {
  from {
    opacity: 0;
    transform: translateY(-16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* SSGOI-safe entrance: uses CSS vars so cloneNode keeps the final state.
   FadeIn strips this animation on animationend, so the OUT-page clone has
   no animation to replay (WAAPI from motion-solidjs would be lost on clone). */
@keyframes ssgoi-enter {
  from {
    opacity: 0;
    transform: translate(var(--enter-x, 0px), var(--enter-y, 12px)) scale(var(--enter-scale, 1));
  }
  to {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }
}
@keyframes shake {
  0%,
  100% {
    transform: translateX(0);
  }
  15% {
    transform: translateX(-10px);
  }
  30% {
    transform: translateX(10px);
  }
  45% {
    transform: translateX(-8px);
  }
  60% {
    transform: translateX(8px);
  }
  75% {
    transform: translateX(-4px);
  }
  90% {
    transform: translateX(4px);
  }
}
@keyframes success-pop {
  0% {
    transform: scale(0.6);
    opacity: 0;
  }
  50% {
    transform: scale(1.08);
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}
@keyframes avatar-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 oklch(0.9356 0.1298 126.62 / 0.2);
  }
  50% {
    box-shadow: 0 0 0 8px oklch(0.9356 0.1298 126.62 / 0);
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* ── Dark mode (charcoal) — base surfaces + status tones brightened for contrast ── */
@layer theme {
  .dark,
  [data-kb-theme="dark"] {
    --color-background: oklch(19.574% 0.00002 271.152);
    --color-foreground: oklch(0.9461 0.0000 0);
    --color-card: oklch(0.2178 0.0000 0);
    --color-card-foreground: oklch(0.9461 0.0000 0);
    --color-popover: oklch(0.2178 0.0000 0);
    --color-popover-foreground: oklch(0.9461 0.0000 0);
    --color-muted: oklch(0.2520 0.0000 0);
    --color-muted-foreground: oklch(0.6671 0.0176 285.91);
    --color-secondary: oklch(0.2520 0.0000 0);
    --color-secondary-foreground: oklch(0.9461 0.0000 0);
    --color-faint-foreground: oklch(0.61 0.004 285);
    --color-border: oklch(1.0000 0.0000 0 / 0.08);
    --color-danger: oklch(0.63 0.19 27);
    /* Status tones: brightened as text-on-tint; foregrounds deepened so solid
       chips (bg-X text-X-foreground) keep contrast. Measured ≥4.5:1 on #1a1a1a. */
    --color-status-success: oklch(0.74 0.14 140);
    --color-status-success-foreground: oklch(0.30 0.05 140);
    --color-status-warning: oklch(0.88 0.12 81);
    --color-status-warning-foreground: oklch(0.30 0.05 81);
    --color-status-danger: oklch(0.78 0.15 25);
    --color-status-danger-foreground: oklch(0.30 0.08 25);
    --color-status-info: oklch(0.72 0.13 240);
    --color-status-info-foreground: oklch(0.30 0.06 240);

    --color-primary: oklch(0.4 0.1298 126.62);
    --color-primary-foreground: oklch(0.98 0 0);
    --color-primary-hover: oklch(0.45 0.1298 126.62);
    --color-primary-active: oklch(0.35 0.1298 126.62);
    --color-accent-foreground: oklch(0.4 0.1298 126.62);
    --color-accent-soft: oklch(0.9356 0.1298 126.62);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

