import { A } from "@solidjs/router";
import { For, Show } from "solid-js";
import {
  FileIcon,
  GridIcon,
  HomeIcon,
  LogoutIcon,
  SettingsIcon,
} from "~/assets";
import { Button } from "~/components/ui/button";
import { cn } from "~/lib/utils";

export type NavKey = "home" | "transactions" | "katalog" | "settings";

const navItems: readonly {
  key: NavKey;
  Icon: typeof HomeIcon;
  label: string;
  href: string;
}[] = [
  { key: "home", Icon: HomeIcon, label: "Home", href: "/" },
  {
    key: "transactions",
    Icon: FileIcon,
    label: "Transaksi",
    href: "/transactions",
  },
  {
    key: "katalog",
    Icon: GridIcon,
    label: "Katalog",
    href: "/katalog",
  },
  {
    key: "settings",
    Icon: SettingsIcon,
    label: "Pengaturan",
    href: "/pengaturan",
  },
] as const;

interface SidebarProps {
  readonly activeNav: NavKey;
  readonly expanded: boolean;
  readonly isShell: boolean;
  readonly onClose: () => void;
  readonly onTouch: () => void;
}

export const Sidebar = (props: SidebarProps) => {
  return (
    <nav
      class={cn(
        "fixed top-0 left-0 z-[100] h-screen flex-col overflow-hidden border-border border-r bg-card px-3 py-5 pb-4 transition-[width] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
        props.isShell ? "hidden lg:flex" : "hidden",
        props.expanded ? "lg:w-[200px]" : "lg:w-[80px]",
      )}
      onClick={props.onTouch}
    >
      {/* Brand */}
      <div class="mb-7 flex h-12 shrink-0 items-center gap-2.5">
        <div class="grid h-12 w-12 shrink-0 place-items-center rounded-[14px]">
          <img
            alt="Nata POS"
            class="h-full w-full object-contain"
            src="/logo.png"
          />
        </div>
        <Show when={props.expanded}>
          <span class="whitespace-nowrap font-bold font-display text-[20px] text-foreground tracking-tight">
            Nata POS
          </span>
        </Show>
      </div>
      <div class="flex flex-1 flex-col justify-center gap-2">
        <For each={navItems}>
          {(item) => {
            const isActive = () => props.activeNav === item.key;
            return (
              <Button
                aria-label={item.label}
                as={A}
                class={cn(
                  "relative flex h-[58px] items-center justify-start gap-[7px] rounded-[14px] [&>svg]:transition-transform [&>svg]:duration-150 hover:[&>svg]:scale-108",
                  props.expanded ? "w-full px-3" : "w-[52px] px-[15px]",
                )}
                end={item.key === "home"}
                href={item.href}
                look="soft"
                size="none"
                tone={isActive() ? "primary" : "neutral"}
              >
                <Show when={isActive()}>
                  <span
                    aria-hidden="true"
