        <span class="absolute inset-[-1000%] animate-[spin_3s_linear_infinite] bg-[conic-gradient(from_90deg_at_50%_50%,var(--color-accent)_0%,var(--color-primary)_50%,var(--color-accent)_100%)]" />
        {/* Content */}
        <span class="relative flex h-full w-full items-center justify-center rounded-full bg-primary text-primary-foreground">
          <CashRegisterIcon class="h-6 w-6" />
        </span>
      </A>
    </nav>
  );
};

/* ── Individual tab ──────────────────────────────────────────────── */

function NavTab(props: {
  active: NavKey;
  tab: { key: NavKey; Icon: typeof HomeIcon; label: string; href: string };
}) {
  const isActive = () => props.active === props.tab.key;
  return (
    <A
      class="pointer-events-auto flex w-[56px] flex-col items-center justify-center gap-1 no-underline"
      end={props.tab.key === "home"}
      href={props.tab.href}
    >
      <props.tab.Icon
        class={cn(
          "h-[22px] w-[22px] transition-colors duration-200",
          isActive()
            ? "text-primary dark:text-accent"
            : "text-faint-foreground",
        )}
      />
      <span
        class={cn(
          "font-medium text-[10px] tracking-[0.02em] transition-colors duration-200",
          isActive() ? "text-foreground" : "text-faint-foreground",
        )}
      >
        {props.tab.label}
      </span>
    </A>
  );
}

