/* ── Helpers ── */

export function stockStatus(stock: number): {
  status: StockStatus;
  label: string;
  badge: "success" | "warning" | "danger";
} {
  if (stock === 0) return { status: "out", label: "Habis", badge: "danger" };
  if (stock <= 10) return { status: "low", label: "Stok Rendah", badge: "warning" };
  return { status: "available", label: "Tersedia", badge: "success" };
}

export function formatVariantOptions(
  options: readonly VariantOption[],
): string {
  return options
    .map((o) => (o.price > 0 ? `${o.label} (+${o.price.toLocaleString("id-ID")})` : o.label))
    .join(", ");
}

export function getVariantProductNames(
  productIds: readonly number[],
  allProducts: readonly Product[],
): string {
  const names = productIds
    .map((pid) => allProducts.find((p) => p.id === pid)?.name)
    .filter(Boolean) as string[];
  if (names.length === 0) return "Belum ada produk";
  const cap = 3;
  const shown = names.slice(0, cap).join(", ");
  const rest = names.length - cap;
  return rest > 0 ? `${shown} dan ${rest} lainnya` : shown;
}

export function productImage(id: number): string {
  return `https://picsum.photos/seed/sakti-${id}/400/400`;
}

import { A } from "@solidjs/router";
import { createMemo, createSignal, For, Show } from "solid-js";
import { PencilIcon, PlusIcon, SearchIcon, TrashIcon } from "~/assets";
import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import { formatRupiah } from "~/lib/utils";
import {
  type Product,
  categories,
  productImage,
  products,
  stockStatus,
} from "../data";

export function TabProduk() {
  const [search, setSearch] = createSignal("");
  const [activeCat, setActiveCat] = createSignal("all");

  const filtered = createMemo(() => {
    const q = search().toLowerCase();
    const cat = activeCat();
    return products.filter((p) => {
      const matchCat = cat === "all" || p.category === cat;
      const matchQ =
        !q ||
        p.name.toLowerCase().includes(q) ||
        p.sku.toLowerCase().includes(q);
      return matchCat && matchQ;
    });
  });

  return (
    <div class="flex flex-1 flex-col overflow-hidden">
      {/* Search + add */}
      <div class="flex shrink-0 items-center gap-2.5 px-4 pt-3 pb-2 lg:px-6">
        <label class="flex flex-1 items-center gap-2 rounded-xl bg-card px-3.5 py-2 shadow-card">
          <SearchIcon class="h-4 w-4 shrink-0 text-faint-foreground" />
          <input
            class="w-full bg-transparent text-body-sm text-foreground outline-none placeholder:text-faint-foreground"
            onInput={(e) => setSearch(e.currentTarget.value)}
            placeholder="Cari produk atau SKU..."
            type="text"
            value={search()}
          />
        </label>
        <Button as={A} href="#" size="sm">
          <PlusIcon class="h-4 w-4" />
          <span class="hidden sm:inline">Tambah Produk</span>
        </Button>
      </div>

      {/* Category filter pills */}
      <div class="scrollbar-none flex shrink-0 gap-2 overflow-x-auto px-4 pb-3 lg:px-6">
        <Button
          class="flex items-center gap-1.5 rounded-full px-3 py-1.5"
          look={activeCat() === "all" ? "solid" : "outline"}
          onClick={() => setActiveCat("all")}
          size="none"
          tone="primary"
          type="button"
        >
          Semua
          <span class="text-caption-sm opacity-70">
            {products.length}
          </span>
        </Button>
        <For each={categories}>
          {(cat) => (
            <Button
              class="flex items-center gap-1.5 rounded-full px-3 py-1.5"
              look={activeCat() === cat.id ? "solid" : "outline"}
              onClick={() => setActiveCat(cat.id)}
              size="none"
              tone="primary"
              type="button"
            >
              {cat.name}
              <span class="text-caption-sm opacity-70">
                {products.filter((p) => p.category === cat.id).length}
              </span>
            </Button>
          )}
        </For>
      </div>

      {/* Product grid */}
      <div class="scrollbar-none flex-1 overflow-y-auto px-4 pb-28 lg:px-6 lg:pb-6">
        <Show
          fallback={<EmptyState message="Produk tidak ditemukan" subtitle="Coba ubah filter atau kata kunci" />}
          when={filtered().length > 0}
        >
          <div class="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4 lg:gap-4 xl:grid-cols-5">
            <For each={filtered()}>
              {(product) => <ProductCard product={product} />}
            </For>
          </div>
        </Show>
      </div>
    </div>
  );
}

function ProductCard(props: { product: Product }) {
  const s = () => stockStatus(props.product.stock);
  return (
    <div class="group overflow-hidden rounded-2xl border border-border bg-card transition-colors hover:border-primary/20">
      {/* Thumbnail */}
      <div class="relative aspect-square overflow-hidden bg-muted">
        <img
          alt={props.product.name}
          class="h-full w-full object-cover"
          src={productImage(props.product.id)}
        />
        <Badge class="absolute left-2 top-2" size="sm" variant={s().badge}>
          {s().label}
        </Badge>
        <div class="absolute right-2 top-2 flex gap-1">
          <Button
            aria-label={`Edit ${props.product.name}`}
            class="size-8 bg-card p-0 shadow-card"
            look="ghost"
            size="none"
            tone="neutral"
          >
            <PencilIcon class="h-3.5 w-3.5" />
          </Button>
          <Button
            aria-label={`Hapus ${props.product.name}`}
            class="size-8 bg-card p-0 shadow-card"
            look="ghost"
            size="none"
            tone="danger"
          >
            <TrashIcon class="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>

      {/* Body */}
      <div class="p-2.5 lg:p-3">
        <h3 class="truncate font-semibold text-body-sm text-foreground">
          {props.product.name}
        </h3>
        <p class="mb-2 font-mono text-caption-sm text-faint-foreground">
          {props.product.sku}
        </p>
        <div class="flex items-center justify-between gap-2">
          <span class="font-bold text-body-sm text-primary tabular-nums">
            {formatRupiah(props.product.price)}
          </span>
          <span class="shrink-0 rounded-full bg-muted px-2 py-0.5 font-medium text-caption-sm text-muted-foreground">
            {props.product.stock} {props.product.unit}
          </span>
        </div>
      </div>
    </div>
  );
}

function EmptyState(props: { message: string; subtitle: string }) {
  return (
    <div class="flex flex-col items-center justify-center gap-1 py-20 text-center">
      <p class="text-body-sm text-muted-foreground">{props.message}</p>
      <p class="text-caption text-faint-foreground">{props.subtitle}</p>
    </div>
  );
}

import { A } from "@solidjs/router";
import { createMemo, createSignal, For, Show } from "solid-js";
import { LayersIcon, PencilIcon, PlusIcon, SearchIcon, TrashIcon } from "~/assets";
import { Button } from "~/components/ui/button";
import { formatRupiah } from "~/lib/utils";
import {
  type Variant,
  formatVariantOptions,
  getVariantProductNames,
  products,
  variants,
} from "../data";

export function TabVarian() {
  const [search, setSearch] = createSignal("");

  const filtered = createMemo(() => {
    const q = search().toLowerCase();
    if (!q) return variants;
    return variants.filter((v) => {
      const nameMatch = v.name.toLowerCase().includes(q);
      const optsMatch = v.options
        .map((o) => o.label)
        .join(",")
        .toLowerCase()
        .includes(q);
      const prodMatch = v.productIds.some((pid) =>
        products
          .find((p) => p.id === pid)
          ?.name.toLowerCase()
          .includes(q),
      );
      return nameMatch || optsMatch || prodMatch;
    });
  });

  return (
    <div class="flex flex-1 flex-col overflow-hidden">
      {/* Search + add */}
      <div class="flex shrink-0 items-center gap-2.5 px-4 pt-3 pb-3 lg:px-6">
        <label class="flex flex-1 items-center gap-2 rounded-xl bg-card px-3.5 py-2 shadow-card">
          <SearchIcon class="h-4 w-4 shrink-0 text-faint-foreground" />
          <input
            class="w-full bg-transparent text-body-sm text-foreground outline-none placeholder:text-faint-foreground"
            onInput={(e) => setSearch(e.currentTarget.value)}
            placeholder="Cari varian..."
            type="text"
            value={search()}
          />
        </label>
        <Button as={A} href="#" size="sm">
          <PlusIcon class="h-4 w-4" />
          <span class="hidden sm:inline">Tambah Varian</span>
        </Button>
      </div>

      {/* Variant list */}
      <div class="scrollbar-none flex-1 overflow-y-auto px-4 pb-28 lg:px-6 lg:pb-6">
        <Show
          fallback={<EmptyState message="Belum ada varian" subtitle="Tambah varian untuk opsi produk" />}
          when={filtered().length > 0}
        >
          <div class="flex flex-col gap-2.5">
            <For each={filtered()}>
              {(variant) => <VariantItem variant={variant} />}
            </For>
          </div>
        </Show>
      </div>
    </div>
  );
}

function VariantItem(props: { variant: Variant }) {
  return (
    <div class="flex items-center gap-3 rounded-2xl border border-border bg-card p-3 transition-colors hover:border-primary/20 lg:gap-4 lg:p-4">
      <div class="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary/10">
        <LayersIcon class="h-5 w-5 text-primary" />
      </div>
      <div class="min-w-0 flex-1">
        <h3 class="font-semibold text-body-sm text-foreground">
          {props.variant.name}
        </h3>
        <p class="truncate text-caption text-muted-foreground">
          {formatVariantOptions(props.variant.options)}
        </p>
        <p class="truncate text-caption-sm text-faint-foreground">
          {getVariantProductNames(props.variant.productIds, products)}
        </p>
      </div>
      <span class="hidden shrink-0 font-medium text-caption text-muted-foreground sm:block">
        {props.variant.productIds.length} produk
      </span>
      <div class="flex shrink-0 gap-1">
        <Button
          aria-label={`Edit ${props.variant.name}`}
          size="icon-sm"
          tone="neutral"
          variant="ghost"
        >
          <PencilIcon class="h-3.5 w-3.5" />
        </Button>
        <Button
          aria-label={`Hapus ${props.variant.name}`}
          size="icon-sm"
          tone="danger"
          variant="ghost"
        >
          <TrashIcon class="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
}

function EmptyState(props: { message: string; subtitle: string }) {
