import type { JSX } from "solid-js";
import { ScreenHeader } from "./screen-header";

interface SubPageShellProps {
  readonly backHref: string;
  readonly backLabel?: string;
  readonly children: JSX.Element;
  readonly title: string;
  readonly [key: string]: unknown;
}

export const SubPageShell = (props: SubPageShellProps) => {
  const { backHref, backLabel, children, title, ...rest } = props;
  return (
    <div
      {...rest}
      class="flex h-screen flex-col bg-muted font-sans text-foreground antialiased"
    >
      <ScreenHeader backHref={backHref} backLabel={backLabel} title={title} />
      {children}
    </div>
  );
};

import { A } from "@solidjs/router";
import type { JSX } from "solid-js";
import { Show } from "solid-js";
import { ArrowLeftIcon } from "~/assets";

interface ScreenHeaderProps {
  readonly backHref: string;
  readonly backLabel?: string;
  readonly right?: JSX.Element;
  readonly title: string;
}

export const ScreenHeader = (props: ScreenHeaderProps) => (
  <header class="flex h-header shrink-0 items-center justify-between border-border border-b bg-card px-3.5 lg:px-5">
    <div class="flex items-center gap-3.5">
      <A
        aria-label={props.backLabel ?? "Kembali"}
        class="grid h-[38px] w-[38px] place-items-center rounded-[10px] border border-border bg-card text-foreground transition-[background,border-color] duration-150 hover:border-primary/20 hover:bg-primary/5"
        href={props.backHref}
      >
        <ArrowLeftIcon class="h-[18px] w-[18px]" />
      </A>
      <span class="font-bold font-display text-[17px] text-foreground tracking-[-0.01em]">
        {props.title}
      </span>
    </div>

    <div class="flex items-center gap-2.5">
      <Show when={props.right}>{props.right}</Show>
    </div>
  </header>
);

import type { RouteSectionProps } from "@solidjs/router";
import { useLocation } from "@solidjs/router";
import { Show } from "solid-js";
import { SubPageShell } from "~/components/layout/sub-page-shell/sub-page-shell";
import { FadeIn } from "~/components/ui/fade-in";
import { useIsWide } from "~/lib/use-is-wide";
import { useOrientation } from "~/lib/use-orientation";
import { NAV_ITEMS, SettingsNav } from "./components/settings-nav";

export default function Pengaturan(props: RouteSectionProps) {
  const isPortrait = useOrientation();
  const isWide = useIsWide();
  const enable = () => !isPortrait();
  const location = useLocation();

  // Section sub-route? (e.g. /pengaturan/umum — not the bare /pengaturan)
  const isSectionRoute = () => {
    const parts = location.pathname.split("/").filter(Boolean);
    return parts.length > 1 && parts[0] === "pengaturan";
  };

  const sectionTitle = () => {
    const seg = location.pathname.split("/")[2];
    return NAV_ITEMS.find((i) => i.key === seg)?.label ?? "Pengaturan";
  };

  return (
    <Show
      fallback={
        /* ── Index route (mobile) or two-column layout (desktop) ── */
        <div
          class="scrollbar-none flex flex-1 flex-col gap-4 overflow-y-auto px-[18px] pt-6 pb-28 lg:gap-5 lg:px-7 lg:pb-24"
          data-ssgoi-transition="/pengaturan"
        >
          <FadeIn duration={0.35} enable={enable()} y={-8}>
            <h1 class="font-bold font-display text-foreground text-heading-sm">
              Pengaturan
            </h1>
            <p class="mt-0.5 text-body-sm text-muted-foreground tracking-[0.02em]">
              Kelola konfigurasi bisnis dan aplikasi Anda
            </p>
          </FadeIn>

          <div class="flex flex-col gap-6 lg:flex-row">
            <FadeIn delay={0.06} duration={0.45} enable={enable()} x={-30}>
              <SettingsNav />
            </FadeIn>

            {/* Desktop only — section panel. Hidden below lg (nav is the menu). */}
            <Show when={isWide()}>
              <FadeIn
                class="flex min-w-0 flex-1 flex-col gap-6"
                delay={0.14}
                duration={0.5}
                enable={enable()}
                scale={0.97}
                x={24}
              >
                <Show keyed when={location.pathname}>
                  {(_) => (
                    <FadeIn
                      duration={0.35}
                      enable={enable()}
                      scale={0.98}
                      x={16}
                    >
                      {props.children}
                    </FadeIn>
                  )}
                </Show>
              </FadeIn>
            </Show>
          </div>
        </div>
      }
      when={!isWide() && isSectionRoute()}
    >
      {/* ── Mobile section route → full-screen SubPageShell ── */}
      <SubPageShell
        backHref="/pengaturan"
        data-ssgoi-transition={location.pathname}
        title={sectionTitle()}
      >
        <div class="scrollbar-none flex-1 overflow-y-auto p-5 pb-28">
          {props.children}
        </div>
      </SubPageShell>
    </Show>
  );
}

import { A } from "@solidjs/router";
import { createMemo, createSignal, For, Show } from "solid-js";
import {
  GridIcon,
  PencilIcon,
  PlusIcon,
  SearchIcon,
  TrashIcon,
} from "~/assets";
import { Button } from "~/components/ui/button";
import { type Category, categories, products } from "~/lib/data/catalog";

export function TabKategori() {
  const [search, setSearch] = createSignal("");

  const filtered = createMemo(() => {
    const q = search().toLowerCase();
    if (!q) {
      return categories;
    }
    return categories.filter((c) => c.name.toLowerCase().includes(q));
  });

  return (
    <div class="flex flex-1 flex-col overflow-hidden">
      {/* Search + add */}
      <div class="flex shrink-0 items-center gap-2.5 px-4 pt-3 pb-3 lg:px-6">
        <label class="flex flex-1 items-center gap-2 rounded-xl bg-card px-3.5 py-2 shadow-card">
          <SearchIcon class="h-4 w-4 shrink-0 text-faint-foreground" />
          <input
            class="w-full bg-transparent text-body-sm text-foreground outline-none placeholder:text-faint-foreground"
            onInput={(e) => setSearch(e.currentTarget.value)}
            placeholder="Cari kategori..."
            type="text"
            value={search()}
          />
        </label>
        <Button as={A} href="#" size="sm">
          <PlusIcon class="h-4 w-4" />
          <span class="hidden sm:inline">Tambah Kategori</span>
        </Button>
      </div>

      {/* Category list */}
      <div class="scrollbar-none flex-1 overflow-y-auto px-4 pb-28 lg:px-6 lg:pb-6">
        <Show
          fallback={
            <EmptyState
              message="Belum ada kategori"
              subtitle="Tambah kategori untuk mengelompokkan produk"
            />
          }
          when={filtered().length > 0}
        >
          <div class="flex flex-col gap-2.5">
            <For each={filtered()}>
              {(cat) => <CategoryItem category={cat} />}
            </For>
          </div>
        </Show>
      </div>
    </div>
  );
}

function CategoryItem(props: { category: Category }) {
  const count = () =>
    products.filter((p) => p.category === props.category.id).length;
  return (
    <div class="flex items-center gap-3 rounded-2xl border border-border bg-card p-3 transition-colors hover:border-primary/20 lg:gap-4 lg:p-4">
      <div
        class="flex size-10 shrink-0 items-center justify-center rounded-xl"
        style={{ background: props.category.color }}
      >
        <GridIcon class="h-5 w-5 text-white" />
      </div>
      <div class="min-w-0 flex-1">
        <h3 class="font-semibold text-body-sm text-foreground">
          {props.category.name}
        </h3>
        <p class="text-caption text-muted-foreground">{count()} produk</p>
      </div>
      <div class="flex shrink-0 gap-1">
        <Button
          aria-label={`Edit ${props.category.name}`}
          look="ghost"
          size="icon-sm"
          tone="neutral"
        >
          <PencilIcon class="h-3.5 w-3.5" />
        </Button>
        <Button
          aria-label={`Hapus ${props.category.name}`}
          look="ghost"
          size="icon-sm"
          tone="danger"
        >
          <TrashIcon class="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
}

function EmptyState(props: { message: string; subtitle: string }) {
  return (
    <div class="flex flex-col items-center justify-center gap-1 py-20 text-center">
      <p class="text-body-sm text-muted-foreground">{props.message}</p>
      <p class="text-caption text-faint-foreground">{props.subtitle}</p>
    </div>
  );
}

import type { PolymorphicProps } from "@kobalte/core";
import * as TextFieldPrimitive from "@kobalte/core/text-field";
import { cva } from "class-variance-authority";
import type { ValidComponent } from "solid-js";
import { mergeProps, splitProps } from "solid-js";
import { cn } from "~/lib/utils";

type TextFieldRootProps<T extends ValidComponent = "div"> =
  TextFieldPrimitive.TextFieldRootProps<T> & {
    class?: string | undefined;
  };

const TextField = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TextFieldRootProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldRootProps, ["class"]);
  return (
    <TextFieldPrimitive.Root
      class={cn("flex flex-col gap-1", local.class)}
      {...others}
    />
  );
};

type TextFieldInputProps<T extends ValidComponent = "input"> =
  TextFieldPrimitive.TextFieldInputProps<T> & {
    class?: string | undefined;
    type?:
      | "button"
      | "checkbox"
      | "color"
      | "date"
      | "datetime-local"
      | "email"
      | "file"
      | "hidden"
      | "image"
      | "month"
      | "number"
      | "password"
      | "radio"
      | "range"
      | "reset"
      | "search"
      | "submit"
      | "tel"
      | "text"
      | "time"
      | "url"
      | "week";
  };

const TextFieldInput = <T extends ValidComponent = "input">(
  rawProps: PolymorphicProps<T, TextFieldInputProps<T>>
) => {
  const props = mergeProps<TextFieldInputProps<T>[]>(
    { type: "text" },
    rawProps
  );
  const [local, others] = splitProps(props as TextFieldInputProps, [
    "type",
    "class",
  ]);
  return (
    <TextFieldPrimitive.Input
      class={cn(
        "h-12 w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground",
        "focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10",
        "dark:focus:border-accent",
        "data-[invalid]:border-danger data-[invalid]:ring-2 data-[invalid]:ring-danger/10",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "file:border-0 file:bg-transparent file:font-medium file:text-sm",
        local.class
      )}
      type={local.type}
      {...others}
    />
  );
};

type TextFieldTextAreaProps<T extends ValidComponent = "textarea"> =
  TextFieldPrimitive.TextFieldTextAreaProps<T> & { class?: string | undefined };

const TextFieldTextArea = <T extends ValidComponent = "textarea">(
  props: PolymorphicProps<T, TextFieldTextAreaProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldTextAreaProps, [
    "class",
  ]);
  return (
    <TextFieldPrimitive.TextArea
      class={cn(
        "min-h-[80px] w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 py-3 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground",
        "focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10",
        "dark:focus:border-accent",
        "data-[invalid]:border-danger data-[invalid]:ring-2 data-[invalid]:ring-danger/10",
        "disabled:cursor-not-allowed disabled:opacity-50",
        local.class
      )}
      {...others}
    />
  );
};

const labelVariants = cva(
  "font-medium text-[13px] text-foreground leading-none tracking-[0.01em] peer-disabled:cursor-not-allowed peer-disabled:opacity-70",
  {
    variants: {
      variant: {
        label: "data-[invalid]:text-danger",
        description: "font-normal text-muted-foreground",
        error: "text-danger text-xs",
      },
    },
    defaultVariants: {
      variant: "label",
    },
  }
);

type TextFieldLabelProps<T extends ValidComponent = "label"> =
  TextFieldPrimitive.TextFieldLabelProps<T> & { class?: string | undefined };

const TextFieldLabel = <T extends ValidComponent = "label">(
  props: PolymorphicProps<T, TextFieldLabelProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldLabelProps, ["class"]);
  return (
    <TextFieldPrimitive.Label
      class={cn(labelVariants(), local.class)}
      {...others}
    />
  );
};

type TextFieldDescriptionProps<T extends ValidComponent = "div"> =
  TextFieldPrimitive.TextFieldDescriptionProps<T> & {
    class?: string | undefined;
  };

const TextFieldDescription = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TextFieldDescriptionProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldDescriptionProps, [
    "class",
  ]);
  return (
    <TextFieldPrimitive.Description
      class={cn(labelVariants({ variant: "description" }), local.class)}
      {...others}
    />
  );
};

type TextFieldErrorMessageProps<T extends ValidComponent = "div"> =
  TextFieldPrimitive.TextFieldErrorMessageProps<T> & {
    class?: string | undefined;
  };

const TextFieldErrorMessage = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TextFieldErrorMessageProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldErrorMessageProps, [
    "class",
  ]);
  return (
    <TextFieldPrimitive.ErrorMessage
      class={cn(labelVariants({ variant: "error" }), local.class)}
      {...others}
    />
  );
};

export {
  TextField,
  TextFieldDescription,
  TextFieldErrorMessage,
  TextFieldInput,
  TextFieldLabel,
  TextFieldTextArea,
};

import type { JSX } from "solid-js";

/* ── shared primitives ────────────────────────────────────────── */

export function SectionCard(props: {
  readonly children: JSX.Element;
  readonly class?: string;
}) {
  return (
    <div
      class={`flex flex-col gap-5 rounded-[14px] border border-border bg-card px-6 py-6 ${props.class ?? ""}`}
    >
      {props.children}
    </div>
  );
}

export function CardTitle(props: { readonly children: JSX.Element }) {
  return (
    <h3 class="font-bold font-display text-body text-foreground tracking-[-0.01em]">
      {props.children}
    </h3>
  );
}

export function CardDesc(props: { readonly children: JSX.Element }) {
  return (
    <p class="mt-0.5 text-body-sm text-muted-foreground leading-relaxed">
      {props.children}
    </p>
  );
}

export function FormGrid(props: { readonly children: JSX.Element }) {
  return (
    <div class="grid grid-cols-1 gap-4 sm:grid-cols-2">{props.children}</div>
  );
}

export function FormGroup(props: {
  readonly children: JSX.Element;
  readonly fullWidth?: boolean;
}) {
  return (
    <div
      class={`flex flex-col gap-1.5 ${props.fullWidth ? "col-span-auto sm:col-span-1 sm:-col-end-1" : ""}`}
    >
      {props.children}
    </div>
  );
}

export function FormLabel(props: { readonly children: JSX.Element }) {
  return (
    <span class="font-semibold text-caption text-muted-foreground tracking-[0.04em]">
      {props.children}
    </span>
