   violate the single-green brand rule. Ordered by hue for scanning.
   First entry is canopy green so the default matches our brand. */
const CATEGORY_COLORS = [
  "#1c3a13",
  "#0e7c5f",
  "#22c55e",
  "#16a34a",
  "#06b6d4",
