    >
      <Route component={HomePage} path="/" />
      <Route component={Transactions} path="/transactions" />
      <Route component={SettingPage} path="/pengaturan">
        <Route component={SectionBusiness} path="/" />
        <Route component={SectionBusiness} path="/bisnis" />
        <Route component={SectionGeneral} path="/umum" />
        <Route component={SectionTax} path="/pajak" />
        <Route component={SectionPaymentMethods} path="/pembayaran" />
        <Route component={SectionReceipt} path="/struk" />
        <Route component={SectionTeams} path="/tim" />
        <Route component={SectionDevices} path="/perangkat" />
