import { cva, type VariantProps } from "class-variance-authority";
import type { JSX } from "solid-js";
import { splitProps } from "solid-js";

import { cn } from "~/lib/utils";
import { Button } from "~/components/ui/button";
import type { ButtonProps } from "~/components/ui/button";

/* ── InputGroup ─────────────────────────────────────────────────── */

export function InputGroup(props: JSX.HTMLAttributes<HTMLDivElement>) {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="input-group"
      role="group"
      class={cn(
        "group/input-group relative flex h-9 w-full min-w-0 items-center rounded-md border border-input bg-background transition-colors outline-none",
        "has-disabled:bg-muted/50 has-disabled:opacity-50",
        "has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-2 has-[[data-slot=input-group-control]:focus-visible]:ring-ring/30",
        "has-[[data-slot][aria-invalid=true]]:border-danger has-[[data-slot][aria-invalid=true]]:ring-2 has-[[data-slot][aria-invalid=true]]:ring-danger/15",
        "has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col",
        "has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col",
        "has-[>textarea]:h-auto",
        "has-[>[data-align=block-end]]:[&>input]:pt-3",
        "has-[>[data-align=block-start]]:[&>input]:pb-3",
        "has-[>[data-align=inline-end]]:[&>input]:pr-1.5",
        "has-[>[data-align=inline-start]]:[&>input]:pl-1.5",
        "dark:bg-muted/30 dark:has-disabled:bg-muted/60 dark:has-[[data-slot][aria-invalid=true]]:ring-danger/25",
        local.class
      )}
      {...others}
    />
  );
}

/* ── InputGroupAddon ────────────────────────────────────────────── */

const inputGroupAddonVariants = cva(
  "flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-sm font-medium text-muted-foreground select-none group-data-[disabled=true]/input-group:opacity-50 [&>kbd]:rounded-sm [&>svg:not([class*='size-'])]:size-4",
  {
    variants: {
      align: {
        "inline-start":
          "order-first pl-2 has-[>button]:ml-[-0.3rem] has-[>kbd]:ml-[-0.15rem]",
        "inline-end":
          "order-last pr-2 has-[>button]:mr-[-0.3rem] has-[>kbd]:mr-[-0.15rem]",
        "block-start":
          "order-first w-full justify-start px-2.5 pt-2 group-has-[>input]/input-group:pt-2 [.border-b]:pb-2",
        "block-end":
          "order-last w-full justify-start px-2.5 pb-2 group-has-[>input]/input-group:pb-2 [.border-t]:pt-2",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  }
);

type InputGroupAddonProps = JSX.HTMLAttributes<HTMLDivElement> &
  VariantProps<typeof inputGroupAddonVariants>;

export function InputGroupAddon(props: InputGroupAddonProps) {
  const [local, others] = splitProps(props, ["class", "align"]);
  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={local.align ?? "inline-start"}
      class={cn(inputGroupAddonVariants({ align: local.align }), local.class)}
      onClick={(e: MouseEvent) => {
        if ((e.target as HTMLElement).closest("button")) {
          return;
        }
        e.currentTarget.parentElement?.querySelector("input")?.focus();
      }}
      {...others}
    />
  );
}

/* ── InputGroupButton ───────────────────────────────────────────── */

const inputGroupButtonVariants = cva(
  "flex items-center gap-2 text-sm shadow-none",
  {
    variants: {
      size: {
        xs: "h-6 gap-1 rounded-[3px] px-1.5 [&>svg:not([class*='size-'])]:size-3.5",
        sm: "",
        "icon-xs": "size-6 rounded-[3px] p-0 has-[>svg]:p-0",
        "icon-sm": "size-8 p-0 has-[>svg]:p-0",
      },
    },
    defaultVariants: {
      size: "xs",
    },
  }
);

type InputGroupButtonProps = Omit<ButtonProps, "size"> &
  VariantProps<typeof inputGroupButtonVariants> & {
    type?: "button" | "submit" | "reset";
  };

export function InputGroupButton(props: InputGroupButtonProps) {
  const [local, others] = splitProps(props, [
    "class",
    "size",
    "look",
    "tone",
    "type",
  ]);
  return (
    <Button
      look={local.look ?? "ghost"}
      tone={local.tone ?? "neutral"}
      size="none"
      type={local.type ?? "button"}
      class={cn(inputGroupButtonVariants({ size: local.size }), local.class)}
      {...others}
    />
  );
}

/* ── InputGroupText ─────────────────────────────────────────────── */

export function InputGroupText(props: JSX.HTMLAttributes<HTMLSpanElement>) {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <span
      class={cn(
        "flex items-center gap-2 text-sm text-muted-foreground [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4",
        local.class
      )}
      {...others}
    />
  );
}

/* ── InputGroupInput ────────────────────────────────────────────── */

export function InputGroupInput(props: JSX.InputHTMLAttributes<HTMLInputElement>) {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <input
      data-slot="input-group-control"
      class={cn(
        "flex-1 rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 disabled:bg-transparent aria-invalid:ring-0 dark:bg-transparent dark:disabled:bg-transparent",
        local.class
      )}
      {...others}
    />
  );
}

/* ── InputGroupTextarea ─────────────────────────────────────────── */

export function InputGroupTextarea(
  props: JSX.TextareaHTMLAttributes<HTMLTextAreaElement>
) {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <textarea
      data-slot="input-group-control"
      class={cn(
        "flex-1 resize-none rounded-none border-0 bg-transparent py-2 shadow-none ring-0 focus-visible:ring-0 disabled:bg-transparent aria-invalid:ring-0 dark:bg-transparent dark:disabled:bg-transparent",
        local.class
      )}
      {...others}
    />
  );
}

