import type { PolymorphicProps } from "@kobalte/core";
import * as TextFieldPrimitive from "@kobalte/core/text-field";
import { cva } from "class-variance-authority";
import type { ValidComponent } from "solid-js";
import { mergeProps, splitProps } from "solid-js";
import { cn } from "~/lib/utils";

type TextFieldRootProps<T extends ValidComponent = "div"> =
  TextFieldPrimitive.TextFieldRootProps<T> & {
    class?: string | undefined;
  };

const TextField = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TextFieldRootProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldRootProps, ["class"]);
  return (
    <TextFieldPrimitive.Root
      class={cn("flex flex-col gap-1", local.class)}
      {...others}
    />
  );
};

type TextFieldInputProps<T extends ValidComponent = "input"> =
  TextFieldPrimitive.TextFieldInputProps<T> & {
    class?: string | undefined;
    type?:
      | "button"
      | "checkbox"
      | "color"
      | "date"
      | "datetime-local"
      | "email"
      | "file"
      | "hidden"
      | "image"
      | "month"
      | "number"
      | "password"
      | "radio"
      | "range"
      | "reset"
      | "search"
      | "submit"
      | "tel"
      | "text"
      | "time"
      | "url"
      | "week";
  };

const TextFieldInput = <T extends ValidComponent = "input">(
  rawProps: PolymorphicProps<T, TextFieldInputProps<T>>
) => {
  const props = mergeProps<TextFieldInputProps<T>[]>(
    { type: "text" },
    rawProps
  );
  const [local, others] = splitProps(props as TextFieldInputProps, [
    "type",
    "class",
  ]);
  return (
    <TextFieldPrimitive.Input
      class={cn(
        "h-12 w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground",
        "focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10",
        "dark:focus:border-accent",
        "data-[invalid]:border-danger data-[invalid]:ring-2 data-[invalid]:ring-danger/10",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "file:border-0 file:bg-transparent file:font-medium file:text-sm",
        local.class
      )}
      type={local.type}
      {...others}
    />
  );
};

type TextFieldTextAreaProps<T extends ValidComponent = "textarea"> =
  TextFieldPrimitive.TextFieldTextAreaProps<T> & { class?: string | undefined };

const TextFieldTextArea = <T extends ValidComponent = "textarea">(
  props: PolymorphicProps<T, TextFieldTextAreaProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldTextAreaProps, [
    "class",
  ]);
  return (
    <TextFieldPrimitive.TextArea
      class={cn(
        "min-h-[80px] w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 py-3 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground",
        "focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10",
        "dark:focus:border-accent",
        "data-[invalid]:border-danger data-[invalid]:ring-2 data-[invalid]:ring-danger/10",
        "disabled:cursor-not-allowed disabled:opacity-50",
        local.class
      )}
      {...others}
    />
  );
};

const labelVariants = cva(
  "font-medium text-[13px] text-foreground leading-none tracking-[0.01em] peer-disabled:cursor-not-allowed peer-disabled:opacity-70",
  {
    variants: {
      variant: {
        label: "data-[invalid]:text-danger",
        description: "font-normal text-muted-foreground",
        error: "text-danger text-xs",
      },
    },
    defaultVariants: {
      variant: "label",
    },
  }
);

type TextFieldLabelProps<T extends ValidComponent = "label"> =
  TextFieldPrimitive.TextFieldLabelProps<T> & { class?: string | undefined };

const TextFieldLabel = <T extends ValidComponent = "label">(
  props: PolymorphicProps<T, TextFieldLabelProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldLabelProps, ["class"]);
  return (
    <TextFieldPrimitive.Label
      class={cn(labelVariants(), local.class)}
      {...others}
    />
  );
};

type TextFieldDescriptionProps<T extends ValidComponent = "div"> =
  TextFieldPrimitive.TextFieldDescriptionProps<T> & {
    class?: string | undefined;
  };

const TextFieldDescription = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TextFieldDescriptionProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldDescriptionProps, [
    "class",
  ]);
  return (
    <TextFieldPrimitive.Description
      class={cn(labelVariants({ variant: "description" }), local.class)}
      {...others}
    />
  );
};

type TextFieldErrorMessageProps<T extends ValidComponent = "div"> =
  TextFieldPrimitive.TextFieldErrorMessageProps<T> & {
    class?: string | undefined;
  };

const TextFieldErrorMessage = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TextFieldErrorMessageProps<T>>
) => {
  const [local, others] = splitProps(props as TextFieldErrorMessageProps, [
    "class",
  ]);
  return (
    <TextFieldPrimitive.ErrorMessage
      class={cn(labelVariants({ variant: "error" }), local.class)}
      {...others}
    />
  );
};

export {
  TextField,
  TextFieldDescription,
  TextFieldErrorMessage,
  TextFieldInput,
  TextFieldLabel,
  TextFieldTextArea,
};

import { useNavigate, useParams } from "@solidjs/router";
import { createSignal, For, Show } from "solid-js";
import { toast } from "solid-sonner";
import { UploadIcon, XCloseIcon } from "~/assets";
import { SubPageShell } from "~/components/layout/sub-page-shell/sub-page-shell";
import { Button } from "~/components/ui/button";
import { categories, products } from "~/lib/data/catalog";

const UNITS = ["cup", "glass", "plate", "pcs", "bowl", "bottle"] as const;

export default function ProductFormPage() {
  const navigate = useNavigate();
  const params = useParams();

  const editId = () => {
    if (!params.id || params.id === "new") {
      return;
    }
    const n = Number.parseInt(params.id, 10);
    return Number.isNaN(n) ? undefined : n;
  };
  const existing = () =>
    editId() ? products.find((p) => p.id === editId()) : undefined;
  const isEditing = () => Boolean(existing());

  const [name, setName] = createSignal(existing()?.name ?? "");
  const [sku, setSku] = createSignal(existing()?.sku ?? "");
  const [category, setCategory] = createSignal(existing()?.category ?? "");
  const [price, setPrice] = createSignal(
    existing() ? String(existing()!.price) : ""
  );
  const [stock, setStock] = createSignal(
    existing() ? String(existing()!.stock) : ""
  );
  const [unit, setUnit] = createSignal(existing()?.unit ?? "cup");
  const [photo, setPhoto] = createSignal<string | null>(null);

  const handlePhotoChange = (e: Event) => {
    const input = e.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) {
      return;
    }
    const reader = new FileReader();
    reader.onload = (ev) => setPhoto(ev.target?.result as string);
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    const trimmedName = name().trim();
    if (!trimmedName) {
      toast.error("Nama produk wajib diisi");
      return;
    }
    if (!sku().trim()) {
      toast.error("SKU wajib diisi");
      return;
    }
    if (!category()) {
      toast.error("Pilih kategori");
      return;
    }
    if (!price() || Number.parseInt(price(), 10) <= 0) {
      toast.error("Harga wajib diisi");
      return;
    }
    toast.success(isEditing() ? "Produk diperbarui" : "Produk ditambahkan");
    navigate("/catalog");
  };

  return (
    <SubPageShell
      backHref="/catalog"
      data-ssgoi-transition="/catalog/product"
      title={isEditing() ? "Edit Produk" : "Tambah Produk"}
    >
      <div class="scrollbar-none flex-1 overflow-y-auto px-5 py-6 pb-28">
        <div class="mx-auto w-full max-w-2xl rounded-lg border border-border bg-card p-6">
          {/* ── Photo + Name + SKU ── */}
          <div class="flex flex-col gap-5 sm:flex-row sm:items-start">
            <div class="flex flex-col gap-1.5">
              <span class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]">
                Foto Produk
              </span>
              <label class="group relative grid h-[120px] w-[120px] shrink-0 cursor-pointer place-items-center overflow-hidden rounded-lg bg-muted">
                <Show when={photo()}>
                  <img
                    alt="Preview"
                    class="absolute inset-0 h-full w-full object-cover"
                    src={photo()!}
                  />
                </Show>
                <Show when={!photo()}>
                  <div class="flex flex-col items-center gap-1.5 text-muted-foreground transition-colors group-hover:text-foreground">
                    <UploadIcon class="h-6 w-6" />
                    <span class="font-medium text-caption-sm">Upload</span>
                  </div>
                </Show>
                <input
                  accept="image/*"
                  class="sr-only"
                  onChange={handlePhotoChange}
                  type="file"
                />
              </label>
              <Show when={photo()}>
                <button
                  class="inline-flex items-center justify-center gap-1 font-medium text-caption-sm text-danger transition-colors hover:text-danger/80"
                  onClick={() => setPhoto(null)}
                  type="button"
                >
                  <XCloseIcon class="h-3 w-3" />
                  Hapus Foto
                </button>
              </Show>
            </div>

            <div class="flex min-w-0 flex-1 flex-col gap-4">
              <div class="flex flex-col gap-1.5">
                <label
                  class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]"
                  for="fName"
                >
                  Nama Produk
                </label>
                <input
                  autofocus
                  class="h-12 w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                  id="fName"
                  onInput={(e) => setName(e.currentTarget.value)}
                  placeholder="e.g. Es Kopi Susu"
                  type="text"
                  value={name()}
                />
              </div>
              <div class="flex flex-col gap-1.5">
                <label
                  class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]"
                  for="fSku"
                >
                  SKU
                </label>
                <input
                  class="h-12 w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                  id="fSku"
                  onInput={(e) => setSku(e.currentTarget.value)}
                  placeholder="e.g. KPI-001"
                  type="text"
                  value={sku()}
                />
              </div>
            </div>
          </div>

          {/* ── Divider ── */}
          <hr class="my-6 border-border" />

          {/* ── Category + Price + Stock + Unit ── */}
          <div class="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <div class="flex flex-col gap-1.5">
              <label
                class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]"
                for="fCategory"
              >
                Kategori
              </label>
              <select
                class="h-12 w-full cursor-pointer appearance-none rounded-sm border-[1.5px] border-input bg-[length:12px_8px] bg-[position:right_14px_center] bg-[url('data:image/svg+xml,%3Csvg%20width%3D%2712%27%20height%3D%278%27%20viewBox%3D%270%200%2012%208%27%20fill%3D%27none%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Cpath%20d%3D%27M1%201.5L6%206.5L11%201.5%27%20stroke%3D%27%23737c77%27%20stroke-width%3D%271.5%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E')] bg-background bg-no-repeat px-3.5 pr-9 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                id="fCategory"
                onChange={(e) => setCategory(e.currentTarget.value)}
                value={category()}
              >
                <option disabled value="">
                  Pilih kategori
                </option>
                <For each={categories}>
                  {(cat) => <option value={cat.id}>{cat.name}</option>}
                </For>
              </select>
            </div>
            <div class="flex flex-col gap-1.5">
              <label
                class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]"
                for="fPrice"
              >
                Harga (Rp)
              </label>
              <input
                class="h-12 w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-[15px] text-foreground tabular-nums outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                id="fPrice"
                min="0"
                onInput={(e) => setPrice(e.currentTarget.value)}
                placeholder="25000"
                type="number"
                value={price()}
              />
            </div>
            <div class="flex flex-col gap-1.5">
              <label
                class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]"
                for="fStock"
              >
                Stok
              </label>
              <input
                class="h-12 w-full rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-[15px] text-foreground tabular-nums outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                id="fStock"
                min="0"
                onInput={(e) => setStock(e.currentTarget.value)}
                placeholder="50"
                type="number"
                value={stock()}
              />
            </div>
            <div class="flex flex-col gap-1.5">
              <label
                class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]"
                for="fUnit"
              >
                Satuan
              </label>
              <select
                class="h-12 w-full cursor-pointer appearance-none rounded-sm border-[1.5px] border-input bg-[length:12px_8px] bg-[position:right_14px_center] bg-[url('data:image/svg+xml,%3Csvg%20width%3D%2712%27%20height%3D%278%27%20viewBox%3D%270%200%2012%208%27%20fill%3D%27none%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Cpath%20d%3D%27M1%201.5L6%206.5L11%201.5%27%20stroke%3D%27%23737c77%27%20stroke-width%3D%271.5%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E')] bg-background bg-no-repeat px-3.5 pr-9 font-sans text-[15px] text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                id="fUnit"
                onChange={(e) => setUnit(e.currentTarget.value)}
                value={unit()}
              >
                <For each={UNITS}>
                  {(u) => (
                    <option value={u}>
                      {u.charAt(0).toUpperCase() + u.slice(1)}
                    </option>
                  )}
                </For>
              </select>
            </div>
          </div>

          {/* ── Actions ── */}
          <div class="mt-7 flex flex-col-reverse gap-2.5 sm:flex-row sm:justify-end">
            <Button
              look="outline"
              onClick={() => navigate("/catalog")}
              tone="neutral"
              type="button"
            >
              Batal
            </Button>
            <Button onClick={handleSave} type="button">
              {isEditing() ? "Simpan Perubahan" : "Simpan Produk"}
            </Button>
          </div>
        </div>
      </div>
    </SubPageShell>
  );
}

import { useNavigate, useParams } from "@solidjs/router";
import { createSignal, For, Show } from "solid-js";
import { createStore } from "solid-js/store";
import { toast } from "solid-sonner";
import { PlusIcon, XCloseIcon } from "~/assets";
import { SubPageShell } from "~/components/layout/sub-page-shell/sub-page-shell";
import { Button } from "~/components/ui/button";
import {
  TextField,
  TextFieldInput,
  TextFieldLabel,
} from "~/components/ui/text-field";
import { products, type VariantOption, variants } from "~/lib/data/catalog";
import { cn } from "~/lib/utils";

interface OptionRow extends VariantOption {
  readonly _id: number;
}

let _rowId = 0;

export default function VariantFormPage() {
  const navigate = useNavigate();
  const params = useParams();

  const editId = () => {
    if (!params.id || params.id === "new") {
      return;
    }
    const n = Number.parseInt(params.id, 10);
    return Number.isNaN(n) ? undefined : n;
  };
  const existing = () =>
    editId() ? variants.find((v) => v.id === editId()) : undefined;
  const isEditing = () => Boolean(existing());

  const [name, setName] = createSignal(existing()?.name ?? "");
  const [options, setOptions] = createStore<OptionRow[]>(
    existing()
      ? existing()!.options.map((o) => ({ ...o, _id: _rowId++ }))
      : [{ _id: _rowId++, label: "", price: 0 }]
  );

  const addOption = () =>
    setOptions((prev) => [...prev, { _id: _rowId++, label: "", price: 0 }]);

  const removeOption = (id: number) => {
    if (options.length <= 1) {
      toast.error("Minimal 1 opsi");
      return;
    }
    setOptions((prev) => prev.filter((o) => o._id !== id));
  };

  const linkedProducts = () =>
    existing()
      ? existing()!
          .productIds.map((pid) => products.find((p) => p.id === pid)?.name)
          .filter(Boolean)
      : [];

  const handleSave = () => {
    const trimmed = name().trim();
    if (!trimmed) {
      toast.error("Nama varian wajib diisi");
      return;
    }
    const valid = options.filter((o) => o.label.trim());
    if (valid.length === 0) {
      toast.error("Minimal 1 opsi dengan nama");
      return;
    }
    toast.success(isEditing() ? "Varian diperbarui" : "Varian ditambahkan");
    navigate("/catalog");
  };

  return (
    <SubPageShell
      backHref="/catalog"
      data-ssgoi-transition="/catalog/variant"
      title={isEditing() ? "Edit Varian" : "Tambah Varian"}
    >
      <div class="scrollbar-none flex-1 overflow-y-auto px-5 py-6 pb-28">
        <div class="mx-auto w-full max-w-2xl rounded-lg border border-border bg-card p-6">
          {/* ── Name ── */}
          <TextField class="mb-6 gap-1.5" onChange={setName} value={name()}>
            <TextFieldLabel>Nama Varian</TextFieldLabel>
            <TextFieldInput autofocus placeholder="e.g. Size, Level Pedas" />
          </TextField>

          {/* ── Options & prices ── */}
          <div class="mb-6">
            <div class="mb-2.5 flex items-center justify-between">
              <span class="font-medium text-[13px] text-foreground leading-none tracking-[0.01em]">
                Opsi &amp; Harga
              </span>
              <Button
                look="soft"
                onClick={addOption}
                size="xs"
                tone="primary"
                type="button"
              >
                <PlusIcon class="h-3.5 w-3.5" />
                Tambah Opsi
              </Button>
            </div>

            <div class="flex flex-col gap-2">
              <For each={options}>
                {(opt) => (
                  <div class="flex items-center gap-2">
                    <input
                      class="h-11 min-w-0 flex-1 rounded-sm border-[1.5px] border-input bg-background px-3.5 font-sans text-body-sm text-foreground outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                      onChange={(e) =>
                        setOptions(
                          (o) => o._id === opt._id,
                          "label",
                          e.currentTarget.value
                        )
                      }
                      placeholder="Nama opsi"
                      type="text"
                      value={opt.label}
                    />
                    <div class="flex shrink-0 items-center gap-1">
                      <span class="text-caption-sm text-faint-foreground">
                        +Rp
                      </span>
                      <input
                        aria-label={`Harga opsi ${opt.label || ""}`}
                        class="h-11 w-24 rounded-sm border-[1.5px] border-input bg-background px-3 text-right font-sans text-body-sm text-foreground tabular-nums outline-none transition-[border-color,box-shadow] duration-standard ease-standard placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-ring focus:outline-offset-1 focus:ring-2 focus:ring-primary/10 dark:focus:border-accent"
                        min="0"
                        onInput={(e) =>
                          setOptions(
                            (o) => o._id === opt._id,
                            "price",
                            Math.max(
                              0,
                              Number.parseInt(e.currentTarget.value, 10) || 0
                            )
                          )
                        }
                        placeholder="0"
                        type="number"
                        value={opt.price}
                      />
                    </div>
                    <Button
                      aria-label="Hapus opsi"
                      look="ghost"
                      onClick={() => removeOption(opt._id)}
                      size="icon-sm"
                      tone="danger"
                      type="button"
                    >
                      <XCloseIcon class="h-3.5 w-3.5" />
                    </Button>
                  </div>
                )}
              </For>
            </div>
          </div>

          {/* ── Linked products (edit mode only, read-only) ── */}
          <Show when={isEditing()}>
            <div class="mb-7 flex flex-col gap-2">
              <span class="font-medium text-[13px] text-muted-foreground leading-none tracking-[0.01em]">
                Produk yang menggunakan varian ini
              </span>
              <div class="flex max-h-50 flex-wrap gap-1.5 overflow-y-auto rounded-lg border border-border bg-muted p-2.5">
                <Show
                  fallback={
                    <p class="w-full py-2 text-center text-caption-sm text-muted-foreground">
                      Belum ada produk yang menggunakan varian ini
                    </p>
                  }
                  when={linkedProducts().length > 0}
                >
                  <For each={linkedProducts()}>
                    {(p) => (
                      <span
                        class={cn(
                          "inline-flex items-center whitespace-nowrap rounded-full border border-primary/15 bg-accent-soft px-3 py-1 font-medium text-caption-sm text-primary"
                        )}
                      >
                        {p}
                      </span>
                    )}
                  </For>
                </Show>
              </div>
            </div>
          </Show>

          {/* ── Actions ── */}
          <div class="flex flex-col-reverse gap-2.5 sm:flex-row sm:justify-end">
            <Button
              look="outline"
              onClick={() => navigate("/catalog")}
              tone="neutral"
              type="button"
            >
              Batal
            </Button>
            <Button onClick={handleSave} type="button">
              {isEditing() ? "Simpan Perubahan" : "Simpan Varian"}
            </Button>
          </div>
        </div>
      </div>
    </SubPageShell>
  );
}

