import type { PolymorphicProps } from "@kobalte/core";
import * as NumberFieldPrimitive from "@kobalte/core/number-field";
import { cva } from "class-variance-authority";
import type { ValidComponent } from "solid-js";
import { mergeProps, splitProps } from "solid-js";
import { cn } from "~/lib/utils";

type NumberFieldRootProps<T extends ValidComponent = "div"> =
  NumberFieldPrimitive.NumberFieldRootProps<T> & {
    class?: string | undefined;
  };

const NumberField = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, NumberFieldRootProps<T>>
) => {
  const merged = mergeProps<NumberFieldRootProps[]>(
    {
      format: true,
      formatOptions: {
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      },
    },
    props as NumberFieldRootProps
  );
  const [local, others] = splitProps(merged, ["class"]);
  return (
    <NumberFieldPrimitive.Root
      class={cn("flex flex-col gap-1", local.class)}
      {...others}
    />
  );
};

type NumberFieldInputProps<T extends ValidComponent = "input"> =
  NumberFieldPrimitive.NumberFieldInputProps<T> & {
    class?: string | undefined;
