import { fireEvent, render, screen } from "@solidjs/testing-library";
import { describe, expect, it, vi } from "vitest";
import { NumberField, NumberFieldInput, NumberFieldLabel } from "./number-field";

const setup = (props?: Record<string, unknown>) => {
  const onChange = vi.fn();
  render(() => (
    <NumberField>
      <NumberFieldLabel>Price</NumberFieldLabel>
      <NumberFieldInput
        onChange={onChange}
        placeholder="0"
        {...props}
      />
    </NumberField>
  ));
  const input = screen.getByPlaceholderText("0") as HTMLInputElement;
  return { input, onChange };
};

const typeChar = (input: HTMLInputElement, char: string) => {
  const pos = input.selectionStart ?? 0;
  input.value =
    input.value.slice(0, pos) + char + input.value.slice(pos);
  input.setSelectionRange(pos + 1, pos + 1);
  fireEvent.input(input);
};

const backspace = (input: HTMLInputElement) => {
