### adaptive-dialog.tsx structure

```tsx
import { createContext, useContext, type JSX } from "solid-js";
import * as DialogPrimitive from "@kobalte/core/dialog";
import Drawer from "@corvu/drawer";
import { createBreakpoints } from "@solid-primitives/media";
import { Show } from "solid-js";
import { XCloseIcon } from "~/assets";
import { cn } from "~/lib/utils";

// Context
type AdaptiveDialogMode = "dialog" | "sheet";
const AdaptiveDialogContext = createContext<{ mode: () => AdaptiveDialogMode }>();
const useAdaptiveDialog = () => {
  const ctx = useContext(AdaptiveDialogContext);
  if (!ctx) throw new Error("AdaptiveDialog components must be used within AdaptiveDialog");
  return ctx;
};

// Root
export function AdaptiveDialog(props: {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: JSX.Element;
}) {
  const matches = createBreakpoints({ sm: "640px", md: "768px", lg: "1024px" });
  const mode = (): AdaptiveDialogMode => (matches.md ? "dialog" : "sheet");

  return (
    <AdaptiveDialogContext.Provider value={{ mode }}>
      <Show
        when={mode() === "dialog"}
        fallback={
          <Drawer open={props.open} onOpenChange={props.onOpenChange}>
            {props.children}
          </Drawer>
        }
      >
        <DialogPrimitive.Root open={props.open} onOpenChange={props.onOpenChange}>
          {props.children}
        </DialogPrimitive.Root>
      </Show>
    </AdaptiveDialogContext.Provider>
  );
}

// Trigger
export function AdaptiveDialogTrigger(props: ComponentProps<typeof DialogPrimitive.Trigger>) {
  const ctx = useAdaptiveDialog();
  return (
    <Show when={ctx.mode() === "dialog"} fallback={<Drawer.Trigger {...props} />}>
      <DialogPrimitive.Trigger {...props} />
    </Show>
  );
}

// Content
export function AdaptiveDialogContent(props: {
  class?: string;
  children?: JSX.Element;
}) {
  const ctx = useAdaptiveDialog();
  return (
    <Show
      when={ctx.mode() === "dialog"}
      fallback={<SheetContent class={props.class}>{props.children}</SheetContent>}
    >
      <DialogContent class={props.class}>{props.children}</DialogContent>
    </Show>
  );
}

// ... etc
```

