### Task 3: Write failing tests for AdaptiveDialog mode detection

**Files:**
- Create: `src/components/ui/__test__/adaptive-dialog.test.tsx`

**Step 1: Write the test file with matchMedia mock**

jsdom doesn't implement `window.matchMedia`. We need to mock it so `createBreakpoints` works. The mock takes a map of `min-width → boolean` and returns `matches` accordingly.

```tsx
import { fireEvent, render, screen } from "@solidjs/testing-library";
import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";

// ── matchMedia mock ──────────────────────────────────────────────
// jsdom doesn't implement matchMedia. We mock it to return controlled
// matches values so we can simulate different viewport widths.

let mockMatches: Record<string, boolean> = {};

const mockMatchMedia = (query: string): MediaQueryList => {
  // Extract the pixel value from "(min-width: 768px)" etc.
  const match = query.match(/\(min-width:\s*([\d.]+)px\)/);
  const threshold = match ? Number.parseFloat(match[1]) : Infinity;
  const matches = mockMatches[`${threshold}`] ?? false;
  return {
    matches,
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    addListener: vi.fn(),
    removeListener: vi.fn(),
    dispatchEvent: vi.fn(),
  } as unknown as MediaQueryList;
};

const setViewport = (width: number) => {
  // Set which thresholds are "matched" — all thresholds <= width
  mockMatches = {};
  for (const bp of [600, 768, 900, 1200]) {
    mockMatches[`${bp}`] = width >= bp;
  }
};

// ── Tests ────────────────────────────────────────────────────────

describe("AdaptiveDialog mode detection", () => {
  beforeEach(() => {
    vi.stubGlobal("matchMedia", mockMatchMedia);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    mockMatches = {};
  });

  it("renders Sheet/Drawer on mobile (<768px)", async () => {
    setViewport(375);
    const { AdaptiveDialog } = await import("../adaptive-dialog");
    render(() => (
      <AdaptiveDialog open>
        <div data-testid="content">Hello</div>
      </AdaptiveDialog>
    ));
    // In sheet mode, content should have data-corvu-drawer-content
    const content = screen.getByTestId("content");
    expect(content).toBeTruthy();
    // The drawer container should exist
    const drawerContent = document.querySelector("[data-corvu-drawer-content]");
    expect(drawerContent).not.toBeNull();
  });

  it("renders Dialog on tablet+ (≥768px)", async () => {
    setViewport(768);
    const { AdaptiveDialog } = await import("../adaptive-dialog");
    render(() => (
      <AdaptiveDialog open>
        <div data-testid="content">Hello</div>
      </AdaptiveDialog>
    ));
    // In dialog mode, content should have role="dialog" from Kobalte
    const dialog = document.querySelector('[role="dialog"]');
    expect(dialog).not.toBeNull();
  });
});
```

