### Task 4: Create AdaptiveDialog root + context

**Files:**
- Create: `src/components/ui/adaptive-dialog.tsx`

**Step 1: Create the component with root + context**

The root establishes the mode (dialog vs sheet) via `useBreakpoints()`, provides it through context, and renders the matching primitive root.

```tsx
import type { JSX, ValidComponent } from "solid-js";
import { createContext, useContext, Show, splitProps } from "solid-js";
import type { Component, ComponentProps } from "solid-js";

import * as DialogPrimitive from "@kobalte/core/dialog";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import Drawer from "@corvu/drawer";

import { XCloseIcon } from "~/assets";
import { useBreakpoints } from "~/lib/breakpoints";
import { cn } from "~/lib/utils";

type AdaptiveMode = "dialog" | "sheet";

interface AdaptiveContextValue {
  mode: () => AdaptiveMode;
}

const AdaptiveDialogContext = createContext<AdaptiveContextValue>();

function useAdaptiveDialog() {
  const ctx = useContext(AdaptiveDialogContext);
  if (!ctx) {
    throw new Error(
      "AdaptiveDialog components must be used within <AdaptiveDialog>"
    );
  }
  return ctx;
}

// ── Root ─────────────────────────────────────────────────────────

interface AdaptiveDialogProps {
  children: JSX.Element;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  modal?: boolean;
}

function AdaptiveDialog(props: AdaptiveDialogProps) {
  const breakpoints = useBreakpoints();
  const mode = (): AdaptiveMode => (breakpoints.md ? "dialog" : "sheet");

  return (
    <AdaptiveDialogContext.Provider value={{ mode }}>
      <Show
        when={mode() === "dialog"}
        fallback={
          <Drawer
            defaultOpen={props.defaultOpen}
            modal={props.modal ?? true}
            onOpenChange={props.onOpenChange}
            open={props.open}
            side="bottom"
            snapPoints={[0, 1]}
          >
            {props.children}
          </Drawer>
        }
      >
        <DialogPrimitive.Root
          defaultOpen={props.defaultOpen}
          modal={props.modal ?? true}
          onOpenChange={props.onOpenChange}
          open={props.open}
        >
          {props.children}
        </DialogPrimitive.Root>
      </Show>
    </AdaptiveDialogContext.Provider>
  );
}
```

