function AdaptiveDialogTrigger<T extends ValidComponent = "button">(
  props: PolymorphicProps<T, AdaptiveDialogTriggerProps<T>>,
) {
  const ctx = useAdaptiveDialog();
  const [, rest] = splitProps(props as AdaptiveDialogTriggerProps, ["class"]);
  return (
    <Show
      when={ctx.mode() === "dialog"}
      fallback={<Drawer.Trigger {...rest} />}
    >
      <DialogPrimitive.Trigger {...rest} />
    </Show>
  );
}
