**`src/components/picker-field.tsx`** (implementation):

```tsx
import { createSignal, For, Show } from "solid-js";
import { ChevronDownIcon, CheckIcon, PlusIcon } from "~/assets";
import { SearchBar } from "~/components/search-bar";
import {
  AdaptiveDialog,
  AdaptiveDialogContent,
  AdaptiveDialogHeader,
  AdaptiveDialogTitle,
} from "~/components/ui/adaptive-dialog";
import { cn } from "~/lib/utils";

export interface PickerOption {
  readonly value: string;
  readonly label: string;
}

interface PickerFieldProps {
  readonly class?: string;
  readonly onCreate?: (query: string) => string; // returns new value
  readonly onInput?: (value: string) => void;    // search query callback
  readonly options: PickerOption[];
  readonly placeholder?: string;
  readonly title: string;                         // dialog title
  readonly value?: string;
}

export function PickerField(props: PickerFieldProps) {
  const [open, setOpen] = createSignal(false);
  const [query, setQuery] = createSignal("");

  const selected = () =>
    props.options.find((o) => o.value === props.value);

  const filtered = () => {
    const q = query().toLowerCase().trim();
    if (!q) return props.options;
    return props.options.filter((o) =>
      o.label.toLowerCase().includes(q),
    );
  };

  const canCreate = () => {
    if (!props.onCreate || !query().trim()) return false;
    // hide if exact match exists
    return !props.options.some(
      (o) => o.label.toLowerCase() === query().trim().toLowerCase(),
    );
  };

  const handleSelect = (value: string) => {
    props.onInput?.(value);
    setOpen(false);
    setQuery("");
  };

  const handleCreate = () => {
    const newValue = props.onCreate!(query().trim());
    handleSelect(newValue);
  };

  return (
    <AdaptiveDialog open={open()} onOpenChange={setOpen}>
      {/* ── Trigger button (looks like a TextFieldInput) ── */}
      <button
        type="button"
        onClick={() => setOpen(true)}
        class={cn(
          "flex h-12 w-full items-center justify-between rounded-sm border-2 border-input bg-background px-3.5 font-sans text-body-sm outline-none transition-colors duration-standard ease-standard",
          "hover:border-primary/50",
          "dark:hover:border-accent/50",
          props.class,
        )}
      >
        <span class={selected() ? "text-foreground" : "text-muted-foreground"}>
          {selected()?.label ?? props.placeholder}
        </span>
        <ChevronDownIcon class="size-4 shrink-0 text-muted-foreground" />
      </button>

      <AdaptiveDialogContent class="max-w-md">
        <AdaptiveDialogHeader>
          <AdaptiveDialogTitle>{props.title}</AdaptiveDialogTitle>
        </AdaptiveDialogHeader>

        <SearchBar
          mode="full"
          onInput={setQuery}
          placeholder="Cari..."
          value={query()}
        />

        <div class="scrollbar-none -mx-2 max-h-[50vh] overflow-y-auto px-2">
          {/* ── Create new (if query doesn't match) ── */}
          <Show when={canCreate()}>
            <button
              type="button"
              onClick={handleCreate}
              class="flex w-full items-center gap-2.5 rounded-sm px-3 py-3 text-left transition-colors hover:bg-muted"
            >
              <span class="grid size-7 shrink-0 place-items-center rounded-full bg-primary/10 text-primary">
                <PlusIcon class="size-4" />
              </span>
              <span class="text-body-sm text-muted-foreground">
                Buat kategori{" "}
                <span class="font-medium text-foreground">
                  "{query().trim()}"
                </span>
              </span>
            </button>
          </Show>

          {/* ── Options ── */}
          <For each={filtered()}>
            {(option) => (
              <button
                type="button"
                onClick={() => handleSelect(option.value)}
                class="flex w-full items-center justify-between rounded-sm px-3 py-3 text-left transition-colors hover:bg-muted"
              >
                <span class="text-body-sm text-foreground">
                  {option.label}
                </span>
                <Show when={option.value === props.value}>
                  <CheckIcon class="size-4 shrink-0 text-primary" />
                </Show>
              </button>
            )}
          </For>
        </div>
      </AdaptiveDialogContent>
    </AdaptiveDialog>
  );
}
```

---

**Usage in `product-form.tsx`:**

```tsx
// Category — with inline create
<PickerField
  title="Pilih Kategori"
  options={categories.map((c) => ({ value: c.id, label: c.name }))}
  value={category()}
  onInput={setCategory}
  onCreate={(query) => {
    const id = query.toLowerCase().replace(/\s+/g, "-");
    // In real app: API call, then add to list
    return id;
  }}
  placeholder="Pilih kategori"
/>

// Satuan — simple picker, no create
<PickerField
  title="Pilih Satuan"
  options={UNITS.map((u) => ({ value: u, label: u.charAt(0).toUpperCase() + u.slice(1) }))}
  value={unit()}
  onInput={setUnit}
  placeholder="Pilih satuan"
/>
```

---

**Key design decisions:**

| Decision | Rationale |
|---|---|
| `title` prop instead of `label` | The field button has no visible label (matching how the current `<select>` works with the external `<span>` label). The title is for the dialog header only |
| `onInput` for selection | Matches existing `TextField`/`NumberField` convention — the consumer controls the value signal |
| `onCreate` optional | Without it, no "create" row appears. Satuan picker is search-only |
| `canCreate()` checks exact match | You can create "Kopi" even if "Kopi Susu" exists — only hides when identical |
| Check icon for selected | Visual confirmation of current value when reopening |
| List items are full-width buttons | Entire row clickable, matches our list-item philosophy |

**One thing to flag:** The `onCreate` callback needs a way to add the new option to the list so it shows as selected with a checkmark. Currently `categories` is a static import. We'd need a local mutable copy in the form, or pass `options` as a signal. Want me to handle that in the form with a local `createSignal([...categories])`, or should `PickerField` manage its own internal option list?

You're right — `onInput` conflicts with search query semantics. It should be **`onChange`** to match `NumberField` and `TextField` conventions:

```tsx
interface PickerFieldProps {
  // ...
  readonly onChange: (value: string) => void;  // selection callback
  readonly value?: string;
}
```

Usage becomes:

```tsx
<PickerField
  title="Pilih Kategori"
  options={categories.map((c) => ({ value: c.id, label: c.name }))}
  value={category()}
  onChange={setCategory}
  onCreate={(query) => { ... }}
  placeholder="Pilih kategori"
/>
```

Clean — same `value`/`onChange` pair as every other field. Good to build?

Good question — with `fetch` it's async, so the signature needs to return a `Promise<string>`:

```tsx
interface PickerFieldProps {
  readonly onCreate?: (query: string) => Promise<string>;
}
```

The component internally handles loading + error states. Usage in `product-form.tsx`:

```tsx
const [options, setOptions] = createSignal([...categories]);

<PickerField
  title="Pilih Kategori"
  options={options()}
  value={category()}
  onChange={setCategory}
  placeholder="Pilih kategori"
  onCreate={async (query) => {
    const res = await fetch("/api/categories", {
      method: "POST",
      body: JSON.stringify({ name: query }),
    });
    if (!res.ok) {
      throw new Error("Gagal membuat kategori");
    }
    const cat = await res.json();
    // Update the list so it shows in future searches + gets the checkmark
    setOptions((prev) => [...prev, cat]);
    return cat.id;  // PickerField sets this as the selected value
  }}
/>
```

**Inside PickerField, `handleCreate` becomes:**

```tsx
const [creating, setCreating] = createSignal(false);

const handleCreate = async () => {
  try {
    setCreating(true);
    const newValue = await props.onCreate!(query().trim());
    handleSelect(newValue);  // close dialog, set value
  } catch (err) {
    toast.error(err.message);  // or onError prop
  } finally {
    setCreating(false);
  }
};
```

**What happens:**
1. User types "Promo" → no match → "Buat kategori **'Promo'**" row appears
2. Click → button shows spinner, disabled
3. Fetch resolves → new option added to list → value set → dialog closes
4. If fetch fails → toast error, dialog stays open, user can retry

**The key contract:** `onCreate` returns the new option's `value` (the ID), and the caller is responsible for adding it to the `options` array they pass in. That way `PickerField` stays dumb — it doesn't manage option lists, only the search/filter/select/create-loading flow.

Should `onError` be a separate prop or just let `onCreate` throw? I lean toward: let it throw, component shows toast, simpler API.

