import type { JSX } from "solid-js";
import { createSignal, For, Show } from "solid-js";
import { ChevronDownIcon, CheckIcon, PlusIcon } from "~/assets";
import { SearchBar } from "~/components/search-bar";
import {
  AdaptiveDialog,
  AdaptiveDialogContent,
  AdaptiveDialogHeader,
  AdaptiveDialogTitle,
} from "~/components/ui/adaptive-dialog";
import { cn } from "~/lib/utils";

export interface PickerOption {
  readonly value: string;
  readonly label: string;
}

interface PickerFieldProps {
  readonly class?: string;
  readonly onChange?: (value: string) => void;
  readonly onCreate?: (query: string) => Promise<string>;
  readonly options: PickerOption[];
  readonly placeholder?: string;
  readonly title: string;
  readonly value?: string;
}

export function PickerField(props: PickerFieldProps) {
  const [open, setOpen] = createSignal(false);
  const [query, setQuery] = createSignal("");
  const [creating, setCreating] = createSignal(false);

  const selected = () =>
    props.options.find((o) => o.value === props.value);

  const filtered = () => {
    const q = query().toLowerCase().trim();
    if (!q) {
      return props.options;
    }
    return props.options.filter((o) =>
      o.label.toLowerCase().includes(q),
    );
  };

  const canCreate = () => {
    if (!props.onCreate || !query().trim()) {
      return false;
    }
    return !props.options.some(
      (o) => o.label.toLowerCase() === query().trim().toLowerCase(),
    );
  };

  const handleSelect = (value: string) => {
    props.onChange?.(value);
    setOpen(false);
    setQuery("");
  };

  const handleCreate = async () => {
    if (creating()) {
      return;
    }
    try {
      setCreating(true);
      const newValue = await props.onCreate!(query().trim());
      handleSelect(newValue);
    } finally {
      setCreating(false);
    }
  };

  return (
    <AdaptiveDialog open={open()} onOpenChange={setOpen}>
      <button
        type="button"
        onClick={() => setOpen(true)}
        class={cn(
          "flex h-12 w-full items-center justify-between rounded-sm border-2 border-input bg-background px-3.5 font-sans text-body-sm outline-none transition-colors duration-standard ease-standard",
          "hover:border-primary/50 dark:hover:border-accent/50",
          props.class,
        )}
      >
        <span class={selected() ? "text-foreground" : "text-muted-foreground"}>
          {selected()?.label ?? props.placeholder}
        </span>
        <ChevronDownIcon class="size-4 shrink-0 text-muted-foreground" />
      </button>

      <AdaptiveDialogContent class="max-w-md">
        <AdaptiveDialogHeader>
          <AdaptiveDialogTitle>{props.title}</AdaptiveDialogTitle>
        </AdaptiveDialogHeader>

        <SearchBar
          mode="full"
          onInput={setQuery}
          placeholder="Cari..."
          value={query()}
        />

        <div class="scrollbar-none -mx-2 max-h-[50vh] overflow-y-auto px-2">
          {/* ── Create new ── */}
          <Show when={canCreate()}>
            <button
              type="button"
              disabled={creating()}
              onClick={handleCreate}
              class="flex w-full items-center gap-2.5 rounded-sm px-3 py-3 text-left transition-colors hover:bg-muted disabled:opacity-50"
            >
