import { render, screen } from "@solidjs/testing-library";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// ── matchMedia mock ──
let mockMatches: Record<string, boolean> = {};
const MIN_WIDTH_RE = /\(min-width:\s*([\d.]+)px\)/;

const mockMatchMedia = (query: string): MediaQueryList => {
  const match = query.match(MIN_WIDTH_RE);
  const threshold = match
    ? Number.parseFloat(match[1])
    : Number.POSITIVE_INFINITY;
  const matches = mockMatches[`${threshold}`] ?? false;
  return {
    matches,
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    addListener: vi.fn(),
    removeListener: vi.fn(),
    dispatchEvent: vi.fn(),
  } as unknown as MediaQueryList;
};

const setViewport = (width: number) => {
  mockMatches = {};
  if (width >= 600) mockMatches["600"] = true;
  if (width >= 768) mockMatches["768"] = true;
  if (width >= 900) mockMatches["900"] = true;
};

// ── Mock ResizeObserver (corvu drawer) ──
globalThis.ResizeObserver = vi.fn().mockImplementation(() => ({
  observe: vi.fn(),
  unobserve: vi.fn(),
  disconnect: vi.fn(),
}));

// Mock window.matchMedia
beforeEach(() => {
  setViewport(1200);
  window.matchMedia = vi.fn().mockImplementation(mockMatchMedia);
});

afterEach(() => {
  vi.restoreAllMocks();
  mockMatches = {};
});

// ── Mock child components to isolate tab animation logic ──
vi.mock("../components/product-tab", () => ({
  ProductTab: () => <div data-testid="product-panel">Product</div>,
}));
vi.mock("../components/variant-tab", () => ({
  VariantTab: () => <div data-testid="variant-panel">Variant</div>,
}));
vi.mock("../components/category-tab", () => ({
  CategoryTab: () => <div data-testid="category-panel">Category</div>,
}));
vi.mock("../components/speed-dial-fab", () => ({
  SpeedDialFab: () => null,
}));

// ── RequestAnimationFrame mock to detect animation scheduling ──
let rafCallbacks: FrameRequestCallback[] = [];
beforeEach(() => {
  rafCallbacks = [];
  vi.spyOn(globalThis, "requestAnimationFrame").mockImplementation(
    (cb: FrameRequestCallback) => {
      rafCallbacks.push(cb);
      return rafCallbacks.length;
    },
  );
});

const flushRaf = () => {
  const callbacks = [...rafafCallbacks];
  rafCallbacks = [];
  callbacks.forEach((cb) => cb(0));
};

describe("CatalogPage tab slide animation", () => {
  it("applies slide-right animation class when moving to a higher tab", async () => {
    const user = userEvent.setup();
    const CatalogPage = (await import("../index")).default;
    render(() => <CatalogPage />);

    // Initial state: produk tab active
    expect(screen.getByTestId("product-panel")).toBeTruthy();

    // Click varian
    await user.click(screen.getByText("Varian"));

    // Panel should have a slide-right animation class
    const panel = screen.getByTestId("variant-panel").parentElement;
    expect(panel?.className).toContain("slide");
    expect(panel?.className).toContain("right");
  });

  it("applies slide-left animation class when moving to a lower tab", async () => {
    const user = userEvent.setup();
    const CatalogPage = (await import("../index")).default;
    render(() => <CatalogPage />);

    // Go to kategori first (rightward)
    await user.click(screen.getByText("Kategori"));
    // Then back to produk (leftward)
    await user.click(screen.getByText("Produk"));

    const panel = screen.getByTestId("product-panel").parentElement;
    expect(panel?.className).toContain("slide");
    expect(panel?.className).toContain("left");
  });

  it("triggers animation on first tab change (not just second)", async () => {
    const user = userEvent.setup();
    const CatalogPage = (await import("../index")).default;
    render(() => <CatalogPage />);

    // First tab change: produk → varian
    await user.click(screen.getByText("Varian"));

    const panel = screen.getByTestId("variant-panel").parentElement;
    // The animation class should be present on FIRST change, not just second
    expect(panel?.className).toContain("slide");
  });
});

