import type { SsgoiConfig, SsgoiPathTransition } from "@ssgoi/solid";
import { axis, drill, fade } from "@ssgoi/solid/view-transitions";

/* ── Path groups ─────────────────────────────────────────────────── */

const SHELL_PATHS = ["/", "/transactions", "/inventory", "/setting"] as const;
const AUTH_PATHS = ["/auth/login", "/auth/register", "/auth/pin"] as const;

/* ── Root config factory ───────────────────────────────────────────
   Pure: takes the current orientation so the caller can drive it
   reactively (matchMedia). Portrait screens slide on X (feels like
   swiping pages); landscape screens slide on Y (feels like scrolling
   sections). The axis choice is made per-navigation, not cached at
   module load. */
export function createRootConfig(isPortrait: boolean): SsgoiConfig {
  const shellSlides: SsgoiPathTransition[] = isPortrait
    ? axis({ paths: [...SHELL_PATHS], type: "x", variant: "snappy" })
    : axis({ paths: [...SHELL_PATHS], type: "y", variant: "default" });

  return {
    transitions: [
      // Shell ↔ Shell
      ...shellSlides,

      // Flow → Flow: drill parallax
      drill({
        enter: "/transactions/payment",
        exit: "/transactions/cash-register",
        type: "parallax",
      }),
      drill({
        enter: "/transactions/receipt",
        exit: "/transactions/payment",
        type: "parallax",
      }),

      // Auth ↔ Auth: fade
      fade({ paths: [...AUTH_PATHS] }),

      // Shell → Flow: drill in (any shell page → cash-register)
      drill({
        enter: "/transactions/cash-register",
        exit: "/",
        type: "parallax",
      }),
      drill({
        enter: "/transactions/cash-register",
        exit: "/transactions",
        type: "parallax",
      }),
      drill({
        enter: "/transactions/cash-register",
        exit: "/setting",
        type: "parallax",
      }),
      drill({
        enter: "/transactions/cash-register",
        exit: "/inventory",
        type: "parallax",
      }),

      // Shell → Catalog (drill in from dashboard)
      drill({ enter: "/catalog", exit: "/", type: "parallax" }),

      // Setting → section sub-pages (mobile drill-in, like iOS Settings)
      drill({ enter: "/setting/*", exit: "/setting", type: "parallax" }),

      // Catalog → form sub-pages (full-screen drill-in)
      drill({
        enter: "/catalog/category/*",
        exit: "/catalog",
        type: "parallax",
      }),
      drill({
        enter: "/catalog/variant/*",
        exit: "/catalog",
        type: "parallax",
      }),
      drill({
        enter: "/catalog/product/*",
        exit: "/catalog",
        type: "parallax",
      }),
    ],
  };
}

import type { PhysicsOptions } from "@types";
import type {
  AxisAnimationConfig,
  AxisProvider,
  AxisProviderBuildArgs,
} from "../../types";

// "Snappy" x — modeled after **KakaoTalk**'s tab/page swap on iOS/Android.
// Outgoing stays in place and only fades; incoming slides in a very short
// distance while fading up. The whole motion lands fast and decisively, giving
// the messenger-app "tactile tap" feel rather than a Material settle.
//
// Differences from Flutter's SharedAxisTransition (which the `fluid` x sibling
// implements):
//   - No out-slide. Outgoing only fades.
//   - 8 px slide vs. Flutter's 30. Flutter's 30 is in dp on a dpi-scaled
//     device; our mobile showcase renders 1:1 so 30 reads as a much bigger
//     shift than Material intended. Korean messenger apps also use a more
//     minimal slide than Material defaults.
//   - Parallel cross-fade (both sides fade simultaneously), not fade-through.
//   - Very stiff spring — lands around ~160 ms.
const KAKAO_SLIDE_PX = 8;

// Loosen the settle thresholds 10× over the integrator defaults
// (0.01 → 0.1 for both position and velocity). With a very stiff spring the
// tail past ~98% is visually indistinguishable but still simulates for a few
// extra frames; bumping the thresholds lets the snappy x land sooner without
// changing the perceived motion.
const SNAPPY_PHYSICS: PhysicsOptions = {
  spring: {
    stiffness: 1000,
    damping: 40,
    doubleSpring: 1.2,
    restDelta: 0.1,
    restSpeed: 0.1,
  },
};

function buildSnappyX({
  direction,
}: AxisProviderBuildArgs): AxisAnimationConfig {
  // forward: incoming arrives from the right.
  // backward: incoming arrives from the left.
  const inStart = direction === "forward" ? KAKAO_SLIDE_PX : -KAKAO_SLIDE_PX;

  return {
    out: {
      willChange: "transform, opacity",
      startStyle: {},
      animate: (t) => ({
        opacity: `${1 - t}`,
      }),
    },
    in: {
      willChange: "transform, opacity",
      startStyle: {
        transform: `translate3d(${inStart}px, 0, 0)`,
        opacity: "0",
      },
      animate: (t) => ({
        transform: `translate3d(${inStart * (1 - t)}px, 0, 0)`,
        opacity: `${t}`,
      }),
    },
  };
}

export function createSnappyXProvider(): AxisProvider {
  return {
    outPhysics: SNAPPY_PHYSICS,
    inPhysics: SNAPPY_PHYSICS,
    // Both sides run together — the cross-fade is the whole point of the
    // snappy feel. (fluid's sibling uses staggered fade-through.)
    composition: { mode: "parallel", startAt: [0, 0] },
    build: buildSnappyX,
  };
}

import type { PhysicsOptions } from "@types";
import type {
  AxisAnimationConfig,
  AxisProvider,
  AxisProviderBuildArgs,
} from "../../types";

// "Fluid" x — Material SharedAxisTransition (horizontal) decomposed into two
// sequential physics phases instead of a single staggered ramp.
//
//   1. Outgoing falls away under an inertia integrator (acceleration + drag).
//      Position 0→1 naturally curves slow-then-fast, giving the Material
//      "legacyAccelerate" out-fade shape for free.
//   2. Once it settles, incoming arrives on a stiffer spring tuned ~2× the
//      perceived speed of the out phase. Spring's slow-settle tail gives the
//      "legacyDecelerate" in-fade shape.
//
// The sequence composition handles the stagger, so each `animate(t)` is a
// straight 0→1 slide+fade — no FADE_SPLIT, no easing branches.
// The sibling `snappy` x is the KakaoTalk-style flavor — parallel cross-fade.
const TRANSLATE_PX = 30;

// All axis providers loosen settle thresholds 10× over the integrator
// defaults (0.01 → 0.1) so the imperceptible tail of each phase doesn't
// hold up the sequence handoff or the page lifecycle.
const FLUID_OUT_PHYSICS: PhysicsOptions = {
  inertia: { acceleration: 150, resistance: 1.5, restDelta: 0.1 },
};

const FLUID_IN_PHYSICS: PhysicsOptions = {
  spring: { stiffness: 180, damping: 34, restDelta: 0.1, restSpeed: 0.1 },
};

function buildFluidX({
  direction,
}: AxisProviderBuildArgs): AxisAnimationConfig {
  // forward: outgoing slides left, incoming arrives from the right.
  // backward: mirrored.
  const sign = direction === "forward" ? 1 : -1;
  const outTarget = -TRANSLATE_PX * sign;
  const inStart = TRANSLATE_PX * sign;

  return {
    out: {
      willChange: "transform, opacity",
      startStyle: {},
      animate: (t) => ({
        transform: `translate3d(${outTarget * t}px, 0, 0)`,
        opacity: `${1 - t}`,
      }),
    },
    in: {
      willChange: "transform, opacity",
      startStyle: {
        transform: `translate3d(${inStart}px, 0, 0)`,
        opacity: "0",
      },
      animate: (t) => ({
        transform: `translate3d(${inStart * (1 - t)}px, 0, 0)`,
        opacity: `${t}`,
      }),
    },
  };
}

export function createFluidXProvider(): AxisProvider {
  return {
    outPhysics: FLUID_OUT_PHYSICS,
    inPhysics: FLUID_IN_PHYSICS,
    // Phased motion: outgoing falls away first under inertia, then incoming
    // springs in. The fade-through shape comes from the integrator curves
    // plus the sequence handoff, not from FADE_SPLIT inside animate(t).
    composition: { mode: "sequence" },
    build: buildFluidX,
  };
}

import { createSnappyXProvider } from "./snappy";
import { createFluidXProvider } from "./fluid";
import type { AxisFeel, AxisProvider } from "../../types";

// X axis has two UX flavors — sibling providers selected by `feel`.
//   - snappy: KakaoTalk-style. Tight, fast, parallel cross-fade, 8 px slide.
//   - fluid:  Flutter SharedAxisTransition. Relaxed, fade-through, 30 px slide.
//
// Other feel values in AxisFeel (e.g. directional/non-directional, which only
// y uses) are absent here — resolveAxisProvider falls back to `snappy`.
export const X_PROVIDERS: { snappy: AxisProvider } & Partial<
  Record<AxisFeel, AxisProvider>
> = {
  snappy: createSnappyXProvider(),
  fluid: createFluidXProvider(),
};

import type { TransitionConfig } from "@types";
import {
  IntegratorProvider,
  MultiAnimation,
  WebAnimation,
} from "../../animation";
import { getViewportRect } from "@utils";
import { resolveAxisProvider } from "./provider";
import type { AxisFeel, AxisOptions, AxisSideConfig, AxisType } from "./types";

export type { AxisFeel, AxisOptions, AxisType } from "./types";

const DEFAULT_TYPE: AxisType = "x";
const DEFAULT_FEEL: AxisFeel = "snappy";

function applyStartStyle(el: HTMLElement, side: AxisSideConfig): void {
  el.style.willChange = side.willChange;
  el.style.backfaceVisibility = "hidden";
  (el.style as CSSStyleDeclaration & { contain: string }).contain =
    "layout paint";
  for (const [key, value] of Object.entries(side.startStyle)) {
    (el.style as unknown as Record<string, string | number>)[key] = value;
  }
}

function clearStyle(el: HTMLElement): void {
  el.style.willChange = "auto";
  el.style.backfaceVisibility = "";
  (el.style as CSSStyleDeclaration & { contain: string }).contain = "";
  el.style.transform = "";
  el.style.opacity = "";
  el.style.clipPath = "";
}

// The outgoing (from) element is now the real, reused page node (React
// Activity / Next cacheComponents) rather than a throwaway clone, so every
// inline style we set on it must be cleared when the out animation completes —
// otherwise the re-hidden node reappears stuck (invisible / translated /
// non-interactive) on the next navigation. Mirrors `clearStyle` (the in-side
// template) plus the out-only `pointerEvents` we set in `prepare`.
function clearFromStyle(el: HTMLElement): void {
  clearStyle(el);
  el.style.pointerEvents = "";
}

export const axis = (options: AxisOptions = {}): TransitionConfig => {
  const direction = options.direction ?? "forward";
  const type = options.type ?? DEFAULT_TYPE;
  const feel = options.feel ?? DEFAULT_FEEL;
  const provider = resolveAxisProvider(type, feel);
  const config = provider.build({ direction });

  return {
    prepare: ({ from, to }) => {
      from.then((el) => {
        applyStartStyle(el, config.out);
        el.style.pointerEvents = "none";
      });
      to.then((el) => {
        applyStartStyle(el, config.in);
      });
      return {};
    },
    animation: ({ from, to, context }) => {
      // Z scales the page element in place. Without clipping to the viewport
      // slice, scale-up paints over chrome / scroll overflow and scale-down
      // exposes neighbouring layout. Mirror sheet's inset trick.
      if (type === "z") {
        const fromRect = getViewportRect(context, "from");
        const toRect = getViewportRect(context, "to");
        from.style.clipPath = `inset(${fromRect.top}px 0 calc(100% - ${fromRect.top + fromRect.height}px) 0)`;
        to.style.clipPath = `inset(${toRect.top}px 0 calc(100% - ${toRect.top + toRect.height}px) 0)`;
      }

      const outAnim = new WebAnimation({
        element: from,
        integrator: IntegratorProvider.from(provider.outPhysics),
        style: (t) => config.out.animate(t),
        // Restore the reused from node's inline styles on complete. This
        // covers willChange/backfaceVisibility/contain/transform/opacity (from
        // applyStartStyle + the WAAPI final frame), pointerEvents (set in
        // prepare), and clipPath (set above for z; harmless no-op otherwise).
        onComplete: () => clearFromStyle(from),
      });

      const inAnim = new WebAnimation({
        element: to,
        integrator: IntegratorProvider.from(provider.inPhysics),
        style: (t) => config.in.animate(t),
        onComplete: () => clearStyle(to),
      });

      // Composition (mode / startAt overlap) is decided by the provider —
      // x, y, z have meaningfully different timings, so this file just
      // forwards what the provider gives us.
      return new MultiAnimation([outAnim, inAnim], provider.composition);
    },
  };
};

import type { PhysicsOptions, StyleObject } from "@types";
import type { MultiAnimationOptions } from "../../animation/multi-animation";

export type AxisType = "x" | "y" | "z";
export type AxisDirection = "forward" | "backward";

/**
 * UX flavor *within* a single axis. Independent dimension from `AxisType`; the
 * set of meaningful values differs per type:
 *   - x: `snappy` (KakaoTalk tab swap) | `fluid` (Material SharedAxisTransition)
 *   - y: `directional` (forward = bottom→top) | `non-directional` (in always
 *     rises from below; out fades in place)
 *   - z: `snappy` only
 *
 * Providers may alias unsupported feels to an in-axis default — `snappy` is
 * the universal fallback inside `resolveAxisProvider`.
 */
export type AxisFeel = "snappy" | "fluid" | "directional" | "non-directional";

export interface AxisOptions {
  type?: AxisType;
  direction?: AxisDirection;
  feel?: AxisFeel;
}

export type AxisAnimateFunc = (progress: number) => StyleObject;

export interface AxisSideConfig {
  willChange: string;
  startStyle: StyleObject;
  animate: AxisAnimateFunc;
}

export interface AxisAnimationConfig {
  out: AxisSideConfig;
  in: AxisSideConfig;
}

export interface AxisProviderBuildArgs {
  direction: AxisDirection;
}

export interface AxisProvider {
  /**
   * Physics for the outgoing side. Split from `inPhysics` so a provider can
   * mix integrators (e.g. fluid's x uses inertia for out + spring for in, so
   * the outgoing page falls away under acceleration while the incoming page
   * springs into place).
   */
  outPhysics: PhysicsOptions;
  /** Physics for the incoming side. */
  inPhysics: PhysicsOptions;
  /**
   * How the out/in animations compose. Each axis has its own timing (e.g. x/y
   * use a slight startAt offset for cross-fade overlap, z runs both in place
   * and typically starts together). Provider decides — transition.ts just
   * forwards this to MultiAnimation.
   */
  composition?: MultiAnimationOptions;
  /** `direction` is only meaningful for the sided providers (x, y). */
  build: (args: AxisProviderBuildArgs) => AxisAnimationConfig;
}

import type { Pose, StyleObject, Timeline, TimelineFrame } from "@types";
import {
  type Integrator,
  type IntegratorState,
  SETTLE_THRESHOLD,
} from "./integrator";
import { Animation } from "./animation";

const FRAME_TIME = 1000 / 60;

export interface WebAnimationOptions {
  element: HTMLElement;
  integrator: Integrator;
  style: (t: number, u: number) => StyleObject;
  /** Default 0 — the value `t` takes at the start of `play()`. */
  lowerBound?: number;
  /** Default 1 — the value `t` takes at the end of `play()`. */
  upperBound?: number;
  onUpdate?: (poses: Pose[]) => void;
  onComplete?: () => void;
}

interface SimFrame {
  time: number;
  position: number;
  velocity: number;
}

/**
 * Single-element animation driven by an Integrator simulation, played through
 * the Web Animation API.
 *
 * Lifecycle:
 *   1. `play()` / `reverse()` calls `simulate()` from the current (position,
 *      velocity) toward the target bound, producing a frame list.
 *   2. Frames are converted to WAAPI keyframes; `element.animate(...)` runs them.
 *   3. While playing, `getPose()` interpolates the live position from frames
 *      using `performance.now() - startTime`.
 *
 * Identity for motion matching is the DOM element itself — when a previous
 * animation's pose is handed in via `matchInto`, we look up by element.
 */
export class WebAnimation extends Animation {
  private element: HTMLElement;
  private integrator: Integrator;
  private styleFn: (t: number, u: number) => StyleObject;
  private lowerBound: number;
  private upperBound: number;

  private currentValue: number;
  private currentVelocity = 0;
  private frames: SimFrame[] = [];
  private waapi: globalThis.Animation | null = null;
  private startTime = 0;
  private running = false;
  private paused = false;
  private settled = false;
  private reversing = false;

  constructor(opts: WebAnimationOptions) {
    super();
    this.element = opts.element;
    this.integrator = opts.integrator;
    this.styleFn = opts.style;
    this.lowerBound = opts.lowerBound ?? 0;
    this.upperBound = opts.upperBound ?? 1;
    this.currentValue = this.lowerBound;
    this.onUpdate = opts.onUpdate;
    this.onComplete = opts.onComplete;
  }

  play(): void {
    this.reversing = false;
    if (this.paused && this.waapi) {
      // Resume the same WAAPI run — currentTime is preserved, so motion
      // continues exactly where it was halted.
      this.paused = false;
      this.running = true;
      this.waapi.play();
      return;
    }
    this.runToward(this.upperBound);
  }

  reverse(): void {
    this.reversing = true;
    // Reverse from a paused state always starts a fresh spring sim from the
    // current pose toward lowerBound — keyframes were baked forward, so
    // flipping playbackRate would replay the wrong path.
    this.runToward(this.lowerBound);
  }

  pause(): void {
    if (!this.running) return;
    // WAAPI's own pause keeps the forwards-fill visual and lets `play()`
    // resume from the exact frame — no inline-style pinning needed.
    this.captureLiveState();
    this.waapi?.pause();
    this.running = false;
    this.paused = true;
  }

  complete(): void {
    this.clearWaapi();
    this.running = false;
    this.paused = false;
    this.currentValue = this.upperBound;
    this.currentVelocity = 0;
    this.applyStyleAt(this.currentValue);
    this.settled = true;
    this.onComplete?.();
  }

  /**
   * Drop the WAAPI forwards-fill after the run has settled, letting inline
   * styles govern the resting visual. Call only from `onComplete` (the run is
   * already finished) — otherwise it cancels mid-flight. Unlike `complete()`,
   * it writes no final frame, so a caller can reset the element to its natural
   * state without the lingering fill clobbering it.
   */
  releaseFill(): void {
    this.clearWaapi();
  }

  get isAnimating(): boolean {
    return this.running;
  }
  get isPaused(): boolean {
    return this.paused;
  }
  get isComplete(): boolean {
    return this.settled;
  }
  get isReversing(): boolean {
    return this.reversing;
  }

  get progress(): number {
    if (this.running) this.captureLiveState();
    const span = this.upperBound - this.lowerBound;
    if (span === 0) return 0;
    const p = (this.currentValue - this.lowerBound) / span;
    return p < 0 ? 0 : p > 1 ? 1 : p;
  }

  findTimeForProgress(threshold: number): number | null {
    if (this.frames.length < 2) return null;
    const span = this.upperBound - this.lowerBound;
    if (span === 0) return 0;
    // Walk frames directly — no per-frame style synthesis, no allocations.
    // For underdamped springs that overshoot, "first crossing" is the right
    // semantic: trigger when progress first reaches the threshold, not when
    // it settles there.
    for (const f of this.frames) {
      if ((f.position - this.lowerBound) / span >= threshold) return f.time;
    }
    return this.frames[this.frames.length - 1]!.time;
  }

  get playbackRate(): number {
    return super.playbackRate;
  }
  set playbackRate(rate: number) {
    super.playbackRate = rate;
    if (this.waapi) this.waapi.playbackRate = rate;
  }

  getPose(): Pose[] {
    if (this.running) this.captureLiveState();
    // Note: captureLiveState mutates currentValue/currentVelocity but doesn't
    // pause the WAAPI animation — visual playback continues, the pose just
    // reflects the live state at this instant.
    return [
      {
        element: this.element,
        value: this.currentValue,
        velocity: this.currentVelocity,
      },
    ];
  }

  getTimeline(): Timeline[] {
    const frames: TimelineFrame[] = this.frames.map((f) => {
      const t = f.position;
      const u = this.lowerBound + this.upperBound - t;
      return {
        time: f.time,
        value: f.position,
        velocity: f.velocity,
        style: this.styleFn(t, u),
      };
    });
    return [{ element: this.element, frames }];
  }

  matchInto(poses: Pose[]): void {
    const match = poses.find((p) => p.element === this.element);
    if (!match) return;
    this.currentValue = match.value;
    this.currentVelocity = match.velocity;
  }

  /* ───────────────────────────────────────────────────────── private */

  private runToward(target: number) {
    if (this.running) this.captureLiveState();
    this.clearWaapi();
    this.running = false;
    this.paused = false;
    this.settled = false;

    this.frames = simulate(
      this.integrator,
      this.currentValue,
      target,
      this.currentVelocity,
    );

    if (this.frames.length === 0) {
      this.currentValue = target;
      this.currentVelocity = 0;
      this.applyStyleAt(target);
      this.settled = true;
      this.onComplete?.();
      return;
    }

    const keyframes: Keyframe[] = this.frames.map((f) => {
      const t = f.position;
      const u = this.lowerBound + this.upperBound - t;
      return this.styleFn(t, u) as Keyframe;
    });

    // Clear inline styles for animated props so they don't clash with WAAPI.
    const firstFrame = keyframes[0];
    if (firstFrame) {
      for (const prop of Object.keys(firstFrame)) {
        (this.element.style as unknown as Record<string, string>)[prop] = "";
      }
    }

    const lastFrame = this.frames[this.frames.length - 1]!;
    const duration = lastFrame.time;

    this.waapi = this.element.animate(keyframes, {
      duration,
      fill: "forwards",
      easing: "linear",
      composite: "replace",
    });
    this.waapi.playbackRate = this.playbackRate;

    this.startTime = performance.now();
    this.running = true;

    this.waapi.onfinish = () => {
      if (!this.running) return;
      this.running = false;
      this.settled = true;
      this.currentValue = lastFrame.position;
      this.currentVelocity = 0;
      this.onComplete?.();
    };
  }

  private clearWaapi() {
    this.waapi?.cancel();
    this.waapi = null;
  }

  private captureLiveState() {
    if (this.frames.length === 0) return;
    const elapsed = performance.now() - this.startTime;
    const { position, velocity } = interpolateFrame(this.frames, elapsed);
    this.currentValue = position;
    this.currentVelocity = velocity;
  }

  private applyStyleAt(value: number) {
    const u = this.lowerBound + this.upperBound - value;
    const style = this.styleFn(value, u);
    for (const [key, val] of Object.entries(style)) {
      (this.element.style as unknown as Record<string, string>)[key] =
        typeof val === "number" ? String(val) : val;
    }
  }
}

/* ────────────────────────────────────────────────────────────────────────────
 * Simulation helpers
 * ──────────────────────────────────────────────────────────────────────────── */

function simulate(
  integrator: Integrator,
  from: number,
  to: number,
  initialVelocity: number,
): SimFrame[] {
  if (from === to && initialVelocity === 0) return [];

  const MAX_FRAMES = 600;
  let state: IntegratorState = { position: from, velocity: initialVelocity };
  let settleTime = 0;
  const frames: SimFrame[] = [];

  for (let i = 0; i < MAX_FRAMES; i++) {
    const time = i * FRAME_TIME;
    frames.push({ time, position: state.position, velocity: state.velocity });

    state = integrator.step(state, to, FRAME_TIME / 1000);

    if (integrator.isSettled(state, to)) {
      settleTime += FRAME_TIME / 1000;
      if (settleTime >= SETTLE_THRESHOLD) {
        frames.push({
          time: (i + 1) * FRAME_TIME,
          position: to,
          velocity: 0,
        });
        break;
      }
    } else {
      settleTime = 0;
    }
  }

  return frames;
}

function interpolateFrame(
  frames: SimFrame[],
  elapsed: number,
): { position: number; velocity: number } {
  if (frames.length === 0) return { position: 0, velocity: 0 };

  const first = frames[0]!;
  const last = frames[frames.length - 1]!;

  if (elapsed <= 0)
    return { position: first.position, velocity: first.velocity };
  if (elapsed >= last.time)
    return { position: last.position, velocity: last.velocity };

  let lo = 0;
  let hi = frames.length - 1;
  while (lo < hi - 1) {
    const mid = (lo + hi) >> 1;
    if (frames[mid]!.time <= elapsed) lo = mid;
    else hi = mid;
  }
  const a = frames[lo]!;
  const b = frames[hi]!;
  const t = (elapsed - a.time) / (b.time - a.time);
  return {
    position: a.position + (b.position - a.position) * t,
    velocity: a.velocity + (b.velocity - a.velocity) * t,
  };
}

