import { createEffect, createSignal, on, Show } from "solid-js";
import { SubPageShell } from "~/components/layout/sub-page-shell/sub-page-shell";
import {
  Tabs,
  TabsIndicator,
  TabsList,
  TabsTrigger,
} from "~/components/ui/tabs";
import { CategoryTab } from "./components/category-tab";
import { ProductTab } from "./components/product-tab";
import { SpeedDialFab } from "./components/speed-dial-fab";
import { VariantTab } from "./components/variant-tab";

const TAB_ORDER = ["produk", "varian", "kategori"] as const;
type TabKey = (typeof TAB_ORDER)[number];

// WAAPI slide constants (inspired by ssgoi's snappy X provider).
// translate3d for GPU compositor; 30px offset; fill: forwards so the
// final opacity:1 / translate3d(0,0,0) persists after animation ends.
const SLIDE_PX = 30;
const SLIDE_DURATION = 250;
const SLIDE_EASING = "cubic-bezier(0.4, 0, 0.2, 1)";

export default function CatalogPage() {
  const [tab, setTab] = createSignal<TabKey>("produk");
  let panelEl: HTMLDivElement | undefined;

  // Directional slide on tab change.
  // `on(tab, fn)` gives us (newTab, prevTab) — direction is computed from
  // indices inside the effect, eliminating stale signal reads.
  // element.animate() plays instantly on creation — no two-phase rAF.
  createEffect(
    on(tab, (newTab, prevTab) => {
      if (prevTab === undefined || !panelEl) return;

      const newIdx = TAB_ORDER.indexOf(newTab);
      const oldIdx = TAB_ORDER.indexOf(prevTab);
      const dir = newIdx >= oldIdx ? 1 : -1;

      panelEl.animate(
        [
          {
            opacity: 0,
            transform: `translate3d(${dir * SLIDE_PX}px, 0, 0)`,
          },
          { opacity: 1, transform: "translate3d(0, 0, 0)" },
        ],
        {
          duration: SLIDE_DURATION,
          easing: SLIDE_EASING,
          fill: "forwards",
        },
      );
    }),
  );

  return (
    <SubPageShell backHref="/" data-ssgoi-transition="/catalog" title="Katalog">
      <div class="flex flex-1 flex-col overflow-hidden">
        <Tabs
          class="flex flex-1 flex-col overflow-hidden"
          onChange={(v) => setTab(v as TabKey)}
          value={tab()}
        >
          <div class="relative shrink-0 border-border border-b">
            <TabsList class="relative flex w-full">
              <TabsTrigger class="flex-1" value="produk">
                Produk
              </TabsTrigger>
              <TabsTrigger class="flex-1" value="varian">
                Varian
              </TabsTrigger>
              <TabsTrigger class="flex-1" value="kategori">
                Kategori
              </TabsTrigger>
              <TabsIndicator class="bg-primary" />
            </TabsList>
          </div>

          {/* Stable wrapper — ref survives tab changes.
              Content swaps via Show; WAAPI animates the wrapper. */}
          <div ref={panelEl} class="relative flex-1 overflow-hidden">
            <Show when={tab() === "produk"}>
              <ProductTab />
            </Show>
            <Show when={tab() === "varian"}>
              <VariantTab />
            </Show>
            <Show when={tab() === "kategori"}>
              <CategoryTab />
            </Show>
          </div>
        </Tabs>
      </div>

      <SpeedDialFab />
    </SubPageShell>
  );
}

