import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import * as TabsPrimitive from "@kobalte/core/tabs";
import {
  createContext,
  createEffect,
  createSignal,
  type JSX,
  on,
  splitProps,
  useContext,
  type ValidComponent,
} from "solid-js";

import { cn } from "~/lib/utils";

// ── Animation constants (ssgoi snappy X provider inspired) ──
const SLIDE_PX = 30;
const SLIDE_DURATION = 250;
const SLIDE_EASING = "cubic-bezier(0.4, 0, 0.2, 1)";

// ── Direction context ──
// direction: 0 = initial (no anim), 1 = forward (right), -1 = backward (left)
interface TabsCtx {
  direction: () => number;
  registerValue: (value: string) => void;
}

const TabsContext = createContext<TabsCtx>();

// ── Tabs Root (wraps Kobalte Root to track slide direction) ──
function Tabs(props: ComponentProps<typeof TabsPrimitive.Root>) {
  const [direction, setDirection] = createSignal(0);
  const values: string[] = [];
  let prevValue = props.value ?? props.defaultValue;

  const registerValue = (value: string) => {
    if (!values.includes(value)) {
      values.push(value);
    }
  };

  const computeDirection = (old: string | undefined, next: string) => {
    if (old === undefined) return;
    const oldIdx = values.indexOf(old);
    const newIdx = values.indexOf(next);
    if (oldIdx >= 0 && newIdx >= 0) {
      setDirection(newIdx >= oldIdx ? 1 : -1);
    }
  };

  const handleChange = (newValue: string) => {
    computeDirection(prevValue, newValue);
    prevValue = newValue;
    props.onChange?.(newValue);
  };

  // Sync prevValue for controlled programmatic changes
  createEffect(
    on(
      () => props.value,
      (v) => {
        prevValue = v;
      },
      { defer: true },
    ),
  );

  return (
    <TabsContext.Provider value={{ direction, registerValue }}>
      <TabsPrimitive.Root {...props} onChange={handleChange} />
    </TabsContext.Provider>
  );
}

