# Research Request: SolidJS `useContext` resolves inside child component but `ref` callback never fires after tab change (Kobalte Tabs + WAAPI slide animation)

## The Objective & Core Issue

I'm building a reusable Tabs component (`src/components/ui/tabs.tsx`) that wraps Kobalte's `@kobalte/core/tabs` to add directional slide animation via the Web Animations API (WAAPI). When the user switches tabs, the new `TabsContent` panel should slide in from the left or right depending on tab order.

The problem: **The `ref` callback on `TabsContent` fires correctly on initial render, but does NOT fire when the tab value changes and Kobalte's `<Show when={present()}>` mounts the new content panel.** The animation never runs.

Critically, I have confirmed via `console.log` that:
1. `useContext(TabsContext)` resolves correctly inside `TabsContent` — context is NOT the issue.
2. `ctx.direction()` reads as `1` (forward) after the first tab click — direction tracking works.
3. `el.animate` exists as a function on the element when the ref fires on initial render.
4. The WAAPI mock captures the animation call on initial render (when I remove the `dir === 0` guard).

But after a tab CHANGE (clicking a trigger), the ref callback simply never executes for the newly-mounted content panel, so no animation plays. The tests that assert `findSlideCall()` is truthy after a click all fail.

## Relevant Code Snippets

### 1. The Tabs component (`src/components/ui/tabs.tsx`) — CURRENT STATE
```tsx
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import * as TabsPrimitive from "@kobalte/core/tabs";
import {
  createContext,
  createEffect,
  createSignal,
  type JSX,
  on,
  splitProps,
  useContext,
  type ValidComponent,
} from "solid-js";

import { cn } from "~/lib/utils";

// ── Animation constants (ssgoi snappy X provider inspired) ──
const SLIDE_PX = 30;
const SLIDE_DURATION = 250;
const SLIDE_EASING = "cubic-bezier(0.4, 0, 0.2, 1)";

// ── Direction context ──
// direction: 0 = initial (no anim), 1 = forward (right), -1 = backward (left)
interface TabsCtx {
  direction: () => number;
  registerValue: (value: string) => void;
}

const TabsContext = createContext<TabsCtx>();

// ── Tabs Root (wraps Kobalte Root to track slide direction) ──
function Tabs(props: ComponentProps<typeof TabsPrimitive.Root>) {
  const [direction, setDirection] = createSignal(0);
  const values: string[] = [];
  let prevValue = props.value ?? props.defaultValue;

  const registerValue = (value: string) => {
    if (!values.includes(value)) {
      values.push(value);
    }
  };

  const computeDirection = (old: string | undefined, next: string) => {
    if (old === undefined) return;
    const oldIdx = values.indexOf(old);
    const newIdx = values.indexOf(next);
    if (oldIdx >= 0 && newIdx >= 0) {
      setDirection(newIdx >= oldIdx ? 1 : -1);
    }
  };

  const handleChange = (newValue: string) => {
    computeDirection(prevValue, newValue);
    prevValue = newValue;
    props.onChange?.(newValue);
  };

  createEffect(
    on(
      () => props.value,
      (v) => {
        prevValue = v;
      },
      { defer: true },
    ),
  );

  const ctx = { direction, registerValue };

  return (
    <TabsContext.Provider value={ctx}>
      <TabsPrimitive.Root {...props} onChange={handleChange} />
    </TabsContext.Provider>
  );
}

type TabsListProps<T extends ValidComponent = "div"> =
  TabsPrimitive.TabsListProps<T> & {
    class?: string | undefined;
  };

const TabsList = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TabsListProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsListProps, ["class"]);
  return (
    <TabsPrimitive.List
      class={cn("flex items-center", local.class)}
      {...others}
    />
  );
};

type TabsTriggerProps<T extends ValidComponent = "button"> =
  TabsPrimitive.TabsTriggerProps<T> & {
    class?: string | undefined;
  };

const TabsTrigger = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, TabsTriggerProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsTriggerProps, ["class"]);
  const ctx = useContext(TabsContext);
  if (ctx && props.value) {
    ctx.registerValue(props.value);
  }
  return (
    <TabsPrimitive.Trigger
      class={cn(
        "z-10 inline-flex items-center justify-center whitespace-nowrap px-3 py-3 font-medium text-body-sm text-muted-foreground transition-colors duration-standard ease-standard hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-2 data-[selected]:text-foreground",
        local.class,
      )}
      {...others}
    />
  );
};

type TabsContentProps<T extends ValidComponent = "div"> =
  TabsPrimitive.TabsContentProps<T> & {
    class?: string | undefined;
  };

const TabsContent = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TabsContentProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsContentProps, ["class", "ref"]);
  const ctx = useContext(TabsContext);

  const animateSlide = (el: HTMLElement) => {
    const dir = ctx?.direction() ?? 0;
    if (dir === 0) return;
    el.animate(
      [
        {
          opacity: 0,
          transform: `translate3d(${dir * SLIDE_PX}px, 0, 0)`,
        },
        { opacity: 1, transform: "translate3d(0, 0, 0)" },
      ],
      {
        duration: SLIDE_DURATION,
        easing: SLIDE_EASING,
        fill: "forwards",
      },
    );
  };

  return (
    <TabsPrimitive.Content
      class={cn("outline-none", local.class)}
      ref={animateSlide}
      {...others}
    />
  );
};

type TabsIndicatorProps<T extends ValidComponent = "div"> =
  TabsPrimitive.TabsIndicatorProps<T> & {
    class?: string | undefined;
  };

const TabsIndicator = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TabsIndicatorProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsIndicatorProps, ["class"]);
  return (
    <TabsPrimitive.Indicator
      class={cn(
        "absolute transition-all duration-standard ease-[cubic-bezier(0.32,0.72,0,1)] data-[orientation=vertical]:-right-px data-[orientation=horizontal]:-bottom-px data-[orientation=horizontal]:h-0.5 data-[orientation=vertical]:w-0.5",
        local.class,
      )}
      {...others}
    />
  );
};

export { Tabs, TabsContent, TabsIndicator, TabsList, TabsTrigger };
```

### 2. Kobalte's TabsContent source (from node_modules, for reference)
