const TabsContext = createContext<TabsCtx>();

// ── Tabs Root (wraps Kobalte Root to track slide direction + selection) ──
function Tabs(props: ComponentProps<typeof TabsPrimitive.Root>) {
  const [direction, setDirection] = createSignal(0);
  const [currentSelected, setCurrentSelected] = createSignal(
    props.value ?? props.defaultValue ?? "",
  );
  const values: string[] = [];
  let prevValue = props.value ?? props.defaultValue ?? "";

  const registerValue = (value: string) => {
    if (!values.includes(value)) {
      values.push(value);
    }
  };

  const computeDirection = (old: string, next: string) => {
    const oldIdx = values.indexOf(old);
    const newIdx = values.indexOf(next);
    if (oldIdx >= 0 && newIdx >= 0) {
      setDirection(newIdx >= oldIdx ? 1 : -1);
    }
  };

  const handleChange = (newValue: string) => {
    computeDirection(prevValue, newValue);
    prevValue = newValue;
    setCurrentSelected(newValue);
    props.onChange?.(newValue);
  };

  createEffect(
    on(
      () => props.value,
      (v) => {
        if (v !== undefined && v !== prevValue) {
          computeDirection(prevValue, v);
          prevValue = v;
          setCurrentSelected(v);
        }
      },
      { defer: true },
    ),
  );

  return (
    <TabsContext.Provider value={{ direction, currentSelected, registerValue }}>
      <TabsPrimitive.Root {...props} onChange={handleChange} />
    </TabsContext.Provider>
  );
}

type TabsListProps<T extends ValidComponent = "div"> =
  TabsPrimitive.TabsListProps<T> & {
    class?: string | undefined;
  };

const TabsList = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TabsListProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsListProps, ["class"]);
  return (
    <TabsPrimitive.List
      class={cn("flex items-center", local.class)}
      {...others}
    />
  );
};

type TabsTriggerProps<T extends ValidComponent = "button"> =
  TabsPrimitive.TabsTriggerProps<T> & {
    class?: string | undefined;
  };

const TabsTrigger = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, TabsTriggerProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsTriggerProps, ["class"]);
  const ctx = useContext(TabsContext);
  if (ctx && props.value) {
    ctx.registerValue(props.value);
  }
  return (
    <TabsPrimitive.Trigger
      class={cn(
        "z-10 inline-flex items-center justify-center whitespace-nowrap px-3 py-3 font-medium text-body-sm text-muted-foreground transition-colors duration-standard ease-standard hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-2 data-[selected]:text-foreground",
        local.class,
      )}
      {...others}
    />
  );
};

type TabsContentProps<T extends ValidComponent = "div"> =
  TabsPrimitive.TabsContentProps<T> & {
    class?: string | undefined;
  };

const TabsContent = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TabsContentProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsContentProps, ["class"]);
  const ctx = useContext(TabsContext);
  const [el, setEl] = createSignal<HTMLElement>();

  // forceMount keeps all panels in DOM (refs fire once on initial render).
  // createEffect watches ctx.currentSelected() — when THIS panel becomes
  // active and direction != 0, run WAAPI slide animation.
  // This bypasses the <Show> node-recycling issue entirely.
  createEffect(
    on(
      () => ctx?.currentSelected(),
      (selected) => {
        if (!selected || selected !== props.value) return;
        const dir = ctx?.direction() ?? 0;
        if (dir === 0) return;
        const target = el();
        if (!target) return;
        target.animate(
          [
            {
              opacity: 0,
              transform: `translate3d(${dir * SLIDE_PX}px, 0, 0)`,
            },
            { opacity: 1, transform: "translate3d(0, 0, 0)" },
          ],
          {
            duration: SLIDE_DURATION,
            easing: SLIDE_EASING,
            fill: "forwards",
          },
        );
      },
      { defer: true },
    ),
  );

  return (
    <TabsPrimitive.Content
      forceMount
      class={cn(
        "hidden data-[selected]:block outline-none",
        local.class,
      )}
      ref={setEl}
      {...others}
    />
  );
};

type TabsIndicatorProps<T extends ValidComponent = "div"> =
  TabsPrimitive.TabsIndicatorProps<T> & {
    class?: string | undefined;
  };

const TabsIndicator = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TabsIndicatorProps<T>>,
) => {
  const [local, others] = splitProps(props as TabsIndicatorProps, ["class"]);
  return (
    <TabsPrimitive.Indicator
      class={cn(
        "absolute transition-all duration-standard ease-[cubic-bezier(0.32,0.72,0,1)] data-[orientation=vertical]:-right-px data-[orientation=horizontal]:-bottom-px data-[orientation=horizontal]:h-0.5 data-[orientation=vertical]:w-0.5",
        local.class,
      )}
      {...others}
    />
  );
};

export { Tabs, TabsContent, TabsIndicator, TabsList, TabsTrigger };

import type { JSX } from "solid-js";
import { fireEvent, render, screen } from "@solidjs/testing-library";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  Tabs,
  TabsContent,
  TabsIndicator,
  TabsList,
  TabsTrigger,
} from "../tabs";

// ── matchMedia mock ──
let mockMatches: Record<string, boolean> = {};
const MIN_WIDTH_RE = /\(min-width:\s*([\d.]+)px\)/;

const mockMatchMedia = (query: string): MediaQueryList => {
  const match = query.match(MIN_WIDTH_RE);
  const threshold = match
    ? Number.parseFloat(match[1])
    : Number.POSITIVE_INFINITY;
  const matches = mockMatches[`${threshold}`] ?? false;
  return {
    matches,
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    addListener: vi.fn(),
    removeListener: vi.fn(),
    dispatchEvent: vi.fn(),
  } as unknown as MediaQueryList;
};

// ── ResizeObserver mock ──
class MockResizeObserver {
  observe = vi.fn();
  unobserve = vi.fn();
  disconnect = vi.fn();
}
globalThis.ResizeObserver =
  MockResizeObserver as unknown as typeof ResizeObserver;

// ── WAAPI mock — element.animate doesn't exist in jsdom ──
const animateMock = vi.fn();
let animateCalls: { keyframes: Keyframe[]; options: object }[] = [];

beforeEach(() => {
  mockMatches = {};
  window.matchMedia = vi.fn().mockImplementation(mockMatchMedia);

  animateCalls = [];
  animateMock.mockImplementation((keyframes: Keyframe[], options: object) => {
    animateCalls.push({ keyframes, options });
    return { cancel: vi.fn(), onfinish: null, finished: Promise.resolve() };
  });
  Object.defineProperty(HTMLElement.prototype, "animate", {
    configurable: true,
    writable: true,
    value: animateMock,
  });
});

afterEach(() => {
  mockMatches = {};
});

const RIGHT_OFFSET_RE = /translate3d\(\s*[\d]/;
const LEFT_OFFSET_RE = /translate3d\(\s*-/;

/** Find the slide animation call (has translate3d in keyframes). */
const findSlideCall = ():
  | { keyframes: Keyframe[]; options: object }
  | undefined =>
  animateCalls.find(
    (c) =>
      typeof c.keyframes?.[0]?.transform === "string" &&
      c.keyframes[0].transform.includes("translate3d"),
  );

function renderTabs(props?: {
  defaultValue?: string;
  onChange?: (v: string) => void;
}) {
  render(() => (
    <Tabs
      defaultValue={props?.defaultValue ?? "a"}
      onChange={props?.onChange}
    >
      <TabsList>
        <TabsTrigger value="a">Alpha</TabsTrigger>
        <TabsTrigger value="b">Beta</TabsTrigger>
        <TabsTrigger value="c">Gamma</TabsTrigger>
        <TabsIndicator />
      </TabsList>
      <TabsContent value="a" data-testid="panel-a">
        <div data-testid="content-a">A</div>
      </TabsContent>
      <TabsContent value="b" data-testid="panel-b">
        <div data-testid="content-b">B</div>
      </TabsContent>
      <TabsContent value="c" data-testid="panel-c">
        <div data-testid="content-c">C</div>
      </TabsContent>
    </Tabs>
  ));
}

describe("Tabs WAAPI slide animation", () => {
  /** Click a tab and flush SolidJS reactive effects. */
  const clickTab = (label: string) => {
    fireEvent.click(screen.getByText(label));
  };

  it("does NOT animate on initial render", () => {
    renderTabs();
    expect(animateCalls.length).toBe(0);
  });

  it("animates content on FIRST tab change", () => {
    renderTabs();

    clickTab("Beta");

    expect(findSlideCall()).toBeTruthy();
  });

  it("slides from the RIGHT when moving to a higher index", () => {
    renderTabs();

    clickTab("Beta");

    const slide = findSlideCall();
    expect(slide).toBeTruthy();
    const firstTransform = slide!.keyframes[0].transform as string;
    expect(firstTransform).toMatch(RIGHT_OFFSET_RE);
  });

  it("slides from the LEFT when moving to a lower index", () => {
    renderTabs();

    // a → c (right)
    clickTab("Gamma");
    animateCalls = [];

    // c → a (left)
    clickTab("Alpha");

    const slide = findSlideCall();
    expect(slide).toBeTruthy();
    const firstTransform = slide!.keyframes[0].transform as string;
    expect(firstTransform).toMatch(LEFT_OFFSET_RE);
  });

  it("uses fill: forwards", () => {
    renderTabs();

    clickTab("Beta");

    const slide = findSlideCall();
    expect(slide).toBeTruthy();
    expect(slide!.options).toMatchObject({ fill: "forwards" });
  });

  it("still calls consumer onChange", () => {
    const onChange = vi.fn();
    renderTabs({ onChange });

    clickTab("Beta");

    expect(onChange).toHaveBeenCalledWith("b");
  });

  it("renders all panels with forceMount (hidden when not selected)", () => {
    renderTabs();

    // All three panels exist in DOM
    expect(screen.getByTestId("panel-a")).toBeTruthy();
    expect(screen.getByTestId("panel-b")).toBeTruthy();
    expect(screen.getByTestId("panel-c")).toBeTruthy();
  });
});

