import type { VariantProps } from "class-variance-authority";
import { cva } from "class-variance-authority";
import type { JSX } from "solid-js";
import { splitProps } from "solid-js";
import { cn } from "~/lib/utils";

/**
 * Tab — a segmented-control button with a STABLE border box.
 *
 * Both `active` and `inactive` share the same border width from `shape`, so
 * toggling a tab never causes layout shift. The active state swaps fill/border
 * color + adds elevation; inactive is a bordered card chip.
 *
 * `tone` controls the active color scheme:
 *   primary — solid canopy fill (default)
 *   accent  — lime soft fill (canopy-on-lime, ≈10.76:1 both themes)
 */
export const tabVariants = cva(
  "flex shrink-0 cursor-pointer items-center border-2 font-semibold text-[13px] transition duration-150",
  {
    variants: {
      variant: {
        inactive:
          "border-border bg-card text-muted-foreground hover:border-primary/20 hover:text-foreground",
        active: "",
      },
      tone: {
        primary: "",
        accent: "",
      },
      shape: {
        rounded: "gap-2 whitespace-nowrap rounded-2xl px-[18px] py-2.5",
        pill: "rounded-full px-4 py-[7px]",
      },
    },
    compoundVariants: [
      {
        variant: "active",
        tone: "primary",
        class:
          "border-primary bg-primary text-primary-foreground shadow-card dark:bg-accent-soft dark:text-primary",
      },
      {
        variant: "active",
        tone: "accent",
        class: "border-primary bg-accent-soft text-primary shadow-card",
      },
    ],
    defaultVariants: {
      variant: "inactive",
      tone: "primary",
      shape: "rounded",
    },
  }
);

export interface TabButtonProps {
  readonly active?: boolean;
  readonly "aria-label"?: string;
  readonly children: JSX.Element;
  readonly class?: string;
  readonly onClick: () => void;
  readonly shape?: VariantProps<typeof tabVariants>["shape"];
  readonly tone?: VariantProps<typeof tabVariants>["tone"];
}

export const TabButton = (props: TabButtonProps) => {
  const [local, others] = splitProps(props, [
    "active",
    "shape",
    "tone",
    "class",
    "children",
  ]);
  return (
    <button
      class={cn(
        tabVariants({
          variant: local.active ? "active" : "inactive",
          shape: local.shape,
          tone: local.tone,
        }),
        local.class
      )}
      type="button"
      {...others}
    >
      {local.children}
    </button>
  );
};

content.thinking:
The user wants me to support ALL the variants from `tab.tsx` in the Tabs component. Let me understand what `tab.tsx` has:

- `variant`: `inactive` | `active` (but in the context of a trigger, this is handled by `data-[selected]`)
- `tone`: `primary` | `accent` (controls active color scheme)
- `shape`: `rounded` (rounded-2xl) | `pill` (rounded-full)

So in the Tabs component, the pill variant should support:
- The `tone` variant (primary/accent for selected state)
- The `shape` variant (rounded/pill)
- The underline variant (the existing full-width one)

The tricky part: `tab.tsx` uses `variant: active/inactive` to toggle between states, but in the Tabs component, this is handled by `data-[selected]`. So I need to map the tab.tsx approach to `data-[selected]` selectors.

Let me think about how to structure this. The `tabVariants` has:
- Base: `flex shrink-0 cursor-pointer items-center border-2 font-semibold text-[13px] transition duration-150`
- variant (inactive): `border-border bg-card text-muted-foreground hover:border-primary/20 hover:text-foreground`
- compound active+primary: `border-primary bg-primary text-primary-foreground shadow-card dark:bg-accent-soft dark:text-primary`
- compound active+accent: `border-primary bg-accent-soft text-primary shadow-card`
- shape rounded: `gap-2 whitespace-nowrap rounded-2xl px-[18px] py-2.5`
- shape pill: `rounded-full px-4 py-[7px]`

In the Tabs component, `variant: active/inactive` becomes `data-[selected]` CSS. So the approach is:

1. `underline` variant: full-width, no border, underline indicator
2. `pill` variant: maps to the tab.tsx pill style, using `data-[selected]` for active state

For the pill variant in Tabs, I need to translate the `variant` + `tone` + `shape` from tab.tsx into `data-[selected]` based CSS. The `tone` and `shape` should still be configurable.

Let me create a cva that has:
- `variant`: `underline` | `pill`
- For the pill variant, `tone` (primary/accent) and `shape` (rounded/pill) map to different visual styles
- The active state is handled via `data-[selected]` rather than `variant: active/inactive`

Actually, looking at this more carefully, I think the cleanest approach is:

```tsx
export const tabsTriggerVariants = cva(
  "inline-flex cursor-pointer items-center transition focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-2",
  {
    variants: {
      variant: {
        // underline = full-width text tabs with indicator
        underline: "z-10 flex-1 justify-center px-3 py-3 font-medium text-body-sm text-muted-foreground duration-standard ease-standard hover:text-foreground data-[selected]:text-foreground",
        // pill = compact button-style chips from tab.tsx
        pill: "shrink-0 border-2 font-semibold text-[13px] duration-150",
      },
      tone: {
        primary: "",
        accent: "",
      },
      shape: {
        rounded: "",
        pill: "",
      },
    },
    compoundVariants: [
      // pill variant + shapes (only apply when variant is pill)
      {
        variant: "pill",
        shape: "rounded",
        class: "gap-2 whitespace-nowrap rounded-2xl px-[18px] py-2.5",
      },
      {
        variant: "pill",
        shape: "pill",
        class: "rounded-full px-4 py-[7px]",
      },
      // pill variant + inactive state (default)
      {
        variant: "pill",
        class: "border-border bg-card text-muted-foreground hover:border-primary/20 hover:text-foreground data-[selected]:border-primary data-[selected]:shadow-card",
      },
      // pill variant + primary tone + selected state
      {
        variant: "pill",
        tone: "primary",
        class: "data-[selected]:bg-primary data-[selected]:text-primary-foreground dark:data-[selected]:bg-accent-soft dark:data-[selected]:text-primary",
      },
      // pill variant + accent tone + selected state
      {
        variant: "pill",
        tone: "accent",
        class: "data-[selected]:bg-accent-soft data-[selected]:text-primary",
      },
    ],
    defaultVariants: {
      variant: "underline",
      tone: "primary",
      shape: "rounded",
    },
  }
);
```

This way:
- `underline` variant ignores `tone` and `shape` (they have no compound variants)
- `pill` variant uses all three dimensions from tab.tsx
- `data-[selected]` handles the active/inactive toggle automatically

