const [search, setSearch] = createSignal("");
const [filter, setFilter] = createSignal<FilterKey>("all");

// WAAPI fade+slide on the list container when the filter changes.
// Direction comes from FILTER_TABS order (same pattern as tab slide).
let prevFilter = "all";
let listEl: HTMLDivElement | undefined;

const FILTER_ORDER: readonly string[] = FILTER_TABS.map((t) => t.key);

const animateList = () => {
  if (!listEl) return;
  listEl.animate(
    [
      { opacity: 0, transform: "translate3d(0, 8px, 0)" },
      { opacity: 1, transform: "translate3d(0, 0, 0)" },
    ],
    {
      duration: 200,
      easing: "cubic-bezier(0.4, 0, 0.2, 1)",
      fill: "forwards",
    },
  );
};

createEffect(
  on(filter, (newFilter) => {
    // Skip initial render
    if (prevFilter === newFilter) return;
    prevFilter = newFilter;
    animateList();
  }, { defer: true }),
);

