// ── Trigger variants (Kobalte TabsTrigger) ──
// Mirrors TabButton styling: `tone` + `shape` apply only to `pill` variant.
// Active/inactive toggle uses `data-[selected]` (Kobalte sets it automatically).
export const tabsTriggerVariants = cva(
  "inline-flex cursor-pointer items-center transition focus-visible:outline-2 focus-visible:outline-ring focus-visible:outline-offset-2",
  {
    variants: {
      variant: {
        underline:
