import { A, useNavigate } from "@solidjs/router";
import { createSignal } from "solid-js";
import { toast } from "solid-sonner";
import { ArrowLeftIcon, CartShoppingIcon } from "~/assets";
import { SearchBar } from "~/components/search-bar";
import { FadeIn } from "~/components/ui/fade-in";
import {
  Sheet,
  SheetBody,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "~/components/ui/sheet";
import { cashRegisterProducts as products } from "~/lib/data/transactions";
import { formatRupiah } from "~/lib/utils";
import { CartList } from "./components/cart-list";
import { CartPanel } from "./components/cart-panel";
import { CartTotals } from "./components/cart-totals";
import { type CategoryKey, CategoryTabs } from "./components/category-tabs";
import { ProductGrid } from "./components/product-grid";
import type { CartEntry } from "./components/types";

export default function CashRegisterPage() {
  const navigate = useNavigate();
  const [activeCat, setActiveCat] = createSignal<CategoryKey>("minuman");
  const [search, setSearch] = createSignal("");
  const [cart, setCart] = createSignal<CartEntry[]>([]);
  const [sheetOpen, setSheetOpen] = createSignal(false);

  const filtered = () =>
    products.filter((p) => {
      const catOk = p.cat === activeCat();
      const searchOk =
        !search() || p.name.toLowerCase().includes(search().toLowerCase());
      return catOk && searchOk;
    });

  const addToCart = (id: number) => {
    setCart((prev) => {
      const existing = prev.find((c) => c.id === id);
      if (existing) {
        return prev.map((c) => (c.id === id ? { ...c, qty: c.qty + 1 } : c));
      }
      return [...prev, { id, qty: 1 }];
    });
  };

  const increment = (id: number) =>
    setCart((prev) =>
      prev.map((c) => (c.id === id ? { ...c, qty: c.qty + 1 } : c))
    );

  const decrement = (id: number) =>
    setCart((prev) => {
      const item = prev.find((c) => c.id === id);
      if (item && item.qty <= 1) {
        return prev.filter((c) => c.id !== id);
      }
      return prev.map((c) => (c.id === id ? { ...c, qty: c.qty - 1 } : c));
    });

  const cartTotal = () =>
    cart().reduce((s, c) => {
      const p = products.find((pr) => pr.id === c.id);
      return s + (p ? p.price * c.qty : 0);
    }, 0);

  const cartItemCount = () => cart().reduce((s, c) => s + c.qty, 0);

  return (
    <div
      class="flex h-screen bg-muted font-sans text-foreground antialiased"
      data-ssgoi-transition="/transactions/cash-register"
    >
      {/* Left column — catalog */}
      <div class="flex min-h-0 flex-1 flex-col overflow-hidden bg-background">
        <FadeIn
          class="flex h-14 shrink-0 items-center justify-between gap-3.5 border-border border-b bg-card px-3.5 lg:px-5"
          duration={0.4}
          x={-20}
        >
          <div class="flex shrink-0 items-center gap-3.5">
            <A
              aria-label="Kembali"
              class="grid h-[38px] w-[38px] place-items-center rounded-xl border border-border bg-card text-foreground transition-colors duration-150 hover:border-primary/20 hover:bg-primary/5"
              href="/"
            >
              <ArrowLeftIcon class="size-5" />
            </A>
            <span class="hidden font-bold font-display text-body-lg text-foreground sm:block">
              Transaksi Baru
            </span>
          </div>
          <SearchBar
            class="w-40 sm:w-56 lg:w-72"
            mode="compact"
            onInput={setSearch}
            value={search()}
          />
        </FadeIn>

        <FadeIn
          class="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden p-3.5 pb-20 lg:gap-4 lg:p-5"
          delay={0.08}
          duration={0.45}
          y={16}
        >
          <CategoryTabs active={activeCat()} onSelect={setActiveCat} />
          <ProductGrid onAdd={addToCart} products={filtered()} />
        </FadeIn>
      </div>

      {/* Right column — cart sidebar (desktop only) */}
      <FadeIn
        class="hidden flex-col overflow-hidden border-border border-l bg-card lg:flex lg:w-[320px] lg:min-w-[320px] xl:w-[360px] xl:min-w-[360px]"
        delay={0.15}
        duration={0.45}
        x={40}
      >
        <CartPanel
          cart={cart()}
          onDecrement={decrement}
          onIncrement={increment}
          onPay={() => navigate("/transactions/payment")}
          onProcess={() => {
            toast.success("Transaksi disimpan & diproses");
            setCart([]);
          }}
          products={products}
        />
      </FadeIn>

      {/* Mobile cart drawer */}
      <Sheet
        onOpenChange={setSheetOpen}
        open={sheetOpen()}
        trigger={
          <SheetTrigger
            aria-label="Buka keranjang"
            class="fixed right-4 bottom-5 left-4 z-40 flex h-14 items-center justify-between rounded-2xl bg-primary px-5 font-semibold text-body-sm text-primary-foreground tracking-wide shadow-card transition duration-150 hover:-translate-y-0.5 hover:shadow-card-hover active:scale-[0.98] lg:hidden"
          >
            <div class="flex items-center gap-2.5">
              <CartShoppingIcon class="h-5 w-5" />
              <span class="grid min-w-[20px] place-items-center rounded-full bg-accent px-1.5 py-0 font-bold text-caption-sm text-primary tabular-nums">
                {cartItemCount()}
              </span>
              <span>Keranjang</span>
            </div>
            <span class="font-bold text-body tabular-nums">
              {formatRupiah(cartTotal())}
            </span>
          </SheetTrigger>
        }
      >
        {({ close }) => (
          <>
            <SheetHeader>
              <SheetTitle>Keranjang</SheetTitle>
            </SheetHeader>

            <SheetBody>
              <CartList
                cart={cart()}
                onDecrement={decrement}
                onIncrement={increment}
                products={products}
              />
            </SheetBody>

            <CartTotals
              disabled={cart().length === 0}
              onPay={() => {
                close();
                navigate("/transactions/payment");
              }}
              onProcess={() => {
                close();
                toast.success("Transaksi disimpan & diproses");
                setCart([]);
              }}
              subtotal={cartTotal()}
            />
          </>
        )}
      </Sheet>
    </div>
  );
}

import { For } from "solid-js";
import { TabButton } from "~/components/ui/tabs";

export type CategoryKey = "minuman" | "makanan" | "snack" | "dessert" | "paket";

interface CatTab {
  readonly key: CategoryKey;
  readonly label: string;
}

export const categoryTabs: readonly CatTab[] = [
  { key: "minuman", label: "Minuman" },
  { key: "makanan", label: "Makanan" },
  { key: "snack", label: "Snack" },
  { key: "dessert", label: "Dessert" },
  { key: "paket", label: "Paket" },
] as const;

interface CategoryTabsProps {
  readonly active: CategoryKey;
  readonly onSelect: (key: CategoryKey) => void;
}

export const CategoryTabs = (props: CategoryTabsProps) => (
  <div class="scrollbar-none flex shrink-0 gap-2.5 overflow-x-auto pb-1">
    <For each={categoryTabs}>
      {(tab) => (
        <TabButton
          active={props.active === tab.key}
          aria-label={tab.label}
          class="px-8 py-4 text-body"
          onClick={() => props.onSelect(tab.key)}
        >
          {tab.label}
        </TabButton>
      )}
    </For>
  </div>
);

import { For, Show } from "solid-js";
import { PlusIcon } from "~/assets";
import { formatRupiah } from "~/lib/utils";
import type { Product } from "./types";

interface ProductGridProps {
  readonly onAdd: (id: number) => void;
  readonly products: readonly Product[];
}

export const ProductGrid = (props: ProductGridProps) => {
  return (
    <div class="scrollbar-none grid min-h-0 flex-1 grid-cols-2 content-start items-start gap-3.5 overflow-y-auto [grid-auto-rows:min-content] sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-[repeat(5,minmax(0,1fr))]">
      <Show
        fallback={
          <div class="col-[1/-1] py-16 text-center font-medium text-body-sm text-muted-foreground">
            Tidak ada menu ditemukan
          </div>
        }
        when={props.products.length > 0}
      >
        <For each={props.products}>
          {(p) => (
            <button
              aria-label={`${p.name} ${formatRupiah(p.price)}`}
              class="group relative aspect-square cursor-pointer overflow-hidden rounded-2xl bg-muted transition duration-200 hover:-translate-y-0.5 hover:shadow-card-hover active:scale-[0.97]"
              onClick={() => props.onAdd(p.id)}
              type="button"
            >
              <img
                alt={p.name}
                class="absolute inset-0 h-full w-full object-cover transition-transform duration-400 ease-out group-hover:scale-108"
                loading="lazy"
                src={`https://picsum.photos/id/${p.img}/400/400`}
              />

              {/* Gradient overlay */}
              <div class="absolute inset-0 z-10 bg-[linear-gradient(to_top,rgba(0,0,0,1)_0%,rgba(0,0,0,1)_15%,rgba(0,0,0,0.90)_35%,rgba(0,0,0,0.70)_50%,rgba(0,0,0,0.50)_65%,rgba(0,0,0,0.30)_78%,rgba(0,0,0,0.15)_88%,transparent_100%)]" />

              {/* Text */}
              <div class="absolute inset-x-0 bottom-0 z-20 flex flex-col gap-1.5 p-4">
                <div class="line-clamp-2 font-bold text-body text-white leading-[1.35] [text-shadow:0_1px_4px_rgba(0,0,0,0.5)]">
                  {p.name}
                </div>
                <div class="font-semibold text-body-sm text-white/90 tabular-nums tracking-snug [text-shadow:0_1px_3px_rgba(0,0,0,0.4)]">
                  {formatRupiah(p.price)}
                </div>
              </div>

              {/* Add badge (hover) */}
              <div class="absolute top-2.5 right-2.5 z-30 grid h-8 w-8 scale-50 place-items-center rounded-full bg-white/90 text-primary opacity-0 shadow-card transition duration-200 [transition-timing-function:cubic-bezier(0.34,1.56,0.64,1)] group-hover:scale-100 group-hover:opacity-100 dark:bg-accent">
                <PlusIcon class="h-4 w-4" />
              </div>
            </button>
          )}
        </For>
      </Show>
    </div>
  );
};

