import type { RouteSectionProps } from "@solidjs/router";
import { useLocation } from "@solidjs/router";
import { Show } from "solid-js";
import { SubPageShell } from "~/components/layout/sub-page-shell/sub-page-shell";
import { FadeIn } from "~/components/ui/fade-in";
import { useIsWide } from "~/lib/use-is-wide";
import { useOrientation } from "~/lib/use-orientation";
import { NAV_ITEMS, SettingsNavigationMenu } from "./components/settings-nav";

export default function SettingPage(props: RouteSectionProps) {
  const isPortrait = useOrientation();
  const isWide = useIsWide();
  const enable = () => !isPortrait();
  const location = useLocation();

  // Section sub-route? (e.g. /setting/general — not the bare /setting)
  const isSectionRoute = () => {
    const parts = location.pathname.split("/").filter(Boolean);
    return parts.length > 1 && parts[0] === "setting";
  };

  const sectionTitle = () => {
    const seg = location.pathname.split("/")[2];
    return NAV_ITEMS.find((i) => i.key === seg)?.label ?? "Pengaturan";
  };

  return (
    <Show
      fallback={
        /* ── Index route (mobile) or two-column layout (desktop) ── */
        <div
          class="scrollbar-none flex flex-1 flex-col gap-4 overflow-y-auto px-gutter pt-6 pb-28 lg:gap-5 lg:px-7 lg:pb-24"
          data-ssgoi-transition="/setting"
        >
          <FadeIn duration={0.35} enable={enable()} y={-8}>
            <h1 class="font-bold font-display text-foreground text-heading-sm">
              Pengaturan
            </h1>
            <p class="mt-0.5 text-body-sm text-muted-foreground tracking-wide">
              Kelola konfigurasi bisnis dan aplikasi Anda
            </p>
          </FadeIn>

          <div class="flex flex-col gap-6 lg:flex-row">
            <FadeIn delay={0.06} duration={0.45} enable={enable()} x={-30}>
              <SettingsNavigationMenu />
            </FadeIn>

            {/* Desktop only — section panel. Hidden below lg (nav is the menu). */}
            <Show when={isWide()}>
              <FadeIn
                class="flex min-w-0 flex-1 flex-col gap-6"
                delay={0.14}
                duration={0.5}
                enable={enable()}
                scale={0.97}
                x={24}
              >
                <Show keyed when={location.pathname}>
                  {(_) => (
                    <FadeIn
                      duration={0.35}
                      enable={enable()}
                      scale={0.98}
                      x={16}
                    >
                      {props.children}
                    </FadeIn>
                  )}
                </Show>
              </FadeIn>
            </Show>
          </div>
        </div>
      }
      when={!isWide() && isSectionRoute()}
    >
      {/* ── Mobile section route → full-screen SubPageShell ── */}
      <SubPageShell
        backHref="/setting"
        data-ssgoi-transition={location.pathname}
        title={sectionTitle()}
      >
        <div class="scrollbar-none flex-1 overflow-y-auto p-5 pb-28">
          {props.children}
        </div>
      </SubPageShell>
    </Show>
  );
}

import { createRoot, createSignal } from "solid-js";

/* ── Global viewport-width signal ──────────────────────────────────
   Matches the lg breakpoint (--breakpoint-lg: 56.25rem = 900px).
   Below 900px the layout is single-column and should use the mobile
   drill-in behavior regardless of physical orientation. */

const mql =
  typeof window === "undefined"
    ? null
    : window.matchMedia("(min-width: 56.25rem)");

const [isWide, setIsWide] = createRoot(() =>
  createSignal(mql?.matches ?? false)
);

if (mql) {
  mql.addEventListener("change", (e) => setIsWide(e.matches));
}

/** Returns true when viewport is ≥ 900px (lg breakpoint). */
export function useIsWide() {
  return isWide;
}

import { createBreakpoints } from "@solid-primitives/media";

/**
 * Reactive breakpoint monitor matching Tailwind v4 breakpoints.
 *
 * Tailwind config (theme.css): sm=600px, lg=900px, xl=1200px.
 * We add md=768px here for the AdaptiveDialog mode switch —
 * it's not a Tailwind class breakpoint, just a JS detection point.
 */
const BREAKPOINTS = {
  sm: "600px",
  md: "768px",
  lg: "900px",
  xl: "1200px",
} as const;

export type BreakpointKey = keyof typeof BREAKPOINTS;

/** Returns a reactive breakpoints object. Access `.md`, `.lg`, etc. */
export function useBreakpoints() {
  return createBreakpoints(BREAKPOINTS);
}

